let builtinPresetGenresCache = null;

function getBuiltinPresetGenres() {
    if (!builtinPresetGenresCache) builtinPresetGenresCache = buildBuiltinPresetGenres();
    return builtinPresetGenresCache;
}

/* Same v2 schema the preset Load / Copy schema path reads. */
function buildBuiltinPresetSchema(genreId, variantId) {
    const genre = getBuiltinPresetGenres().find(item => item.id === genreId);
    const variant = genre?.[variantId];
    if (!variant) return null;

    const stats = {};
    for (const stat of variant.stats) stats[stat.name] = structuredClone(stat);

    const state = {
        stats,
        custom: structuredClone(variant.custom || {}),
        customText: "",
        skills: [],
        inventory: structuredClone(variant.inventory || []),
        effects: []
    };

    return {
        format: CHARACTER_SCHEMA_FORMAT,
        version: CHARACTER_SCHEMA_VERSION,
        character: { name: "", key: "" },
        startingState: structuredClone(state),
        runtimeState: state
    };
}

function builtinPresetDisplayName(genreId, variantId) {
    const genre = getBuiltinPresetGenres().find(item => item.id === genreId);
    const variant = BUILTIN_PRESET_VARIANTS.find(item => item.id === variantId);
    return genre && variant ? `${csT(genre.name)} · ${csT(variant.label)}` : "";
}

globalThis.__csBuiltinPresetsForTests = {
    genres: () => getBuiltinPresetGenres(),
    variants: BUILTIN_PRESET_VARIANTS,
    build: (genreId, variantId) => buildBuiltinPresetSchema(genreId, variantId),
    load: (character, genreId, variantId, mode = "replace") =>
        pasteCharacterSchema(character, mode, JSON.stringify(buildBuiltinPresetSchema(genreId, variantId))),
    sectionHtml: open => builtinPresetSectionHtml(open),
    readOpen: count => readBuiltinPresetsOpen(count),
    writeOpen: open => writeBuiltinPresetsOpen(open)
};

/* The built-in section remembers being folded (per browser, like the
   presets themselves). Never chosen yet: open while the user has no
   presets of their own, folded once they do. */
const BUILTIN_PRESETS_OPEN_KEY = "character-state:builtin-presets-open:v1";

function readBuiltinPresetsOpen(ownPresetCount) {
    try {
        const stored = globalThis.localStorage?.getItem(BUILTIN_PRESETS_OPEN_KEY);
        if (stored === "1") return true;
        if (stored === "0") return false;
    } catch {
        /* storage blocked — fall back to the default */
    }
    return ownPresetCount === 0;
}

function writeBuiltinPresetsOpen(open) {
    try {
        globalThis.localStorage?.setItem(BUILTIN_PRESETS_OPEN_KEY, open ? "1" : "0");
    } catch {
        /* storage blocked — the choice lasts until the window closes */
    }
}

function builtinPresetSectionHtml(open = true) {
    const cards = getBuiltinPresetGenres().map(genre => `
        <div class="cs-builtin-preset">
            <div class="cs-builtin-preset-head">
                <span class="cs-builtin-preset-icon" aria-hidden="true">${genre.icon}</span>
                <b>${escapeHtml(csT(genre.name))}</b>
            </div>
            <div class="cs-builtin-preset-desc">${escapeHtml(csT(genre.description))}</div>
            <div class="cs-builtin-preset-actions">
                ${BUILTIN_PRESET_VARIANTS.map(variant => `
                    <button class="cs-chip${variant.id === "main" ? " cs-chip-accent" : ""}" type="button"
                        data-builtin-load="${genre.id}:${variant.id}"
                        title="${csH("{n} stats", { n: genre[variant.id].stats.length })}">${escapeHtml(csT(variant.label))} · ${genre[variant.id].stats.length}</button>`).join("")}
            </div>
        </div>`).join("");

    return `
        <details class="cs-builtin-presets"${open ? " open" : ""}>
            <summary>${csH("Built-in by genre")} <span class="cs-builtin-presets-hint">${csH("read-only · Load, adjust, then 💾 Save as your own")}</span></summary>
            <div class="cs-builtin-preset-grid">${cards}</div>
        </details>
        <div class="cs-builtin-presets-mine">${csH("Your presets")}</div>`;
}

function presetRowsHtml(presets) {
    if (!presets.length) {
        return `<div class="cs-log-empty">${csH("No presets saved yet. Type a name above and press 💾 Save current state.")}</div>`;
    }

    /* Display order: pinned entries first, then newest on top. Storage
       order is untouched (cap eviction still evicts the oldest save). */
    const sorted = presets
        .map(preset => preset)
        .filter(Boolean)
        .sort((a, b) => {
            const pinA = a.pinned ? 1 : 0;
            const pinB = b.pinned ? 1 : 0;

            if (pinA !== pinB) return pinB - pinA;

            return (b.pinnedAt || b.ts || 0) - (a.pinnedAt || a.ts || 0);
        });

    return sorted.map(preset => {
        const statCount = Object.keys(preset?.schema?.startingState?.stats || {}).length;
        const time = formatAuditTime(preset.ts);

        return `
            <div class="cs-log-row cs-preset-row${preset.pinned ? " cs-preset-pinned" : ""}">
                <span class="cs-log-main">
                    ${preset.pinned ? `<span title="${csH("Pinned to top")}">📌</span> ` : ""}
                    <b>${escapeHtml(preset.name || csT("Unnamed"))}</b>
                    <span style="color:#8e93b9;"> · ${csH("{n} stats", { n: statCount })} · ${csH("saved {time}", { time })}</span>
                </span>
                <button class="cs-chip${preset.pinned ? " cs-chip-accent" : " cs-chip-soft"}" type="button" data-preset-pin="${escapeHtml(preset.id)}" title="${preset.pinned ? csH("Unpin (back to time order)") : csH("Pin this preset to the top")}">📌</button>
                <button class="cs-chip" type="button" data-preset-load="${escapeHtml(preset.id)}">${csH("Load")}</button>
                <button class="cs-chip cs-chip-soft" type="button" data-preset-copy="${escapeHtml(preset.id)}" title="${csH("Copy preset schema to clipboard")}">${csH("Copy")}</button>
                <button class="cs-chip cs-chip-soft" type="button" data-preset-delete="${escapeHtml(preset.id)}" title="${csH("Delete this preset")}">🗑</button>
            </div>
        `;
    }).join("");
}

/*
 * Manual side NPC creation (user action — the AI can also create side
 * NPCs only on the user's explicit chat request via SIDE_NPC_CREATE).
 * Stats are seeded from the group/character schema with default values;
 * the AI can adjust them later through STATE_UPDATE.
 */
async function openSideNpcModal() {
    const context = SillyTavern.getContext();
    const existing = listSideNpcs(context);

    if (existing.length >= SIDE_NPC_MAX) {
        csToast.warning(csT("Side NPC limit reached ({n} per chat).", { n: SIDE_NPC_MAX }));
        return;
    }

    const schema = await buildUserSchemaFromGroup(context);
    const statCount = Object.keys(schema?.stats || {}).length;

    let driftNote = "";
    if (statCount) {
        try {
            const drift = await collectSchemaDrift(context);
            if (drift.length) {
                driftNote = `<div class="cs-drift-note">⚠ ${csH("Definition drift:")} ${drift.map(item =>
                    `${escapeHtml(item.name)} (${item.variants.map(variant =>
                        `${escapeHtml(variant.type)}${variant.optionCount ? ` · ${csH("{n} opts", { n: variant.optionCount })}` : ""} ×${variant.count}`
                    ).join(" vs ")}). ${csH("New NPCs get the majority definition — align cards via field Copy/Paste if that is wrong.")}`
                ).join("<br>")}</div>`;
            }
        } catch {
            /* drift check is best-effort */
        }
    }

    document.getElementById("cs-side-npc-modal-overlay")?.remove();

    const modal = document.createElement("div");
    modal.id = "cs-side-npc-modal-overlay";
    modal.className = "cs-log-overlay";

    modal.innerHTML = `
        <div class="cs-log-window" style="width:min(460px,94vw);">
            <div class="cs-log-header">
                <div class="cs-log-title">${csIcon("user-plus")} ${escapeHtml(csT("Side NPC"))}</div>
                <div class="cs-log-subtitle">${csH("Chat-local character — its data lives only in this chat")}</div>
            </div>
            <div class="cs-log-body" style="padding:16px 20px;">
                <div class="cs-form-group">
                    <label>${csH("Name")}</label>
                    <input id="cs-side-npc-name" class="text_pole" type="text" maxlength="60" placeholder="${csH("Guard, Merchant, ...")}" />
                </div>
                <div class="cs-settings-hint">
                    ${statCount
                        ? csH("{n} stat(s) will be seeded from the group/character schema with default values (Mod = 0). Edit them in the sheet or let the AI adjust them later.", { n: statCount })
                        : csH("No stat schema is available — an empty sheet will be created (add stats in the editor).")}
                    ${csH("Existing side NPCs: {names} · limit {n}.", { names: existing.length ? existing.map(entry => entry.name).join(", ") : csT("none"), n: SIDE_NPC_MAX })}
                    ${driftNote}
                </div>
            </div>
            <div class="cs-log-footer">
                <button class="cs-chip cs-chip-accent" id="cs-side-npc-create-btn" type="button">＋ ${csH("Create")}</button>
                <button class="cs-chip cs-chip-soft" id="cs-side-npc-cancel-btn" type="button">${csH("Cancel")}</button>
            </div>
        </div>
    `;

    document.body.appendChild(modal);

    modal.querySelector("#cs-side-npc-cancel-btn")?.addEventListener("click", () => modal.remove());

    modal.addEventListener("click", event => {
        if (event.target === modal) modal.remove();
    });

    modal.querySelector("#cs-side-npc-create-btn")?.addEventListener("click", async () => {
        const name = String(modal.querySelector("#cs-side-npc-name")?.value || "").trim();

        if (!name || name.length > 60 || name.includes("|")) {
            csToast.error("Side NPC name must be 1-60 characters (no | character).");
            return;
        }

        if (findSideNpcByName(context, name)) {
            const entryKey = sideNpcKeyFor(name);
            const liveState = context.chatMetadata?.character_states?.[entryKey];

            if (liveState && typeof liveState === "object") {
                csToast.error(csT("A side NPC named \"{name}\" already exists in this chat.", { name }));
                return;
            }

            /* Registry entry without a live state (previously AI-deleted):
               recreating the same name rebinds the key. */
        }

        if (findCharacterByName(name)) {
            csToast.error(csT("\"{name}\" is already a Character Card — side NPCs must have unique names.", { name }));
            return;
        }

        if (listSideNpcs(context).length >= SIDE_NPC_MAX) {
            csToast.error(csT("Side NPC limit reached ({n} per chat).", { n: SIDE_NPC_MAX }));
            return;
        }

        const schema = await buildUserSchemaFromGroup(context);
        const state = createUserStateFromSchema(schema || { stats: {} });

        const key = sideNpcKeyFor(name);

        if (!context.chatMetadata.character_states ||
            typeof context.chatMetadata.character_states !== "object" ||
            Array.isArray(context.chatMetadata.character_states)) {
            context.chatMetadata.character_states = {};
        }

    const normalizedState = normalizeRuntimeState(state);

    /* v2.0.20: a save with ZERO stat rows is a deliberate wipe — mark it
       so the stale-empty repair in ensureCharacterState (which re-seeds
       an empty runtime from the Character Card defaults) does not
       resurrect the deleted sheet on the next pipeline pass. */
    if (Object.keys(normalizedState.stats).length) {
        delete normalizedState.statsCleared;
    } else {
        normalizedState.statsCleared = true;
    }

    context.chatMetadata.character_states[key] = normalizedState;

        const registry = Array.isArray(context.chatMetadata[SIDE_NPC_REGISTRY_KEY])
            ? context.chatMetadata[SIDE_NPC_REGISTRY_KEY]
            : [];

        registry.push({ key, name, createdAt: Date.now() });
        context.chatMetadata[SIDE_NPC_REGISTRY_KEY] = registry;

        pushWholeAudit(context, key, "manual", "create");

        await saveChatState(context);

        csToast.success(csT("Side NPC \"{name}\" created ({n} stats) — chat-local only.", { name, n: Object.keys(state.stats).length }));
        modal.remove();
        await openCharacterSheet("view", makeSideNpcEntity({ key, name, createdAt: Date.now() }));
    });

    modal.addEventListener("click", event => {
        if (event.target === modal) modal.remove();
    });
}

/* ---- Scenes manager (A2): switch the ACTIVE scene / create by hand --- */

function openScenesModal() {
    const context = SillyTavern.getContext();

    document.getElementById("cs-scenes-overlay")?.remove();

    const modal = document.createElement("div");
    modal.id = "cs-scenes-overlay";
    modal.className = "cs-log-overlay";

    const renderBody = () => {
        const scenes = listScenes(context);
        const activeKey = getActiveSceneKey(context);
        const body = modal.querySelector("#cs-scenes-body");

        if (!body) return;

        const rows = scenes.map(scene => `
            <div class="cs-scene-row">
                <span class="cs-scene-name">${scene.key === activeKey ? "📍" : "⬜"} ${escapeHtml(scene.name)}</span>
                <span class="cs-scene-info">${csH("{n} fields", { n: Object.keys(scene.data || {}).length })}</span>
                <button class="cs-chip ${scene.key === activeKey ? "" : "cs-chip-accent"} cs-scene-switch-btn" data-key="${escapeHtml(scene.key)}" type="button">
                    ${scene.key === activeKey ? csH("Active") : csH("Set active")}
                </button>
                <button class="cs-chip cs-scene-delete-btn" data-key="${escapeHtml(scene.key)}" type="button" title="${csH("Delete this scene (chat-local only)")}">🗑</button>
            </div>
        `).join("");

        body.innerHTML = scenes.length ? rows : `<div class="cs-log-empty">${csH("No scenes yet. Create one below, or ask the AI in chat (it only creates scenes when you explicitly request it).")}</div>`;
    };

    modal.innerHTML = `
        <div class="cs-log-window" style="width:min(560px,94vw);">
            <div class="cs-log-header">
                <div class="cs-log-title">${csIcon("clapperboard")} ${escapeHtml(csT("Scenes"))}</div>
                <div class="cs-log-subtitle">${csH("Chat-local scene entities — the ACTIVE scene is injected into the AI prompt")}</div>
            </div>
            <div class="cs-log-body" id="cs-scenes-body"></div>
            <div class="cs-log-footer">
                <input id="cs-scene-name" class="text_pole" type="text" maxlength="60" placeholder="${csH("Scene name…")}" style="flex:1;" />
                <button class="cs-chip cs-chip-accent" id="cs-scene-create-btn" type="button">＋ ${csH("Create")}</button>
                <button class="cs-chip cs-chip-soft" id="cs-scenes-close-btn" type="button">${csH("Close")}</button>
            </div>
        </div>
    `;

    document.body.appendChild(modal);
    renderBody();

    modal.querySelector("#cs-scene-create-btn")?.addEventListener("click", async () => {
        const name = String(modal.querySelector("#cs-scene-name")?.value || "").trim();

        if (!name || name.length > 60 || name.includes("|")) {
            csToast.error("Scene name must be 1-60 characters (no | character).");
            return;
        }

        if (findSceneByName(context, name)) {
            csToast.error(csT("A scene named \"{name}\" already exists in this chat.", { name }));
            return;
        }

        if (findCharacterByName(name) || findSideNpcByName(context, name)) {
            csToast.error(csT("\"{name}\" is already used by a character — scenes need unique names.", { name }));
            return;
        }

        const key = sceneKeyFor(name);

        if (!context.chatMetadata.character_states ||
            typeof context.chatMetadata.character_states !== "object" ||
            Array.isArray(context.chatMetadata.character_states)) {
            context.chatMetadata.character_states = {};
        }

        context.chatMetadata.character_states[key] = normalizeRuntimeState({
            stats: {}, skills: [], inventory: [],
            custom: {}, customText: "", effects: []
        });

        pushWholeAudit(context, key, "manual", "create");

        stateEventBus.emit("entity.created", {
            event: "entity.created",
            entity: key,
            timestamp: Date.now(),
            result: { type: "scene", name },
            source: "manual"
        });

        stateEventBus.emit("state.created", {
            event: "state.created",
            entity: key,
            timestamp: Date.now(),
            result: { type: "scene", name },
            source: "manual"
        });

        await saveChatState(context);

        csToast.success(csT("Scene \"{name}\" created — chat-local only.", { name }));
        modal.remove();
    });

    modal.addEventListener("click", async event => {
        const switchBtn = event.target.closest(".cs-scene-switch-btn");
        const deleteBtn = event.target.closest(".cs-scene-delete-btn");

        if (switchBtn) {
            const key = switchBtn.dataset.key;
            const result = setActiveScene(context, key === getActiveSceneKey(context) ? null : key);

            if (!result.ok) {
                csToast.error(result.reason || csT("Cannot switch scene."));
                return;
            }

            pushWholeAudit(context, result.active || "scene:none", "manual", "activate");
            await saveChatState(context);
            renderBody();
            return;
        }

        if (deleteBtn) {
            const key = deleteBtn.dataset.key;
            const name = key.slice("scene:".length);

            if (!await csConfirm(csT("Delete scene \"{name}\" and its data from this chat? This cannot be undone.", { name }))) return;

            delete context.chatMetadata.character_states[key];

            if (getActiveSceneKey(context) === key) setActiveScene(context, null);

            if (context.chatMetadata[HISTORY_KEY]?.[key]) {
                delete context.chatMetadata[HISTORY_KEY][key];
            }

            pushAuditEntry(context, { k: key, src: "manual", sec: "state", f: name, op: "delete" });

            await saveChatState(context);
            renderBody();
        }
    });

    modal.querySelector("#cs-scenes-close-btn")?.addEventListener("click", () => modal.remove());
    modal.addEventListener("click", event => {
        if (event.target === modal) modal.remove();
    });
}

/* ---- Custom field metadata editor (B2) ---------------------------- */

function flattenCustomLeafPaths(value, prefix = "", out = []) {
    if (!value || typeof value !== "object") return out;

    if (Array.isArray(value)) {
        out.push(prefix);
        return out;
    }

    for (const [key, child] of Object.entries(value)) {
        const path = prefix ? `${prefix}.${key}` : key;

        if (child && typeof child === "object" && !Array.isArray(child)) {
            flattenCustomLeafPaths(child, path, out);
        } else {
            out.push(path);
        }
    }

    return out;
}

function openCustomFieldMetaModal(character) {
    const context = SillyTavern.getContext();

    if (!character) {
        csToast.warning("No entity could be resolved.");
        return;
    }

    const entityKey = getStateEntityKey(character);
    const state = getLiveStateForEntity(character);
    const data = state ? getEffectiveCustomData(state) : null;
    const leafPaths = data ? flattenCustomLeafPaths(data) : [];

    if (!leafPaths.length) {
        csToast.info("This entity has no custom data fields yet.");
        return;
    }

    document.getElementById("cs-custom-meta-overlay")?.remove();

    const modal = document.createElement("div");
    modal.id = "cs-custom-meta-overlay";
    modal.className = "cs-log-overlay";

    const current = getCustomFieldMetaMap(context, entityKey) || {};

    const typeOptions = ["number", "bar", "boolean", "choice", "text", "badge", "counter"]
        .map(type => `<option value="${type}">${type}</option>`).join("");
    const visibilityOptions = ["prompt", "ui", "hidden"]
        .map(visibility => `<option value="${visibility}">${visibility}</option>`).join("");

    modal.innerHTML = `
        <div class="cs-log-window" style="width:min(560px,94vw);">
            <div class="cs-log-header">
                <div class="cs-log-title">${csIcon("sliders")} ${escapeHtml(csT("Custom Field Meta"))}</div>
                <div class="cs-log-subtitle">${csH("Typed display + prompt visibility per field (metadata only — values stay plain JSON)")}</div>
            </div>
            <div class="cs-log-body" style="padding:16px 20px;">
                <div class="cs-settings-row">
                    <label class="cs-settings-label" for="cs-meta-field">${csH("Field")}</label>
                    <select id="cs-meta-field" class="text_pole cs-log-select" style="width:100%;">${optionsListHtml(leafPaths)}</select>
                </div>
                <div class="cs-settings-row">
                    <label class="cs-settings-label" for="cs-meta-type">${csH("Type (display)")}</label>
                    <select id="cs-meta-type" class="text_pole cs-log-select">${typeOptions}</select>
                </div>
                <div class="cs-settings-row">
                    <label class="cs-settings-label" for="cs-meta-visibility">${csH("Visibility")}</label>
                    <select id="cs-meta-visibility" class="text_pole cs-log-select">${visibilityOptions}</select>
                </div>
                <div class="cs-settings-row">
                    <label class="cs-settings-label" for="cs-meta-max">${csH("Bar max (for type=bar)")}</label>
                    <input id="cs-meta-max" class="text_pole" type="number" min="0" placeholder="—" />
                </div>
            </div>
            <div class="cs-log-footer">
                <button class="cs-chip cs-chip-accent" id="cs-meta-apply-btn" type="button">💾 ${csH("Apply")}</button>
                <button class="cs-chip cs-chip-soft" id="cs-meta-close-btn" type="button">${csH("Close")}</button>
            </div>
        </div>
    `;

    function optionsListHtml(paths) {
        return paths.map(path => `<option value="${escapeHtml(path)}">${escapeHtml(path)}</option>`).join("");
    }

    document.body.appendChild(modal);

    const syncForm = () => {
        const path = String(modal.querySelector("#cs-meta-field")?.value || "");
        const meta = getCustomFieldMeta(context, entityKey, path) || {};

        modal.querySelector("#cs-meta-type").value = meta.type || "number";
        modal.querySelector("#cs-meta-visibility").value = meta.visibility || "prompt";
        modal.querySelector("#cs-meta-max").value = Number.isFinite(meta.max) ? meta.max : "";
    };

    modal.querySelector("#cs-meta-field")?.addEventListener("change", syncForm);
    syncForm();

    modal.querySelector("#cs-meta-apply-btn")?.addEventListener("click", async () => {
        const path = String(modal.querySelector("#cs-meta-field")?.value || "");
        const patch = {
            type: modal.querySelector("#cs-meta-type")?.value || "number",
            visibility: modal.querySelector("#cs-meta-visibility")?.value || "prompt"
        };

        const maxRaw = modal.querySelector("#cs-meta-max")?.value;
        if (String(maxRaw).trim() !== "") patch.max = Number(maxRaw);

        const result = setCustomFieldMeta(context, entityKey, path, patch);

        if (!result.ok) {
            csToast.error(result.reason || csT("Cannot save field meta."));
            return;
        }

        await saveChatState(context);
        csToast.success(csT("Field meta saved for {path}.", { path }));
        modal.remove();

        const viewedOverlay = document.getElementById("character-state-overlay");
        if (viewedOverlay && viewedOverlay._character) {
            viewedOverlay.remove();
            await openCharacterSheet("view", character);
        }
    });

    modal.querySelector("#cs-meta-close-btn")?.addEventListener("click", () => modal.remove());
    modal.addEventListener("click", event => {
        if (event.target === modal) modal.remove();
    });
}

/* =========================================================
   DYNAMIC STATE COMPONENTS (B1 — reusable definition packs)
   A component is a schema-agnostic bundle of STAT DEFINITIONS:
     { format: "cs-component-v1", id, name, ts, fields: { Stat: def } }
   Applying one adds MISSING stat definitions and NEVER overwrites
   existing user-owned definitions (mirrors the STAT KEY RULE). The
   core knows nothing about component semantics — this is a definition
   transport format for community packs (dating sim, survival, ...).
========================================================= */

const COMPONENTS_STORAGE_KEY = "character-state:components:v1";
const COMPONENT_MAX = 50;

function componentStoreRead() {
    try {
        const raw = globalThis.localStorage?.getItem(COMPONENTS_STORAGE_KEY);
        const parsed = raw ? JSON.parse(raw) : [];

        return Array.isArray(parsed)
            ? parsed.filter(item => item && typeof item === "object")
            : [];
    } catch {
        return [];
    }
}

function componentStoreWrite(components) {
    globalThis.localStorage?.setItem(COMPONENTS_STORAGE_KEY, JSON.stringify(components.slice(0, COMPONENT_MAX)));
}

function listComponents() {
    return componentStoreRead();
}

function saveComponent(name, fields) {
    const cleanName = String(name || "").trim();

    if (!cleanName) return { ok: false, reason: "component name is required" };

    if (!fields || typeof fields !== "object" || Array.isArray(fields) || !Object.keys(fields).length) {
        return { ok: false, reason: "fields must be a non-empty object of stat definitions" };
    }

    const components = componentStoreRead();
    const existing = components.find(item => String(item?.name ?? "").trim().toLowerCase() === cleanName.toLowerCase());

    const component = existing || {
        format: "cs-component-v1",
        id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        name: cleanName,
        ts: Date.now(),
        fields: {}
    };

    component.fields = structuredClone(fields);
    component.ts = Date.now();

    if (!existing) components.push(component);

    componentStoreWrite(components);

    return { ok: true, component, overwritten: Boolean(existing) };
}

function deleteComponent(id) {
    const components = componentStoreRead();
    const index = components.findIndex(item => item?.id === id);

    if (index < 0) return false;

    components.splice(index, 1);
    componentStoreWrite(components);

    return true;
}

/*
 * Add MISSING stat definitions from a component into a starting state.
 * Incoming definitions are normalized through the SAME rebuild path
 * card schemas use — no bespoke stat semantics here.
 */
function applyComponentToSchema(startingState, component) {
    const fields = component?.fields && typeof component.fields === "object" && !Array.isArray(component.fields)
        ? component.fields
        : null;

    if (!fields) return { ok: false, added: [], skipped: [], reason: "component fields are missing" };

    if (!startingState || typeof startingState !== "object") startingState = { stats: {} };

    if (!startingState.stats || typeof startingState.stats !== "object" || Array.isArray(startingState.stats)) {
        startingState.stats = {};
    }

    const normalized = normalizeStartingState({
        stats: structuredClone(fields),
        skills: [], inventory: [], custom: {}, customText: ""
    });

    const added = [];
    const skipped = [];

    for (const [name, statDef] of Object.entries(normalized.stats || {})) {
        if (startingState.stats[name]) {
            skipped.push(name);
            continue;
        }

        startingState.stats[name] = statDef;
        added.push(name);
    }

    return { ok: true, added, skipped };
}

/* ---- Components manager overlay ------------------------------------ */

function openComponentManager(character) {
    const context = SillyTavern.getContext();

    if (!character) {
        csToast.warning("No character could be resolved.");
        return;
    }

    document.getElementById("cs-components-overlay")?.remove();

    const overlay = document.createElement("div");
    overlay.id = "cs-components-overlay";
    overlay.className = "cs-log-overlay";

    const nameInput = () => overlay.querySelector("#cs-component-name-input");

    overlay.innerHTML = `
        <div class="cs-log-window" style="width:min(720px,96vw);">
            <div class="cs-log-header">
                <div class="cs-log-title">${csIcon("puzzle-piece")} ${escapeHtml(csT("Components"))}</div>
                <div class="cs-log-subtitle">${csH("Reusable stat-definition packs (community \"packs\") — applying adds MISSING stats only, never overwrites · stored in this browser")}</div>
                <div class="cs-log-filters">
                    <input id="cs-component-name-input" class="text_pole cs-log-select" type="text" placeholder="${csH("Component name…")}" style="flex:1;min-width:180px;" />
                    <button class="cs-chip cs-chip-accent" id="cs-component-save-btn" type="button">💾 ${csH("Save current stats")}</button>
                    <button class="cs-chip" id="cs-component-paste-btn" type="button">⇩ ${csH("Paste JSON")}</button>
                    <button class="cs-chip" id="cs-components-close-btn" type="button">${csH("Close")}</button>
                </div>
            </div>
            <div class="cs-log-body" id="cs-components-body"></div>
            <div class="cs-log-footer" id="cs-components-summary"></div>
        </div>
    `;

    document.body.appendChild(overlay);

    const refresh = () => {
        const components = listComponents();
        const body = overlay.querySelector("#cs-components-body");

        if (!body) return;

        body.innerHTML = components.length
            ? components.map(component => `
                <div class="cs-component-row">
                    <span class="cs-log-main"><b>${escapeHtml(component.name)}</b> · ${csH("{n} stat fields", { n: Object.keys(component.fields || {}).length })}</span>
                    <button class="cs-chip cs-chip-accent" data-component-apply="${escapeHtml(component.id)}" type="button">${csH("Apply")}</button>
                    <button class="cs-chip" data-component-copy="${escapeHtml(component.id)}" type="button">${csH("Copy JSON")}</button>
                    <button class="cs-chip" data-component-delete="${escapeHtml(component.id)}" type="button" title="${csH("Delete component")}">🗑</button>
                </div>
            `).join("")
            : `<div class="cs-log-empty">${csH("No components yet — save the current sheet's stats as a pack, or paste one.")}</div>`;

        const summary = overlay.querySelector("#cs-components-summary");

        if (summary) summary.textContent = csT("{n} component(s) · browser-stored · shared across chats", { n: components.length });
    };

    refresh();

    overlay.querySelector("#cs-components-close-btn")?.addEventListener("click", () => overlay.remove());

    overlay.addEventListener("click", event => {
        if (event.target === overlay) overlay.remove();
    });

    overlay.querySelector("#cs-component-save-btn")?.addEventListener("click", () => {
        const name = String(nameInput()?.value || "").trim();

        if (!name) {
            csToast.warning("Type a component name first.");
            return;
        }

        const schema = buildCharacterSchema(character, getCharacterState(character));
        const fields = schema?.startingState?.stats;

        if (!fields || !Object.keys(fields).length) {
            csToast.warning("The current sheet has no stat definitions to save.");
            return;
        }

        const result = saveComponent(name, fields);

        if (!result.ok) {
            csToast.error(result.reason || csT("Cannot save component."));
            return;
        }

        csToast.success(result.overwritten
            ? csT("Component \"{name}\" overwritten.", { name })
            : csT("Component \"{name}\" saved ({n} stat fields).", { name, n: Object.keys(fields).length }));

        if (nameInput()) nameInput().value = "";
        refresh();
    });

    overlay.querySelector("#cs-component-paste-btn")?.addEventListener("click", async () => {
        let text = "";

        try {
            text = await navigator.clipboard.readText();
        } catch (error) {
            csToast.error("Clipboard read failed.");
            return;
        }

        let parsed = null;

        try {
            parsed = JSON.parse(text);
        } catch {
            csToast.error("Pasted JSON could not be parsed.");
            return;
        }

        const fields = parsed?.fields ||
            parsed?.startingState?.stats ||
            (parsed?.stats && typeof parsed.stats === "object" ? parsed.stats : null);

        if (!fields || typeof fields !== "object" || Array.isArray(fields) || !Object.keys(fields).length) {
            csToast.error("No stat fields found (expect {format:\"cs-component-v1\", name, fields:{...}}).");
            return;
        }

        const name = String(parsed?.name || parsed?.id || "").trim() || `component-${Date.now() % 10000}`;
        const result = saveComponent(name, fields);

        if (!result.ok) {
            csToast.error(result.reason || csT("Cannot save component."));
            return;
        }

        csToast.success(csT("Component \"{name}\" imported.", { name }));
        refresh();
    });

    overlay.querySelector("#cs-components-body")?.addEventListener("click", async event => {
        const applyButton = event.target.closest?.("[data-component-apply]");
        const copyButton = event.target.closest?.("[data-component-copy]");
        const deleteButton = event.target.closest?.("[data-component-delete]");

        const components = listComponents();
        const findComponentById = id => components.find(item => item?.id === id) || null;

        if (applyButton) {
            const component = findComponentById(applyButton.dataset.componentApply);

            if (!component?.fields) {
                csToast.error("Component fields are missing.");
                return;
            }

            /* Reuse the tested paste pipeline: build a v2 schema carrying
               ONLY the component's stat definitions. */
            const schema = {
                format: "v2",
                startingState: {
                    stats: structuredClone(component.fields),
                    skills: [], inventory: [], custom: {}, customText: ""
                }
            };

            await navigator.clipboard.writeText(JSON.stringify(schema, null, 2));

            const mode = await promptPasteMode(component.name || "component");

            if (!mode) return;

            await pasteCharacterSchema(character, mode);

            csToast.success(csT("Component \"{name}\" applied (missing stats added).", { name: component.name }));
            return;
        }

        if (copyButton) {
            const component = components.find(item => item?.id === copyButton.dataset.componentCopy);

            if (component) {
                await navigator.clipboard.writeText(JSON.stringify(component, null, 2));
                csToast.success("Component JSON copied to clipboard.");
            }

            return;
        }

        if (deleteButton) {
            if (deleteComponent(deleteButton.dataset.componentDelete)) {
                refresh();
            }
        }
    });
}

async function openPresetManager(character) {
    const context = SillyTavern.getContext();

    if (!character) {
        csToast.warning("No character could be resolved.");
        return;
    }

    const isUser = isUserEntity(character);

    document.getElementById("cs-presets-overlay")?.remove();

    const overlay = document.createElement("div");
    overlay.id = "cs-presets-overlay";
    overlay.className = "cs-log-overlay";

    overlay.innerHTML = `
        <div class="cs-log-window">
            <div class="cs-log-header">
                <div class="cs-log-title">${csIcon("bookmark")} ${escapeHtml(csT("Stat Presets"))}</div>
                <div class="cs-log-subtitle">${csH("Saved schemas (same format as ⋯ ▸ Copy schema) · stored in this browser")} · ${escapeHtml(isUser ? csT("{{user}} runtime") : (character.name || ""))}</div>
                <div class="cs-log-filters">
                    <input id="cs-preset-name-input" class="text_pole cs-log-select" type="text" placeholder="${csH("Preset name…")}" style="flex:1;min-width:200px;" />
                    <button class="cs-chip cs-chip-accent" id="cs-preset-save-btn" type="button">💾 ${csH("Save current state")}</button>
                    <button class="cs-chip" id="cs-preset-close-btn" type="button">${csH("Close")}</button>
                </div>
            </div>
            <div class="cs-log-body" id="cs-preset-body"></div>
            <div class="cs-log-footer" id="cs-preset-summary"></div>
        </div>
    `;

    document.body.appendChild(overlay);

    const body = overlay.querySelector("#cs-preset-body");
    const summary = overlay.querySelector("#cs-preset-summary");
    const nameInput = overlay.querySelector("#cs-preset-name-input");

    const findPresetByName = (presets, name) => {
        const needle = String(name ?? "").trim().toLowerCase();
        if (!needle) return null;
        return presets.find(preset =>
            String(preset?.name ?? "").trim().toLowerCase() === needle
        ) || null;
    };

    const refresh = () => {
        const presets = presetStoreRead();
        const builtinOpen = readBuiltinPresetsOpen(presets.length);
        body.innerHTML = builtinPresetSectionHtml(builtinOpen) + presetRowsHtml(presets);
        /* a <details> rendered open fires "toggle" once by itself — only
           store a real change */
        let shownOpen = builtinOpen;
        body.querySelector?.(".cs-builtin-presets")?.addEventListener("toggle", event => {
            if (event.target.open === shownOpen) return;
            shownOpen = event.target.open;
            writeBuiltinPresetsOpen(shownOpen);
        });

        const typedName = String(nameInput?.value || "").trim();
        const existing = findPresetByName(presets, typedName);

        summary.textContent = existing
            ? csT("{n} preset(s) · shared across chats · cap {cap} · 💾 will OVERWRITE \"{name}\"", { n: presets.length, cap: PRESET_MAX_ITEMS, name: existing.name })
            : csT("{n} preset(s) · shared across chats · cap {cap}", { n: presets.length, cap: PRESET_MAX_ITEMS });
    };

    refresh();

    nameInput?.addEventListener("input", refresh);

    overlay.querySelector("#cs-preset-close-btn")?.addEventListener("click", () => overlay.remove());

    overlay.addEventListener("click", event => {
        if (event.target === overlay) overlay.remove();
    });

    overlay.querySelector("#cs-preset-save-btn")?.addEventListener("click", async () => {
        const name = String(nameInput?.value || "").trim();

        if (!name) {
            csToast.warning("Type a preset name first.");
            return;
        }

        const presets = presetStoreRead();
        const existing = findPresetByName(presets, name);

        if (existing && !await csConfirm(
            csT("Preset \"{name}\" already exists.\n\nOverwrite it with the current state?", { name: existing.name })
        )) {
            return;
        }

        await ensureCharacterState(character, false);

        const state = getCharacterState(character);
        const schema = buildCharacterSchema(character, state);

        if (isUser) {
            /* {{user}} has no card: the current runtime IS the schema's
               startingState so a later Load restores the full sheet. */
            schema.startingState = structuredClone(schema.runtimeState);
        }

        const statCount = Object.keys(schema.startingState.stats || {}).length;

        if (existing) {
            /* Save As: overwrite the existing preset in place. */
            existing.schema = schema;
            existing.ts = Date.now();

            presetStoreWrite(presets);
            csToast.success(csT("Preset \"{name}\" overwritten ({n} stats).", { name: existing.name, n: statCount }));
        } else {
            if (presets.length >= PRESET_MAX_ITEMS) {
                presets.shift();
            }

            presets.push({
                id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
                name,
                ts: Date.now(),
                schema
            });

            presetStoreWrite(presets);
            csToast.success(csT("Preset \"{name}\" saved ({n} stats).", { name, n: statCount }));
            if (nameInput) nameInput.value = "";
        }

        refresh();
    });

    body.addEventListener("click", async event => {
        const loadButton = event.target.closest?.("[data-preset-load]");
        const builtinButton = event.target.closest?.("[data-builtin-load]");
        const copyButton = event.target.closest?.("[data-preset-copy]");
        const deleteButton = event.target.closest?.("[data-preset-delete]");
        const pinButton = event.target.closest?.("[data-preset-pin]");

        const presets = presetStoreRead();
        const findPresetById = id => presets.find(preset => preset?.id === id) || null;

        if (loadButton || builtinButton) {
            /* v3.2: a built-in genre preset loads through the same path */
            const [genreId, variantId] = String(builtinButton?.dataset.builtinLoad || "").split(":");
            const preset = builtinButton
                ? { name: builtinPresetDisplayName(genreId, variantId), schema: buildBuiltinPresetSchema(genreId, variantId) }
                : findPresetById(loadButton.dataset.presetLoad);

            if (!preset?.schema) {
                csToast.error("Preset schema is missing.");
                return;
            }

            const mode = await promptPasteMode(preset.name || "preset");

            if (!mode) return;

            const presetText = JSON.stringify(preset.schema, null, 2);

            if (mode === "clear_replace") {
                const entityKey = getStateEntityKey(character);

                if (entityKey) {
                    clearCharacterChatState(context, entityKey);
                    pushWholeAudit(context, entityKey, "manual", "clear");
                    await saveChatState(context);
                }
            }

            await pasteCharacterSchema(character, mode === "clear_replace" ? "replace" : mode, presetText);

            csToast.success(
                mode === "overlay"
                    ? csT("Preset \"{name}\" applied as overlay.", { name: preset.name })
                    : csT("Preset \"{name}\" applied.", { name: preset.name })
            );

            overlay.remove();
            openCharacterSheet("view", character);
            return;
        }

        if (copyButton) {
            const preset = findPresetById(copyButton.dataset.presetCopy);

            if (!preset?.schema) return;

            await navigator.clipboard.writeText(JSON.stringify(preset.schema, null, 2));
            csToast.success(csT("Preset \"{name}\" copied to the clipboard (v2 schema).", { name: preset.name }));
            return;
        }

        if (deleteButton) {
            const preset = findPresetById(deleteButton.dataset.presetDelete);

            if (!preset) return;

            if (!await csConfirm(csT("Delete preset \"{name}\"?", { name: preset.name }))) return;

            presetStoreWrite(presets.filter(item => item?.id !== preset.id));
            csToast.success(csT("Preset \"{name}\" deleted.", { name: preset.name }));
            refresh();
            return;
        }

        if (pinButton) {
            const preset = findPresetById(pinButton.dataset.presetPin);

            if (!preset) return;

            preset.pinned = !preset.pinned;
            preset.pinnedAt = preset.pinned ? Date.now() : undefined;

            presetStoreWrite(presets);
            refresh();
        }
    });
}

async function openAuditLogOverlay(character) {
    const context = SillyTavern.getContext();
    const audit = getAuditArray(context) || [];

    const currentKey = character ? getStateEntityKey(character) : USER_STATE_KEY;

    /* distinct entity keys in this chat's audit + current entity */
    const entityKeys = new Set(audit.map(entry => entry.k).filter(Boolean));
    entityKeys.add(currentKey);

    const sortedEntities = Array.from(entityKeys).sort((a, b) =>
        auditEntityDisplayName(a).localeCompare(auditEntityDisplayName(b))
    );

    document.getElementById("cs-log-overlay")?.remove();

    const overlay = document.createElement("div");
    overlay.id = "cs-log-overlay";
    overlay.className = "cs-log-overlay";

    const entityOptions = [
        `<option value="__all__">${csH("All characters")}</option>`,
        ...sortedEntities.map(key =>
            `<option value="${escapeHtml(key)}" ${key === currentKey ? "selected" : ""}>${escapeHtml(auditEntityDisplayName(key))}</option>`
        )
    ].join("");

    const sourceOptions = [
        `<option value="all">${csH("All sources")}</option>`,
        `<option value="ai">AI</option>`,
        `<option value="manual">${csH("Manual")}</option>`,
        `<option value="system">${csH("System")}</option>`
    ].join("");

    const currentCap = getAuditCap(context);
    const capOptions = [0, 100, 200, 500, 1000, 2000, 5000].map(value =>
        `<option value="${value}" ${currentCap === value ? "selected" : ""}>${value === 0 ? csH("Unlimited") : csH("{n} entries", { n: value })}</option>`
    ).join("");

    overlay.innerHTML = `
        <div class="cs-log-window">
            <div class="cs-log-header">
                <div class="cs-log-title">${csIcon("list")} ${escapeHtml(csT("Change Log"))}</div>
                <div class="cs-log-subtitle">${csH("This chat only")} · ${escapeHtml(auditEntityDisplayName(currentKey))} · ${csH("user-only history (never sent to the model)")}</div>
                <div class="cs-log-filters">
                    <select id="cs-log-entity" class="text_pole cs-log-select">${entityOptions}</select>
                    <select id="cs-log-src" class="text_pole cs-log-select">${sourceOptions}</select>
                    <select id="cs-log-cap" class="text_pole cs-log-select" title="${csH("How many entries this chat keeps (0 = unlimited). Saved per chat.")}">${capOptions}</select>
                    <button class="cs-chip cs-chip-soft" id="cs-log-clear-btn" type="button" title="${csH("Delete the audit log for this chat")}">🗑 ${csH("Clear log")}</button>
                    <button class="cs-chip cs-chip-soft" id="cs-log-export-json-btn" type="button" title="${csH("Download the filtered audit as JSON")}">⬇ JSON</button>
                    <button class="cs-chip cs-chip-soft" id="cs-log-export-csv-btn" type="button" title="${csH("Download the filtered audit as CSV (spreadsheet-friendly)")}">⬇ CSV</button>
                    <button class="cs-chip" id="cs-log-close-btn" type="button">${csH("Close")}</button>
                </div>
            </div>
            <div class="cs-log-body" id="cs-log-body"></div>
            <div class="cs-log-footer" id="cs-log-summary"></div>
        </div>
    `;

    document.body.appendChild(overlay);

    const body = overlay.querySelector("#cs-log-body");
    renderAuditLogBody(body, context, currentKey, "all");

    const entitySelect = overlay.querySelector("#cs-log-entity");
    const sourceSelect = overlay.querySelector("#cs-log-src");
    const capSelect = overlay.querySelector("#cs-log-cap");

    const refresh = () => {
        renderAuditLogBody(
            body,
            context,
            entitySelect?.value || "__all__",
            sourceSelect?.value || "all"
        );
    };

    entitySelect?.addEventListener("change", refresh);
    sourceSelect?.addEventListener("change", refresh);

    capSelect?.addEventListener("change", async () => {
        setAuditCap(context, Number(capSelect.value || 0));
        applyAuditCap(context);
        await saveChatState(context);
        refresh();
        csToast.info(getAuditCap(context) > 0
            ? csT("Audit cap set to {n} entries for this chat.", { n: getAuditCap(context) })
            : csT("Audit cap set to unlimited for this chat."));
    });

    overlay.querySelector("#cs-log-close-btn")?.addEventListener("click", () => overlay.remove());

    const getFilteredAudit = () => {
        const audit = getAuditArray(context) || [];
        const entityFilter = entitySelect?.value || "__all__";
        const sourceFilter = sourceSelect?.value || "all";

        return audit.filter(entry => {
            if (entityFilter !== "__all__" && entry.k !== entityFilter) return false;
            if (sourceFilter !== "all" && (entry.src || "system") !== sourceFilter) return false;
            return true;
        });
    };

    overlay.querySelector("#cs-log-export-json-btn")?.addEventListener("click", () => {
        const filtered = getFilteredAudit();

        if (!filtered.length) {
            csToast.info("No entries to export for this filter.");
            return;
        }

        downloadTextFile(
            `character-state-audit-${Date.now()}.json`,
            JSON.stringify(filtered, null, 2)
        );
        csToast.success(csT("Exported {n} audit entries as JSON.", { n: filtered.length }));
    });

    overlay.querySelector("#cs-log-export-csv-btn")?.addEventListener("click", () => {
        const filtered = getFilteredAudit();

        if (!filtered.length) {
            csToast.info("No entries to export for this filter.");
            return;
        }

        const escapeCsv = value => {
            const text = String(value ?? "");
            return /[",\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
        };

        const header = ["time", "entity", "source", "section", "field", "op", "before", "after", "count"];

        const rows = filtered.map(entry => [
            formatAuditTime(entry.t),
            auditEntityDisplayName(entry.k),
            entry.src || "system",
            entry.sec || "",
            entry.f ?? "",
            entry.op || "",
            entry.b !== undefined ? entry.b : "",
            entry.a !== undefined ? entry.a : "",
            entry.c ?? 1
        ]);

        const csv = [header, ...rows]
            .map(row => row.map(escapeCsv).join(","))
            .join("\r\n");

        downloadTextFile(
            `character-state-audit-${Date.now()}.csv`,
            "\uFEFF" + csv
        );
        csToast.success(csT("Exported {n} audit entries as CSV.", { n: filtered.length }));
    });

    overlay.addEventListener("click", event => {
        if (event.target === overlay) overlay.remove();
    });

    overlay.querySelector("#cs-log-clear-btn")?.addEventListener("click", async () => {
        if (!await csConfirm("Delete all change history of THIS chat?\n\nRuntime states and Character Cards are not touched.")) return;

        getAuditArray(context).length = 0;
        await saveChatState(context);
        csToast.success("Change log cleared.");
        refresh();
    });
}

/* =========================================================
   SHEET
========================================================= */

let sheetOpenSequence = 0;

async function openCharacterSheet(mode = "view", targetCharacter = null) {
    const context = SillyTavern.getContext();

    /* v3 review: overlapping opens (AI refresh vs a user click) — only the
       most recent call may attach its sheet. */
    const openSequence = ++sheetOpenSequence;
    const restoreForThisOpen = sheetUiMemory.pendingRestore;
    sheetUiMemory.pendingRestore = null;

    /* ---- browse mode: no character/group chat is active ----------------
       The sheet button must still work when nothing is selected: offer the
       WHOLE character library in the selector (with a small filter) and
       default to the first character. Inside a group/character chat the
       selector stays limited to the group members / current character. */
    const contextCharacters = await ensureCharactersLoaded(
        getAvailableSheetCharacters()
    );

    let browseAll = false;
    let availableCharacters = contextCharacters;

    const activeIndex = typeof context.characterId === "number"
        ? context.characterId
        : -1;

    const inCharacterChat = !context.groupId &&
        activeIndex >= 0 &&
        context.characters?.[activeIndex] != null;

    if (!contextCharacters.length &&
        !context.groupId &&
        !inCharacterChat &&
        Array.isArray(context.characters) &&
        context.characters.length) {
        browseAll = true;

        /* Whole library, sorted by name. Cards are NOT hydrated here —
           the selected character is loaded lazily by the normal flow. */
        availableCharacters = context.characters
            .filter(item => item && item.name)
            .slice()
            .sort((a, b) => String(a.name).localeCompare(String(b.name)));
    }

    /* Group or character chats with an existing User State also offer the
       {{user}} entity in the selector. */
    const canHostUser = Boolean(
        context?.groupId || inCharacterChat || resolveActiveCharacter()
    );

    const userEntity = canHostUser && getStoredUserState(context)
        ? makeUserEntity()
        : null;

    if (userEntity) {
        availableCharacters.push(userEntity);
    }

    csDebug(
        "[Character State] Sheet available characters:",
        availableCharacters.map(character => character?.name)
    );

    const initialCharacter = targetCharacter || getSelectedSheetCharacter(availableCharacters);

    if (!initialCharacter) {
        csToast.error("No character available for Character Sheet.");
        return;
    }

    setSelectedSheetCharacter(initialCharacter);
    let character = getSelectedSheetCharacter(availableCharacters);

    const isUser = isUserEntity(character);

    /* Stable entity key of the sheet's current character ({{user}} uses
       the reserved USER_STATE_KEY). Used for stat history/sparklines. */
    const entityKey = getStateEntityKey(character) || "";

    /* Browsing the whole library (no chat open): cards may be shallow —
       hydrate the selected card first so editors/reset see real data. */
    if (!isUser && character) {
        const hydrated = await ensureCharactersLoaded([character]);
        if (hydrated && hydrated.length && hydrated[0]) {
            character = hydrated[0];
        }
    }

    /* Modes: view | edit (Character Card defaults) | editRuntime (chat).
       {{user}} has no card, so "edit" always becomes "editRuntime". */
    if (isUser && mode === "edit") {
        mode = "editRuntime";
    }

    let state;

    if (isUser) {
        const storedUser = getUserState(context);
        if (!storedUser) {
            csToast.error("User State has not been created yet in this chat.");
            return;
        }
        state = mode === "editRuntime"
            ? normalizeRuntimeState(structuredClone(storedUser))
            : storedUser;
    } else {
        /* Order matters: hydrate the card first, then initialize the runtime,
           then read state. Never render before initialization. */
        await ensureCharacterState(character);
        state = mode === "edit"
            ? buildEditorStateForCharacter(character)
            : mode === "editRuntime"
                ? normalizeRuntimeState(structuredClone(getCharacterState(character)))
                : getCharacterState(character);
    }

    const isEditing = mode !== "view";
    const characterName = isUser ? userDisplayName() : (character?.name || csT("Character"));
    const sheetIcon = isUser ? "👤" : "♟";

    /* View mode: make sure every number stat has a baseline history point
       so the inline sparkline/dot renders immediately (persisted here so
       the next save keeps it). */
    if (!isEditing && entityKey) {
        const baselineChanged = recordHistoryBaseline(context, entityKey, state);

        if (baselineChanged) {
            try {
                saveChatState(context);
            } catch {
                /* best effort */
            }
        }
    }

    /* Group stat keys the user sheet is still missing (available on a
       majority of the group members). Only computed for user view mode.
       Stats the user explicitly DISMISSED ("✕ Never") are filtered out —
       a leaner user sheet than the group schema can be INTENTIONAL. */
    let missingCommonStats = (isUser && !isEditing && canHostUser)
        ? await getMissingCommonUserStats(context)
        : [];

    if (missingCommonStats.length) {
        const dismissedNames = getSchemaDiffDismissedNames(context, entityKey);

        if (dismissedNames.length) {
            missingCommonStats = missingCommonStats.filter(entry => !dismissedNames.includes(entry.name));
        }
    }

    /* per-chat custom display mode (compact = cheaper prompts) */
    const customDisplayMode = getCustomDisplayMode(context);

    document.getElementById("cs-stat-modal-overlay")?.remove();

    /* v3: the previous sheet stays on screen until the new one is ready. */
    const previousOverlay = document.getElementById("character-state-overlay");

    const overlay = document.createElement("div");
    overlay.id = "character-state-overlay";
    overlay.dataset.characterKey = getStateEntityKey(character) || "";
    overlay.dataset.mode = mode;
    overlay._character = character;
    if (isEditing) overlay._editState = state;

    /* ---- header subtitle / chips / notes (computed once) ---- */
    let subtitleText = "";
    let modeNoteHtml = "";
    let hintNoteHtml = "";
    let saveButtonLabel = "Save";

    /* v3: texts name the CURRENT controls (menus), bilingual via csT. */
    if (mode === "view") {
        subtitleText = escapeHtml(isUser
            ? csT("Character Sheet · {{user}} (no Character Card)")
            : character?.csSideNpc
                ? csT("Character Sheet · Side NPC (this chat only)")
                : csT("Character Sheet · this chat's state"));
    } else if (mode === "edit") {
        subtitleText = escapeHtml(csT("Editing the card defaults (new chats)"));
        modeNoteHtml = `
            <div class="cs-mode-note">${csT("Editing the <b>Character Card defaults</b>. This chat is not changed — to apply them here use <b>⋯ ▸ Reset this chat from the card</b>.")}</div>`;
        saveButtonLabel = escapeHtml(csT("Save card defaults"));
    } else {
        subtitleText = escapeHtml(isUser
            ? csT("Editing {{user}} in this chat")
            : csT("Editing this chat's state (card untouched)"));
        modeNoteHtml = `
            <div class="cs-mode-note">
                ${isUser
                    ? csT("Editing the <b>{{user}} state of this chat</b>. {{user}} has no Character Card — defaults come from the group stat schema.")
                    : csT("Editing the <b>state of this chat</b> (Base, Mod, skills, items, custom). The <b>Character Card is not changed</b> — card defaults change only through <b>Edit ▸ card defaults</b>, <b>⋯ ▸ Save this chat as the card defaults</b> or Paste.")}
            </div>`;
        saveButtonLabel = escapeHtml(csT("Save this chat"));
    }

    let headerActionsHtml = "";
    let tokenSummaryEstimate = null;
    const isSideNpcSheet = Boolean(character?.csSideNpc);

    /* Per-stat Mod→Base fold buttons in the sheet view are hidden behind
       this per-chat toggle (default OFF). */
    const modToBaseUiEnabled = getModToBaseUiEnabled(context);

    if (!isEditing) {
        /* Empty sheet + card without defaults: offer a visible way to
           pull the defaults from another chat of this character. */
        const cardHasDefaults = !isUser && hasStartingStateData(
            unwrapNestedStartingState(character?.data?.extensions?.["character-state"]?.startingState)
        );

        /* v3.1 P7: the token estimate rebuilds the whole prompt — computed
           when its menu item is clicked, not on every sheet open. */
        tokenSummaryEstimate = { lazy: true };

        /* v3: six visible controls; every other action moved into a menu
           (same button ids → same wiring below). */
        headerActionsHtml = renderSheetHeaderActions({
            isUser,
            isSideNpc: isSideNpcSheet,
            canHostUser,
            hasUserState: Boolean(getStoredUserState(context)),
            showRecover: !isUser && !isSideNpcSheet && !cardHasDefaults && isStaleEmptyRuntime(state),
            modToBaseUiEnabled,
            tokenEstimate: tokenSummaryEstimate
        });
    }

    if (isUser && mode === "view" && missingCommonStats.length) {
        hintNoteHtml = `
            <div class="cs-hint-note">
                <span>${csH("Group stat schema now offers stats this user sheet is missing:")}
                    <b>${escapeHtml(missingCommonStats.map(entry => entry.name).join(", "))}</b>
                </span>
                <button class="cs-link-btn" id="cs-user-add-missing-btn" type="button">＋ ${csH("Add missing")}</button>
                <button class="cs-link-btn" id="cs-user-dismiss-missing-btn" type="button" title="${csH("Don't offer these stats again in this chat — a leaner sheet than the group schema can be intentional")}">✕ ${csH("Never")}</button>
            </div>`;
    }

    const activeEffectCount = isEditing ? 0 : getActiveEffects(state).length;
    const sheetTabs = [
        { key: "stats", icon: "chart-simple", label: csT("Stats"), count: Object.keys(state.stats || {}).length },
        !isEditing ? { key: "effects", icon: "wand-sparkles", label: csT("Effects"), count: activeEffectCount } : null,
        { key: "skills", icon: "bolt", label: csT("Skills"), count: Array.isArray(state.skills) ? state.skills.length : 0 },
        { key: "inventory", icon: "box-open", label: csT("Inventory"), count: Array.isArray(state.inventory) ? state.inventory.length : 0 },
        !isEditing && entityKey ? {
            key: "relations",
            icon: "diagram-project",
            label: csT("Relations"),
            count: listRelationships(context, { from: entityKey }).length + listRelationships(context, { to: entityKey }).length
        } : null,
        { key: "custom", icon: "code", label: csT("Custom") }
    ].filter(Boolean);

    const activeTab = sheetTabs.some(tab => tab.key === sheetUiMemory.tab) ? sheetUiMemory.tab : "stats";

    /* v3.1 P5: a big custom tree (thousands of nodes, ~0.9 MB HTML) is only
       rendered when its tab is opened. Small ones stay eager. */
    const lazyCustomPanel = !isEditing && countCustomLeaves(state.custom) > 300;
    overlay._renderCustomPanel = () => renderCustomViewHtml(state, isEditing, customDisplayMode, getStateEntityKey(character));
    const panelAttrs = key => `data-cs-tab-panel="${key}"${key === activeTab ? "" : " hidden"}`;
    const sheetIconName = isUser ? "user" : isSideNpcSheet ? "user-tag" : "chess-knight";

    overlay.innerHTML = `
        <div class="cs-window" role="dialog" aria-modal="true" aria-label="${escapeHtml(csT("Character Sheet"))} — ${escapeHtml(characterName)}">
            <div class="cs-header">
                <div class="cs-title-area">
                    <div class="cs-character-icon">${csIcon(sheetIconName)}</div>
                    <div class="cs-title-content">
                        <div class="cs-character-name">${escapeHtml(characterName)}</div>
                        <div class="cs-subtitle">${subtitleText}</div>
                        <div class="cs-selector-row">
                            ${renderCharacterSelector(availableCharacters, character)}
                            ${browseAll
                                ? `<input id="cs-browse-filter" class="text_pole cs-browse-filter" type="text" placeholder="${csH("Filter characters…")}" title="${csH("Type to narrow down the character list")}" />`
                                : ""}
                        </div>
                    </div>
                </div>

                <div class="cs-header-actions">
                    ${renderGameTimeBadgeHtml(getGameTime(context))}
                    ${headerActionsHtml}
                    ${!isEditing ? `
                    <button class="cs-chip cs-chip-icon cs-chip-close" id="cs-x-btn" type="button" title="${escapeHtml(csT("Close"))}" aria-label="${escapeHtml(csT("Close"))}">${csIcon("xmark")}</button>
                    ` : ""}
                </div>
            </div>

            ${modeNoteHtml}
            ${hintNoteHtml}

            ${renderSheetTabs(sheetTabs, activeTab)}

            <div class="cs-content">
                <section class="cs-section cs-tab-panel" ${panelAttrs("stats")}>
                    <div class="cs-card">
                        ${isEditing ? renderStatsEditor(state) : renderStatsViewV3(state, entityKey, { isUser, isSideNpc: isSideNpcSheet })}
                    </div>
                </section>

                ${!isEditing ? `
                <section class="cs-section cs-tab-panel" ${panelAttrs("effects")}>
                    <div class="cs-card cs-card-pad">
                        ${renderEffectsPanelHtml(state)}
                    </div>
                </section>` : ""}

                <section class="cs-section cs-tab-panel" ${panelAttrs("skills")}>
                    <div class="cs-card">
                        ${isEditing ? renderSkillsEditor(state) : renderSkillsView(state)}
                    </div>
                </section>

                <section class="cs-section cs-tab-panel" ${panelAttrs("inventory")}>
                    <div class="cs-card">
                        ${isEditing ? renderInventoryEditor(state) : renderInventoryView(state)}
                    </div>
                </section>

                ${!isEditing && entityKey ? `
                <section class="cs-section cs-tab-panel" ${panelAttrs("relations")}>
                    <div class="cs-card cs-card-pad">${renderRelationsPanelHtml(context, entityKey)}</div>
                </section>` : ""}

                <section class="cs-section cs-tab-panel" ${panelAttrs("custom")}>
                    ${!isEditing ? `
                    <div class="cs-section-title cs-panel-toolbar">
                        <span>${escapeHtml(csT("Custom data"))}</span>
                        <button class="cs-link-btn cs-custom-copy-btn" id="cs-custom-copy-btn" type="button" title="${csH("Copy the Custom text (rules) to the clipboard")}">${csIcon("copy")} ${csH("Copy")}</button>
                        <select id="cs-custom-mode-select" class="text_pole cs-custom-mode-select" title="${csH("UI: pretty JSON tree. Compact: rules + compact data (cheaper tokens). Full: whole custom text + JSON block.")}">
                            <option value="ui" ${customDisplayMode === "ui" ? "selected" : ""}>UI</option>
                            <option value="compact" ${customDisplayMode === "compact" ? "selected" : ""}>${csH("Compact")}</option>
                            <option value="full" ${customDisplayMode === "full" ? "selected" : ""}>${csH("Full")}</option>
                        </select>
                    </div>` : ""}
                    <div class="cs-card"${lazyCustomPanel ? " data-cs-lazy-custom" : ""}>
                        ${lazyCustomPanel
                            ? `<div class="cs-empty-card"><div class="cs-empty-text">…</div></div>`
                            : renderCustomViewHtml(state, isEditing, customDisplayMode, getStateEntityKey(character))}
                    </div>
                </section>
            </div>

            <div class="cs-footer">
                ${mode === "view"
                    ? `<span class="cs-footer-note">${csIcon("circle-check")} ${escapeHtml(isUser || isSideNpcSheet ? csT("This chat") : csT("Chat runtime state"))} · ${escapeHtml(csT("Saved automatically"))}</span>
                       <span class="cs-footer-hint"><kbd>Esc</kbd> ${escapeHtml(csT("Esc to close").replace(/^Esc\s*/, ""))}</span>
                       <button class="cs-close-button" id="cs-close-btn" type="button">${escapeHtml(csT("Close"))}</button>`
                    : `<div class="cs-edit-footer">
                        <button class="cs-cancel-button" id="cs-cancel-btn" type="button">${escapeHtml(csT("Cancel"))}</button>
                        <button class="cs-save-button" id="cs-save-btn" type="button">${saveButtonLabel}</button>
                    </div>`}
            </div>
        </div>
    `;

    if (openSequence !== sheetOpenSequence) return;

    const currentOverlay = document.getElementById("character-state-overlay");
    if (currentOverlay && currentOverlay !== overlay) currentOverlay.remove();
    if (previousOverlay && previousOverlay !== overlay) previousOverlay.remove();
    document.body.appendChild(overlay);

    /* v3: menus, tabs, group pills, filter, row details. */
    wireSheetChrome(overlay);
    if (!isEditing) {
        wireRelationsPanel(overlay, entityKey);
        wireQuickEdits(overlay);
    }
    if (activeTab === "custom") hydrateLazyCustomPanel(overlay);
    restoreSheetUiState(overlay, restoreForThisOpen);

    document.getElementById("cs-x-btn")?.addEventListener("click", () => {
        void flushQuickEditBursts();
        overlay.remove();
    });

    document.getElementById("cs-game-time-badge")?.addEventListener("click", () => {
        promptEditGameTime();
    });

    document.getElementById("cs-browse-filter")?.addEventListener("input", event => {
        const term = String(event.target?.value || "").trim().toLowerCase();
        const select = overlay.querySelector("#cs-character-selector");
        if (!select) return;

        for (const option of select.options) {
            const show = !term || String(option.text || "").toLowerCase().includes(term);
            option.hidden = !show;
            option.style.display = show ? "" : "none";
        }
    });

    overlay.querySelector("#cs-character-selector")?.addEventListener("change", async event => {
        const nextCharacter = availableCharacters.find(item =>
            getStateEntityKey(item) === event.target.value
        );

        if (!nextCharacter || getStateEntityKey(nextCharacter) === getStateEntityKey(overlay._character)) {
            return;
        }

        if (mode === "edit" && isUserEntity(nextCharacter)) {
            csToast.warning("{{user}} has no Character Card to edit.");
            event.target.value = getStateEntityKey(overlay._character) || "";
            return;
        }

        if (mode === "edit" && !await csConfirm(
            "Switch character?\n\nUnsaved edits on the current character will be discarded."
        )) {
            event.target.value = getStateEntityKey(overlay._character) || "";
            return;
        }

        setSelectedSheetCharacter(nextCharacter);
        await reopenCharacterSheet(overlay, mode, nextCharacter);
    });

    if (mode === "view") {
        document.getElementById("cs-close-btn")?.addEventListener("click", () => {
            void flushQuickEditBursts();
            overlay.remove();
        });

        document.getElementById("cs-snapshot-now-btn")?.addEventListener("click", async () => {
            const result = takeStateSnapshot(context, "manual");

            if (result.ok) {
                await saveChatState(context);
                csToast.success(csT("Snapshot saved ({summary}).", { summary: result.summary }));
            } else {
                csToast.error("Could not save a snapshot (no active chat).");
            }
        });

        document.getElementById("cs-snapshots-btn")?.addEventListener("click", () => {
            openSnapshotManager(overlay._character);
        });

        document.getElementById("cs-settings-btn")?.addEventListener("click", () => {
            openSettingsOverlay();
        });

        document.getElementById("cs-token-btn")?.addEventListener("click", () => {
            const estimate = buildTokenSummaryEstimate();
            if (estimate) openTokenSummaryOverlay(estimate);
            else csToast.info("Nothing is injected into the prompt for this chat yet.");
        });

        overlay.addEventListener("click", async event => {
            const removeButton = event.target.closest?.(".cs-effect-remove");
            if (removeButton) {
                const effectId = removeButton.dataset?.csEffectId || "";

                if (effectId && await removeEffectManually(overlay._character, effectId)) {
                    const viewed = overlay._character;
                    await reopenCharacterSheet(overlay, "view", viewed);
                }

                return;
            }

            const addEffectButton = event.target.closest?.(".cs-effect-add");
            if (addEffectButton) {
                openEffectModal({ character: overlay._character });
                return;
            }

            const effectChip = event.target.closest?.(".cs-effect-chip");
            if (effectChip) {
                const effectId = effectChip.dataset?.csEffectId || "";
                const state = getLiveStateForEntity(overlay._character);
                const effect = state?.effects?.find(item => item.id === effectId);

                if (effect) {
                    openEffectModal({ character: overlay._character, effect });
                }

                return;
            }

            const foldButton = event.target.closest?.(".cs-mod-to-base-row-btn");
            if (foldButton) {
                const statName = foldButton.dataset?.csStatName || "";

                if (statName) {
                    const viewed = overlay._character;
                    const applied = await applyModToBaseForEntity(viewed, statName);

                    if (applied && applied.length) {
                        const entry = applied[0];
                        csToast.success(csT("{name}: Mod folded into Base ({before} → {after}).", { name: statName, before: formatNumber(entry.before), after: formatNumber(entry.after) }));
                    } else {
                        csToast.info(csT("{name}: no Mod to fold.", { name: statName }));
                    }

                    await reopenCharacterSheet(overlay, "view", viewed);
                }

                return;
            }

            const statLabel = event.target.closest?.(".cs-stat-name-label");
            if (statLabel) {
                const statName = statLabel.dataset?.csStatName || "";
                const key = getStateEntityKey(overlay._character);

                if (statName && key) {
                    openStatHistoryModal(key, statName);
                }

                return;
            }

            if (event.target === overlay) overlay.remove();
        });

        document.getElementById("cs-side-npc-btn")?.addEventListener("click", () => {
            openSideNpcModal();
        });

        document.getElementById("cs-scenes-btn")?.addEventListener("click", () => {
            openScenesModal();
        });

        document.getElementById("cs-components-btn")?.addEventListener("click", () => {
            openComponentManager(overlay._character);
        });

        document.getElementById("cs-side-npc-delete-btn")?.addEventListener("click", async () => {
            const viewed = overlay._character;
            const key = getStateEntityKey(viewed);

            if (!viewed?.csSideNpc?.key || !key) return;

            if (!await csConfirm(csT("Delete side NPC \"{name}\" and ALL its data from this chat? This cannot be undone.", { name: viewed.name }))) return;

            delete context.chatMetadata.character_states[key];

            context.chatMetadata[SIDE_NPC_REGISTRY_KEY] =
                listSideNpcs(context).filter(entry => entry.key !== key);

            if (context.chatMetadata[HISTORY_KEY]?.[key]) {
                delete context.chatMetadata[HISTORY_KEY][key];
            }

            pushAuditEntry(context, { k: key, src: "manual", sec: "state", f: viewed.name, op: "delete" });

            await saveChatState(context);
            csToast.success(csT("Side NPC \"{name}\" deleted.", { name: viewed.name }));

            await reopenCharacterSheet(overlay, "view");
        });

        document.getElementById("cs-log-btn")?.addEventListener("click", () => {
            openAuditLogOverlay(overlay._character);
        });

        document.getElementById("cs-timeline-btn")?.addEventListener("click", () => {
            openTimelineOverlay();
        });

        document.getElementById("cs-world-btn")?.addEventListener("click", () => {
            openWorldOverviewOverlay();
        });

        document.getElementById("cs-mod-to-base-toggle")?.addEventListener("click", async () => {
            const enabled = !getModToBaseUiEnabled(context);

            if (!context.chatMetadata) context.chatMetadata = {};
            context.chatMetadata[MOD_TO_BASE_UI_KEY] = enabled;
            await saveChatState(context);

            const viewed = overlay._character;
            await reopenCharacterSheet(overlay, "view", viewed);
        });

        document.getElementById("cs-mod-to-base-all-btn")?.addEventListener("click", async () => {
            const viewed = overlay._character;
            const previewState = structuredClone(state);
            const preview = foldModsToBaseForState(previewState);

            if (!preview.length) {
                csToast.info("No stat has a Mod to fold.");
                return;
            }

            const summary = preview
                .slice(0, 8)
                .map(entry => `${entry.name} ${entry.mod > 0 ? "+" : ""}${formatNumber(entry.mod)}`)
                .join(", ");

            const more = preview.length > 8 ? `\n${csT("…and {n} more", { n: preview.length - 8 })}` : "";

            if (!await csConfirm(
                csT("Fold {n} stat Mod(s) into Base?", { n: preview.length }) + `\n\n${summary}${more}\n\n` +
                csT("Each Base becomes Base + Mod and Mod resets to 0 in THIS chat's runtime. The Character Card is not modified — use ⋯ ▸ Save this chat as the card defaults afterwards.")
            )) return;

            const applied = await applyModToBaseForEntity(viewed);

            if (applied && applied.length) {
                csToast.success(csT("{n} stat(s) folded into Base. Use ⋯ ▸ Save this chat as the card defaults to write the card.", { n: applied.length }));
            }

            await reopenCharacterSheet(overlay, "view", viewed);
        });

        document.getElementById("cs-presets-btn")?.addEventListener("click", () => {
            openPresetManager(overlay._character);
        });

        document.getElementById("cs-custom-mode-select")?.addEventListener("change", async event => {
            const mode = event.target?.value === "full" || event.target?.value === "compact"
                ? event.target.value
                : "ui";

            setCustomDisplayMode(context, mode);
            await saveChatState(context);

            const viewed = overlay._character;
            await reopenCharacterSheet(overlay, "view", viewed);
        });

        document.getElementById("cs-custom-copy-btn")?.addEventListener("click", async () => {
            const liveState = getLiveStateForEntity(overlay._character);
            const customText = typeof liveState?.customText === "string" && liveState.customText.trim()
                ? liveState.customText
                : (liveState?.custom && Object.keys(liveState.custom).length
                    ? JSON.stringify(liveState.custom, null, 2)
                    : "");

            if (!customText) {
                csToast.info("Nothing to copy — Custom is empty.");
                return;
            }

            const copied = await copyTextToClipboard(customText);

            if (copied) {
                csToast.success("Custom text copied to the clipboard.");
            } else {
                csToast.error("Could not access the clipboard.");
            }
        });

        /* JSON tree interactions (UI mode) — DELEGATED on the overlay (v3.1):
           the Custom tab of big sheets is rendered lazily, after this runs. */
        const setJsonNodeCollapsed = (node, collapsed) => {
            if (!collapsed) hydrateJsonTreeNode(node);
            if (collapsed) node.dataset.collapsed = "1";
            else delete node.dataset.collapsed;
            const caret = node.querySelector(".cs-json-caret");
            if (caret) caret.textContent = collapsed ? "▸" : "▾";
        };

        overlay.addEventListener("click", event => {
            const target = event.target;
            if (!target?.closest) return;

            const caret = target.closest(".cs-json-caret");
            if (caret) {
                const node = caret.closest(".cs-json-node");
                if (node) setJsonNodeCollapsed(node, node.dataset.collapsed !== "1");
                return;
            }

            if (target.closest("#cs-json-expand-all, #cs-json-collapse-all")) {
                const collapse = Boolean(target.closest("#cs-json-collapse-all"));
                if (!collapse) {
                    /* hydrated nodes bring new lazy children: repeat */
                    let lazy;
                    while ((lazy = overlay.querySelectorAll("#cs-json-tree .cs-json-node[data-lazy-keys]")).length) {
                        for (const node of lazy) hydrateJsonTreeNode(node);
                    }
                }
                for (const node of overlay.querySelectorAll("#cs-json-tree .cs-json-node")) setJsonNodeCollapsed(node, collapse);
                return;
            }

            if (target.closest("#cs-custom-meta-btn")) {
                openCustomFieldMetaModal(overlay._character);
            }
        });

        document.getElementById("cs-edit-chat-btn")?.addEventListener("click", async () => {
            const currentCharacter = overlay._character;
            await reopenCharacterSheet(overlay, "editRuntime", currentCharacter);
        });

        document.getElementById("cs-edit-card-btn")?.addEventListener("click", async () => {
            const currentCharacter = overlay._character;
            await reopenCharacterSheet(overlay, "edit", currentCharacter);
        });

        document.getElementById("cs-user-create-btn")?.addEventListener("click", async () => {
            const created = await createUserSheetWithDefaults(context);            if (created) {
                csToast.info("{{user}} sheet created from the character/group stat schema — set the initial values, then press Save this chat.");
                await reopenCharacterSheet(overlay, "editRuntime", makeUserEntity());
            } else {
                csToast.error("Could not create the {{user}} sheet (no active chat or it already exists).");
            }
        });

        document.getElementById("cs-reset-user-btn")?.addEventListener("click", async () => {
            if (!await csConfirm(
                "Reset the {{user}} runtime state in THIS chat to the stat schema defaults?\n\nCurrent values (damage, spent items, custom, ...) will be lost. No Character Card exists for the user."
            )) return;

            const ok = await resetUserState(context);

            if (ok) {
                csToast.success("{{user}} runtime state reset to stat schema defaults.");
            } else {
                csToast.warning("User reset skipped: no stat schema available or no user state yet.");
            }

            await reopenCharacterSheet(overlay, "view", overlay._character);
        });

        document.getElementById("cs-user-add-missing-btn")?.addEventListener("click", async () => {
            const added = await addMissingCommonUserStats(context);

            if (added > 0) {
                csToast.success(csT("Added {n} missing group stat(s) to the {{user}} sheet.", { n: added }));
                await reopenCharacterSheet(overlay, "view", overlay._character);
            } else {
                csToast.info("No missing stats to add right now.");
            }
        });

        /* v2.0.23: "✕ Never" — the offered missing stats are INTENTIONALLY
           absent from this sheet. Persisted per chat + entity in
           chatMetadata; the note reappears only for stats that are not in
           the dismissed list (e.g. the group schema grows later). */
        document.getElementById("cs-user-dismiss-missing-btn")?.addEventListener("click", async () => {
            const names = missingCommonStats.map(entry => entry.name);

            if (!names.length) return;

            await dismissSchemaDiffStats(context, entityKey, names);
            csToast.info(csT("{n} stat(s) will not be offered again in this chat.", { n: names.length }));
            await reopenCharacterSheet(overlay, "view", overlay._character);
        });

        document.getElementById("cs-copy-btn")?.addEventListener("click", async () => {
            try {
                await copyCharacterSchema(overlay._character, state);
                csToast.success("Full Character State schema copied.");
            } catch (error) {
                console.error("[Character State] Copy failed:", error);
                csToast.error(csT("Copy failed: {error}", { error: error.message || error }));
            }
        });

        document.getElementById("cs-paste-btn")?.addEventListener("click", async () => {
            try {
                /* Field payload detection (v2.0.14): the SAME dialog gains an
                   explicit "⧉ Paste these fields" choice at the top when the
                   clipboard holds copied fields — no hidden routing. */
                let fieldPayload = null;

                try {
                    fieldPayload = parseFieldCopyPayload(await navigator.clipboard.readText());
                } catch {
                    /* clipboard unreadable → schema paste as before */
                }

                const mode = await promptPasteMode(overlay._character?.name || csT("this character"), fieldPayload);
                if (!mode) return;

                if (mode === "__field__") {
                    overlay.remove();
                    await openFieldPasteModal(fieldPayload, overlay._character);
                    return;
                }
                if (!mode) return;

                if (mode === "clear_replace") {
                    const character = overlay._character;
                    const entityKey = getStateEntityKey(character);

                    if (entityKey) {
                        clearCharacterChatState(context, entityKey);
                        pushWholeAudit(context, entityKey, "manual", "clear");
                        await saveChatState(context);
                        csToast.info("Current chat state cleared. Pasting the clipboard now…");
                    }
                }

                await pasteCharacterSchema(overlay._character, mode === "clear_replace" ? "replace" : mode);
                csToast.success(
                    mode === "clear_replace"
                        ? csT("Cleared and pasted: the clipboard is now this character's full state.")
                        : mode === "merge"
                            ? csT("Merge paste applied: existing stats overwritten + new stats added; skills/inventory/custom untouched.")
                            : mode === "overlay"
                                ? csT("Overlay paste applied: existing stats were overwritten in place; skills/inventory/custom untouched.")
                                : csT("Character State schema pasted.")
                );
                await reopenCharacterSheet(overlay, "view", overlay._character);
            } catch (error) {
                console.error("[Character State] Paste failed:", error);
                csToast.error(csT("Paste failed: {error}", { error: error.message || error }));
            }
        });

        document.getElementById("cs-reset-btn")?.addEventListener("click", async () => {
            const currentCharacter = overlay._character;

            if (!await csConfirm(csT(
                "Reset {name}'s runtime state in THIS chat to the Character Card defaults?\n\nCurrent chat values (damage, spent items, ...) will be lost. The Character Card itself is not modified.",
                { name: currentCharacter?.name || csT("this character") }
            ))) return;

            try {
                const ok = await resetCharacterState(currentCharacter);

                if (ok) {
                    csToast.success("Runtime state reset to Character Card defaults.");
                } else {
                    csToast.warning("Reset skipped: no active chat with a runtime state yet.");
                }

                await reopenCharacterSheet(overlay, "view", currentCharacter);
            } catch (error) {
                console.error("[Character State] Reset failed:", error);
                csToast.error(csT("Reset failed: {error}", { error: error.message || error }));
            }
        });

        document.getElementById("cs-push-btn")?.addEventListener("click", async () => {
            const currentCharacter = overlay._character;

            if (!currentCharacter) return;

            if (!await csConfirm(csT(
                "Copy the current chat runtime of {name} into the Character Card defaults?\n\nThe card default becomes the current Base values (chat Mod/states are not included). The chat runtime itself stays as-is.",
                { name: currentCharacter.name }
            ))) return;

            try {
                await ensureCharacterState(currentCharacter);
                const runtime = getCharacterState(currentCharacter);

                /* Push replaces the whole card startingState: refusing to
                   run on a runtime without stats prevents silently wiping
                   card stats (custom-only/empty runtimes must be reset or
                   edited first). */
                const runtimeStatsCount = Object.keys(runtime?.stats || {}).length;

                if (!runtimeStatsCount) {
                    csToast.error("This chat runtime has no stats to push. Use ⋯ ▸ Reset this chat from the card (or Edit ▸ this chat's state) first.");
                    return;
                }

                const starting = buildStartingStateFromRuntimeState(runtime);

                if (!hasStartingStateData(starting)) {
                    csToast.error("This chat runtime is empty — nothing to push.");
                    return;
                }

                setCardStateData(currentCharacter, starting);

                const cardWritten = await persistCharacterCardStartingState(
                    currentCharacter,
                    structuredClone(starting)
                );

                if (cardWritten) {
                    csToast.success("Character Card defaults written from this chat runtime.");
                } else {
                    csToast.error("Character Card file could not be written — defaults kept in memory only and will NOT appear in new chats. Check the console for errors.");
                }

                await reopenCharacterSheet(overlay, "view", currentCharacter);
            } catch (error) {
                console.error("[Character State] Push failed:", error);
                csToast.error(csT("Push failed: {error}", { error: error.message || error }));
            }
        });

        document.getElementById("cs-recover-defaults-btn")?.addEventListener("click", async () => {
            const viewed = overlay._character;

            const recovered = await attemptCardDefaultRecovery(viewed, true);

            overlay.remove();

            if (recovered) {
                csToast.success("Defaults recovered into the Character Card; this chat has been seeded.");
            } else {
                csToast.info("No defaults found in other chats of this character. Use Edit ▸ card defaults or ⋯ ▸ Paste schema to create them.");
            }

            await openCharacterSheet("view", viewed);
        });

        return;
    }

    setupCharacterSheetDragDrop(overlay);

    /* Insert-above / insert-below buttons live on every row, including
       rows added later, so one delegated listener covers all of them. */
    overlay.addEventListener("click", event => {
        const button = event.target.closest?.(".cs-insert-above, .cs-insert-below");
        if (!button) return;

        const row = button.closest(".cs-edit-stat-row, .cs-edit-skill-row, .cs-edit-item-row");
        if (!row || !overlay.contains(row)) return;

        const position = button.classList.contains("cs-insert-above") ? "before" : "after";

        if (row.classList.contains("cs-edit-stat-row")) {
            openStatModal({ mode: "add", anchorRow: row, position });
        } else if (row.classList.contains("cs-edit-skill-row")) {
            addSkillEditorRow(overlay, row, position);
        } else if (row.classList.contains("cs-edit-item-row")) {
            addInventoryEditorRow(overlay, row, position);
        }
    });

    /* Per-row Mod→Base fold (runtime editor only): updates the inputs
       in place — the change persists when Save Chat runs. */
    overlay.addEventListener("click", event => {
        const button = event.target.closest?.(".cs-mod-to-base-edit");
        if (!button) return;

        const row = button.closest(".cs-edit-stat-row");
        if (!row || !overlay.contains(row)) return;

        const baseInput = row.querySelector(".cs-edit-base");
        const modInput = row.querySelector(".cs-edit-mod");
        const base = Number(baseInput?.value);
        const mod = Number(modInput?.value);

        if (Number.isFinite(base) && Number.isFinite(mod) && mod !== 0) {
            baseInput.value = String(base + mod);
            modInput.value = "0";
        }
    });

    document.getElementById("cs-cancel-btn")?.addEventListener("click", async () => {
        const currentCharacter = overlay._character;
        await reopenCharacterSheet(overlay, "view", currentCharacter);
    });

    document.getElementById("cs-save-btn")?.addEventListener("click", async () => {
        if (overlay.dataset.mode === "editRuntime") {
            await saveRuntimeChatEditor(overlay);
        } else {
            await saveCharacterSheetEditor(overlay);
        }
    });

    document.getElementById("cs-add-stat")?.addEventListener("click", () => {
        openStatModal({ mode: "add" });
    });

    document.getElementById("cs-add-skill")?.addEventListener("click", () => {
        addSkillEditorRow(overlay);
    });

    document.getElementById("cs-add-item")?.addEventListener("click", () => {
        addInventoryEditorRow(overlay);
    });

    document.getElementById("cs-apply-all-mod-to-base")?.addEventListener("click", () => {
        const rows = overlay.querySelectorAll("#cs-edit-stats .cs-edit-stat-row");
        let foldedCount = 0;

        for (const row of rows) {
            const baseInput = row.querySelector(".cs-edit-base");
            const modInput = row.querySelector(".cs-edit-mod");
            const base = Number(baseInput?.value);
            const mod = Number(modInput?.value);

            if (Number.isFinite(base) && Number.isFinite(mod) && mod !== 0) {
                baseInput.value = String(base + mod);
                modInput.value = "0";
                foldedCount += 1;
            }
        }

        if (!foldedCount) {
            csToast.info("No Mod values to fold.");
            return;
        }

        csToast.success(csT("{n} stat(s) folded into Base — press Save this chat to keep.", { n: foldedCount }));
    });

    document.getElementById("cs-clear-stats")?.addEventListener("click", async () => {
        const rows = overlay.querySelectorAll("#cs-edit-stats .cs-edit-stat-row");
        if (!rows.length) return csToast.info("No stats to clear.");
        if (await csConfirm(csT("Delete all {n} stat(s) from this editor?", { n: rows.length }))) {
            rows.forEach(row => row.remove());
            /* v2.0.20: make the save step explicit — an unsaved clear looks
               like "nothing happened" the moment the editor is reopened. */
            csToast.warning(csT("{n} stat(s) removed from the editor — press the SAVE button to keep this.", { n: rows.length }), "Character State", { timeOut: 6000 });
        }
    });

    document.getElementById("cs-clear-skills")?.addEventListener("click", async () => {
        const rows = overlay.querySelectorAll("#cs-edit-skills .cs-edit-skill-row");
        if (!rows.length) return csToast.info("No skills to clear.");
        if (await csConfirm(csT("Delete all {n} skill(s) from this editor?", { n: rows.length }))) {
            rows.forEach(row => row.remove());
        }
    });

    document.getElementById("cs-clear-items")?.addEventListener("click", async () => {
        const rows = overlay.querySelectorAll("#cs-edit-inventory .cs-edit-item-row");
        if (!rows.length) return csToast.info("No items to clear.");
        if (await csConfirm(csT("Delete all {n} item(s) from this editor?", { n: rows.length }))) {
            rows.forEach(row => row.remove());
        }
    });

    overlay.querySelectorAll(".cs-edit-stat").forEach(button => {
        button.addEventListener("click", () => {
            const row = button.closest(".cs-edit-stat-row");
            if (!row) return;

            const originalName = row.dataset.originalName || "";
            const stat = row._statDefinition || state.stats[originalName];

            if (stat) {
                openStatModal({
                    mode: "edit",
                    stat: structuredClone(stat),
                    row
                });
            }
        });
    });

    overlay.querySelectorAll(".cs-remove-stat").forEach(button => {
        button.addEventListener("click", async () => {
            const row = button.closest(".cs-edit-stat-row");
            const name = row?.dataset.originalName || row?.querySelector(".cs-edit-stat-name-input")?.value?.trim();
            if (!row || !name) return;

            if (!await csConfirm(csT("Delete \"{name}\"?\n\nThis will remove this stat from the character's sheet.", { name }))) return;
            row.remove();
        });
    });

    /* ---- Field copy / paste (v2.0.14) ---- */

    const collectRowField = row => {
        if (!row) return null;

        const name = row.querySelector(".cs-edit-stat-name-input")?.value?.trim() || row.dataset.originalName || "";

        if (!name) return null;

        /* row._statDefinition NEVER survives the outerHTML round-trip in
           renderStatsEditor — same trap the ✎ modal already handles with
           its fallback to the live state definition. */
        const definition = row._statDefinition || state.stats?.[name];

        if (!definition) return null;

        return { name, definition };
    };

    const readStatBaseFromRow = row => {
        if (!row) return undefined;
        const select = row.querySelector(".cs-edit-base-select");
        if (select) return select.value;
        const checkbox = row.querySelector(".cs-edit-base-checkbox");
        if (checkbox) return checkbox.checked;
        const input = row.querySelector(".cs-edit-base");
        return input ? input.value : undefined;
    };

    overlay.querySelectorAll(".cs-copy-stat").forEach(button => {
        button.addEventListener("click", async () => {
            const row = button.closest(".cs-edit-stat-row");
            const collected = collectRowField(row);

            if (!collected) {
                csToast.warning(csT("Cannot copy: stat definition for this row was not found (row: \"{name}\").", { name: row?.querySelector(".cs-edit-stat-name-input")?.value?.trim() || "?" }));
                return;
            }

            try {
                const payload = buildFieldCopyPayload(overlay._character, { [collected.name]: collected.definition }, {
                    [collected.name]: readStatBaseFromRow(row)
                });
                const payloadText = JSON.stringify(payload, null, 2);
                const ok = await copyTextToClipboard(payloadText);

                if (ok) {
                    csToast.success(csT("Field \"{name}\" copied — press Paste on a character and choose \"⧉ Paste these fields\".", { name: collected.name }));
                } else {
                    /* Clipboard blocked (non-secure context / permission):
                       the payload is still recoverable. */
                    console.warn("[Character State] Field copy payload (clipboard blocked):\n", payloadText);
                    openClipboardFallbackModal(csT("Field \"{name}\"", { name: collected.name }), payloadText);
                }
            } catch (error) {
                console.error("[Character State] Field copy failed:", error);
                csToast.error(csT("Field copy failed: {error}", { error: error.message || error }));
            }
        });
    });

    const selectToggle = document.getElementById("cs-stat-select-toggle");
    const copySelectedButton = document.getElementById("cs-copy-selected");
    const saveComponentButton = document.getElementById("cs-save-selection-component");

    selectToggle?.addEventListener("click", () => {
        const list = document.getElementById("cs-edit-stats");
        const on = list?.classList.toggle("cs-select-mode");

        if (selectToggle) selectToggle.textContent = on ? `▣ ${csT("Cancel")}` : `▣ ${csT("Select")}`;

        if (copySelectedButton) copySelectedButton.style.display = on ? "" : "none";
        if (saveComponentButton) saveComponentButton.style.display = on ? "" : "none";
    });

    const collectSelectedFields = () => {
        const picked = {};
        const overrides = {};

        overlay.querySelectorAll(".cs-edit-stat-row").forEach(row => {
            if (!row.querySelector(".cs-stat-select")?.checked) return;

            const collected = collectRowField(row);
            if (!collected) return;

            picked[collected.name] = collected.definition;
            overrides[collected.name] = readStatBaseFromRow(row);
        });

        return { picked, overrides };
    };

    copySelectedButton?.addEventListener("click", async () => {
        const { picked, overrides } = collectSelectedFields();
        const count = Object.keys(picked).length;

        if (!count) {
            csToast.info("No fields selected — tick the checkboxes next to the fields you want.");
            return;
        }

        try {
            const payloadText = JSON.stringify(buildFieldCopyPayload(overlay._character, picked, overrides), null, 2);
            const ok = await copyTextToClipboard(payloadText);

            if (ok) {
                csToast.success(csT("{n} field(s) copied — press Paste on a character and choose \"⧉ Paste these fields\".", { n: count }));
            } else {
                console.warn("[Character State] Field copy payload (clipboard blocked):\n", payloadText);
                openClipboardFallbackModal(csT("{n} field(s)", { n: count }), payloadText);
            }
        } catch (error) {
            console.error("[Character State] Field copy failed:", error);
            csToast.error(csT("Field copy failed: {error}", { error: error.message || error }));
        }
    });

    saveComponentButton?.addEventListener("click", async () => {
        const { picked, overrides } = collectSelectedFields();
        const count = Object.keys(picked).length;

        if (!count) {
            csToast.info("No fields selected — tick the checkboxes next to the fields you want.");
            return;
        }

        const name = await csPrompt(csT("Component name ({n} field(s)):", { n: count }), `${overlay._character?.name || "component"} fields`);

        if (!name || !name.trim()) return;

        /* Values become the component's defaults — applyComponentToSchema
           seeds new sheets with them. */
        const componentFields = {};

        for (const [fieldName, definition] of Object.entries(picked)) {
            const clone = structuredClone(definition);
            clone.base = overrides[fieldName] !== undefined && overrides[fieldName] !== "" ? overrides[fieldName] : definition.base;
            componentFields[fieldName] = clone;
        }

        const result = saveComponent(name.trim(), componentFields);

        if (result.ok) {
            csToast.success(result.overwritten ? csT("Component \"{name}\" overwritten.", { name: name.trim() }) : csT("Component \"{name}\" saved (🧩).", { name: name.trim() }));
        } else {
            csToast.error(csT("Component not saved: {reason}", { reason: result.reason }));
        }
    });

    overlay.querySelectorAll(".cs-remove-skill").forEach(button => {
        button.addEventListener("click", async () => {
            const row = button.closest(".cs-edit-skill-row");
            if (!row) return;

            const name = row.querySelector(".cs-edit-skill-name")?.value.trim() || csT("this skill");
            if (!await csConfirm(csT("Delete \"{name}\"?", { name }))) return;
            row.remove();
        });
    });

    overlay.querySelectorAll(".cs-remove-item").forEach(button => {
        button.addEventListener("click", async () => {
            const row = button.closest(".cs-edit-item-row");
            if (!row) return;

            const name = row.querySelector(".cs-edit-item-name")?.value.trim() || csT("this item");
            if (!await csConfirm(csT("Delete \"{name}\"?", { name }))) return;
            row.remove();
        });
    });

    /* Card editor: Mod is runtime-only and is always 0 on the card, so the
       Mod field is locked. The runtime editor keeps Mod editable. */
    if (mode === "edit") {
        overlay.querySelectorAll(".cs-edit-mod").forEach(input => {
            input.disabled = true;
            input.title = csT("Mod is chat runtime-only. Defaults use Base.");
        });

        /* Folding Mod→Base is meaningless on the card (Mod is always 0). */
        overlay.querySelectorAll(".cs-mod-to-base-edit").forEach(button => {
            button.remove();
        });

        document.getElementById("cs-apply-all-mod-to-base")?.remove();
    } else {
        overlay.querySelectorAll(".cs-edit-mod").forEach(input => {
            input.disabled = false;
            input.title = csT("Mod of the chat runtime (Eff. = Base + Mod).");
        });
    }

    updateAllEquippableUI(overlay);
}

/* =========================================================
   SHEET VIEW v3 — header menus, tabs, stat rows, effects panel
   Every action keeps its historical button id (cs-edit-card-btn,
   cs-push-btn, …): the buttons only MOVED into menus, so all wiring in
   openCharacterSheet and every test keep working unchanged.
========================================================= */

/* Session-scoped UI memory (never persisted): last tab, group per entity,
   and the restore payload for an in-place sheet refresh. */
const sheetUiMemory = {
    tab: "stats",
    groupByEntity: new Map(),
    pendingRestore: null
};

function csIcon(name) {
    return `<i class="fa-solid fa-${name}" aria-hidden="true"></i>`;
}

function renderMenuItem({ id, icon, label, hint = "", danger = false, active = false, extraClass = "" }) {
    return `
        <button class="cs-menu-item${danger ? " cs-menu-item-danger" : ""}${active ? " cs-menu-item-active" : ""}${extraClass ? ` ${extraClass}` : ""}" id="${id}" type="button" role="menuitem">
            ${csIcon(icon)}
            <span class="cs-menu-item-label">${escapeHtml(label)}</span>
            ${hint ? `<span class="cs-menu-item-hint">${escapeHtml(hint)}</span>` : ""}
        </button>`;
}

function renderHeaderMenu({ key, icon, label, items, primary = false, iconOnly = false, align = "end" }) {
    const body = items.filter(Boolean).join("");
    if (!body.trim()) return "";

    return `
        <div class="cs-menu" data-cs-menu="${key}">
            <button class="cs-chip cs-menu-trigger${primary ? " cs-chip-primary" : ""}${iconOnly ? " cs-chip-icon" : ""}" type="button"
                aria-haspopup="menu" aria-expanded="false" title="${escapeHtml(label)}" aria-label="${escapeHtml(label)}">
                ${csIcon(icon)}${iconOnly ? "" : `<span class="cs-chip-label">${escapeHtml(label)}</span>${csIcon("caret-down cs-caret")}`}
            </button>
            <div class="cs-menu-popover cs-menu-align-${align}" role="menu" hidden>${body}</div>
        </div>`;
}

function renderMenuHeading(text) {
    return `<div class="cs-menu-heading">${escapeHtml(text)}</div>`;
}

const MENU_SEPARATOR = `<div class="cs-menu-sep" role="separator"></div>`;

/*
 * Header actions for VIEW mode. Six visible controls (clock, Edit, History,
 * World, More, Close); everything else lives in a menu.
 */
function renderSheetHeaderActions(options) {
    const {
        isUser, isSideNpc, canHostUser, hasUserState, showRecover,
        modToBaseUiEnabled, tokenEstimate
    } = options;

    const editItems = [];

    if (isUser) {
        editItems.push(renderMenuItem({ id: "cs-edit-chat-btn", icon: "pen", label: csT("Edit this chat's state"), hint: "{{user}}" }));
    } else {
        editItems.push(renderMenuItem({ id: "cs-edit-chat-btn", icon: "pen", label: csT("Edit this chat's state") }));
        if (!isSideNpc) {
            editItems.push(renderMenuItem({ id: "cs-edit-card-btn", icon: "id-card", label: csT("Edit the card defaults (new chats)") }));
        }
    }

    const historyItems = [
        renderMenuItem({ id: "cs-log-btn", icon: "list", label: csT("Change log") }),
        renderMenuItem({ id: "cs-timeline-btn", icon: "timeline", label: csT("Timeline") }),
        MENU_SEPARATOR,
        renderMenuItem({ id: "cs-snapshots-btn", icon: "clock-rotate-left", label: csT("Snapshots") }),
        renderMenuItem({ id: "cs-snapshot-now-btn", icon: "camera", label: csT("Take snapshot now") })
    ];

    const worldItems = [
        renderMenuItem({ id: "cs-world-btn", icon: "earth-asia", label: csT("World overview") }),
        renderMenuItem({ id: "cs-scenes-btn", icon: "clapperboard", label: csT("Scenes") }),
        canHostUser ? renderMenuItem({ id: "cs-side-npc-btn", icon: "user-plus", label: csT("Add side NPC") }) : "",
        canHostUser && !isUser && !hasUserState
            ? renderMenuItem({ id: "cs-user-create-btn", icon: "user", label: csT("Create user sheet"), hint: "{{user}}" })
            : ""
    ];

    const moreItems = [
        renderMenuHeading(csT("Schema")),
        renderMenuItem({ id: "cs-copy-btn", icon: "copy", label: csT("Copy schema") }),
        renderMenuItem({ id: "cs-paste-btn", icon: "paste", label: csT("Paste schema…") }),
        renderMenuItem({ id: "cs-presets-btn", icon: "bookmark", label: csT("Presets…") }),
        !isUser && !isSideNpc ? renderMenuItem({ id: "cs-components-btn", icon: "puzzle-piece", label: csT("Components…") }) : "",
        MENU_SEPARATOR,
        renderMenuHeading(isUser || isSideNpc ? csT("This chat") : csT("Card ⇄ Chat"))
    ];

    if (isUser) {
        moreItems.push(renderMenuItem({ id: "cs-reset-user-btn", icon: "rotate-left", label: csT("Reset this chat from the card…"), hint: csT("schema"), danger: true }));
    } else if (isSideNpc) {
        moreItems.push(renderMenuItem({ id: "cs-side-npc-delete-btn", icon: "trash", label: csT("Delete this side NPC…"), danger: true }));
    } else {
        moreItems.push(renderMenuItem({ id: "cs-push-btn", icon: "upload", label: csT("Save this chat as the card defaults…") }));
        moreItems.push(renderMenuItem({ id: "cs-reset-btn", icon: "rotate-left", label: csT("Reset this chat from the card…"), danger: true }));
        if (showRecover) {
            moreItems.push(renderMenuItem({ id: "cs-recover-defaults-btn", icon: "life-ring", label: csT("Recover card defaults…") }));
        }
    }

    moreItems.push(renderMenuItem({ id: "cs-mod-to-base-all-btn", icon: "arrow-down-short-wide", label: csT("Fold Mod into Base (all stats)…") }));
    moreItems.push(renderMenuItem({
        id: "cs-mod-to-base-toggle",
        icon: modToBaseUiEnabled ? "toggle-on" : "toggle-off",
        label: modToBaseUiEnabled ? csT("Hide per-stat fold column") : csT("Show per-stat fold column"),
        active: modToBaseUiEnabled
    }));
    moreItems.push(MENU_SEPARATOR);

    if (tokenEstimate) {
        moreItems.push(renderMenuItem({
            id: "cs-token-btn",
            icon: "calculator",
            label: csT("Token estimate"),
            hint: Number.isFinite(tokenEstimate.totalTokens) ? formatTokenCount(tokenEstimate.totalTokens) : ""
        }));
    }

    moreItems.push(renderMenuItem({ id: "cs-settings-btn", icon: "gear", label: csT("Settings") }));

    return [
        renderHeaderMenu({ key: "edit", icon: "pen", label: csT("Edit"), items: editItems, primary: true }),
        renderHeaderMenu({ key: "history", icon: "clock-rotate-left", label: csT("History"), items: historyItems }),
        renderHeaderMenu({ key: "world", icon: "earth-asia", label: csT("World"), items: worldItems }),
        renderHeaderMenu({ key: "more", icon: "ellipsis", label: csT("More"), items: moreItems, iconOnly: true })
    ].join("");
}

function renderSheetTabs(tabs, activeTab) {
    return `
        <div class="cs-tabs" role="tablist">
            ${tabs.map(tab => `
                <button class="cs-tab${tab.key === activeTab ? " active" : ""}" type="button" role="tab"
                    data-cs-tab="${tab.key}" aria-selected="${tab.key === activeTab ? "true" : "false"}">
                    ${csIcon(tab.icon)}
                    <span class="cs-tab-label">${escapeHtml(tab.label)}</span>
                    ${tab.count !== undefined && tab.count !== null ? `<span class="cs-tab-count">${escapeHtml(String(tab.count))}</span>` : ""}
                </button>`).join("")}
        </div>`;
}

/* ---- stat rows (view) ---------------------------------------------------- */

function getStatGroupLayout(state) {
    const entries = Object.entries(state.stats || {});
    const groupOrder = [];
    const byGroup = new Map();

    for (const [name, stat] of entries) {
        const group = String(stat?.group ?? "").trim() || "Other";

        if (!byGroup.has(group)) {
            byGroup.set(group, []);
            groupOrder.push(group);
        }

        byGroup.get(group).push([name, stat]);
    }

    const hasGroups = getExtensionSettings().groupsEnabled && (
        groupOrder.length > 1 ||
        (groupOrder.length === 1 && groupOrder[0] !== "Other")
    );

    return { entries, groupOrder, byGroup, hasGroups };
}

function renderStatTrend(points) {
    if (!Array.isArray(points) || points.length < 2) return "";

    const last = Number(points[points.length - 1]?.eff);
    const previous = Number(points[points.length - 2]?.eff);
    const delta = last - previous;

    if (!Number.isFinite(delta) || delta === 0) return "";

    const up = delta > 0;
    return `<span class="cs-trend cs-trend-${up ? "up" : "down"}" title="${escapeHtml(`${up ? "+" : ""}${formatPlainValue(delta)}`)}">${up ? "▲" : "▼"}${escapeHtml(formatPlainValue(Math.abs(delta)))}</span>`;
}

function renderStatRowHtml(name, stat, state, entityKey, group, showFold) {
    const context = SillyTavern.getContext();
    const quickHtml = entityKey ? renderQuickControlsHtml(name, stat, getPinnedStatNames(context, entityKey).includes(name)) : "";
    const descText = applyCsMacros(String(stat.description || "")).trim();
    const search = escapeHtml(`${applyCsMacros(name)} ${name}`.toLowerCase());
    const nameHtml = renderRichText(name);

    const nameLabel = entityKey
        ? `<span class="cs-stat-name-label" data-cs-stat-name="${escapeHtml(name)}" role="button" tabindex="0" title="${escapeHtml(csT("History graph"))}">${nameHtml}</span>`
        : `<span class="cs-stat-name-text">${nameHtml}</span>`;

    const descriptionHtml = descText
        ? `<p class="cs-stat-desc">${renderRichText(stat.description || "")}</p>`
        : `<p class="cs-stat-desc cs-stat-desc-empty">${escapeHtml(csT("No description."))}</p>`;

    if (stat.type === "number") {
        const base = Number(stat.base || 0);
        const mod = Number(stat.mod || 0);
        const effectDelta = getEffectDeltaForStat(state, name);
        const total = base + mod + effectDelta;
        const unit = stat.unit ? ` ${escapeHtml(stat.unit)}` : "";
        const max = stat.max !== null && stat.max !== undefined && Number.isFinite(Number(stat.max)) && Number(stat.max) !== 0
            ? Number(stat.max)
            : null;

        const points = entityKey ? getStatHistory(context, entityKey, name) : [];
        const sparkline = points.length > 1 ? renderStatSparkline(points, 64, 18) : "";

        const progress = stat.progressBar?.enabled && max !== null
            ? renderStatProgressBar(stat, total, { text: false })
            : "";

        const signed = value => `${value > 0 ? "+" : ""}${formatNumber(value)}`;
        const fold = showFold && mod !== 0
            ? `<button class="cs-mod-to-base-row-btn cs-mini-btn" type="button" data-cs-stat-name="${escapeHtml(name)}" title="${csH("Base += Mod, Mod = 0")}">${csIcon("arrow-down-short-wide")} ${escapeHtml(csT("Fold Mod into Base"))}</button>`
            : "";

        return `
            <div class="cs-stat-row" data-cs-stat-row data-cs-search="${search}" data-cs-group-of="${escapeHtml(group)}" data-cs-stat-key="${escapeHtml(name)}">
                <div class="cs-stat-main">
                    <div class="cs-stat-title">${nameLabel}</div>
                    ${sparkline ? `<span class="cs-stat-spark">${sparkline}</span>` : ""}
                    <button class="cs-stat-value" type="button" aria-expanded="false" title="${escapeHtml(descText || csT("Description"))}">
                        <b>${formatNumber(total)}</b>${max !== null ? `<small> / ${formatNumber(max)}</small>` : ""}${unit ? `<small>${unit}</small>` : ""}
                        ${effectDelta ? `<span class="cs-eff-delta cs-eff-delta-${effectDelta > 0 ? "gain" : "loss"}">(${signed(effectDelta)})</span>` : ""}
                        ${renderStatTrend(points)}
                        ${mod !== 0 && showFold ? `<span class="cs-fold-dot" title="Mod ${escapeHtml(signed(mod))}"></span>` : ""}
                    </button>
                </div>
                ${progress}
                <div class="cs-stat-detail" hidden>
                    <div class="cs-stat-breakdown">
                        <span>${escapeHtml(csT("Base"))} <b>${formatNumber(base)}</b></span>
                        <span>${escapeHtml(csT("Mod"))} <b class="${mod > 0 ? "cs-positive" : mod < 0 ? "cs-negative" : ""}">${mod ? signed(mod) : "0"}</b></span>
                        ${effectDelta ? `<span>${escapeHtml(csT("Effects"))} <b class="${effectDelta > 0 ? "cs-positive" : "cs-negative"}">${signed(effectDelta)}</b></span>` : ""}
                        ${stat.min !== null && stat.min !== undefined && max !== null ? `<span class="cs-stat-range">${formatNumber(Number(stat.min) || 0)} … ${formatNumber(max)}</span>` : ""}
                        ${fold}
                    </div>
                    ${quickHtml}
                    ${descriptionHtml}
                </div>
            </div>`;
    }

    return `
        <div class="cs-stat-row cs-stat-row-text" data-cs-stat-row data-cs-search="${search}" data-cs-group-of="${escapeHtml(group)}" data-cs-stat-key="${escapeHtml(name)}">
            <div class="cs-stat-main">
                <div class="cs-stat-title"><span class="cs-stat-name-text">${nameHtml}</span></div>
                <button class="cs-stat-value cs-stat-value-text cs-non-number-value" type="button" aria-expanded="false" title="${escapeHtml(descText || csT("Description"))}">${formatNonNumberValue(stat)}</button>
            </div>
            <div class="cs-stat-detail" hidden>${quickHtml}${descriptionHtml}</div>
        </div>`;
}

function renderStatsEmptyState(isUser, isSideNpc) {
    const cardPath = !isUser && !isSideNpc;

    return `
        <div class="cs-onboarding">
            <div class="cs-onboarding-title">${escapeHtml(csT("This sheet has no stats yet"))}</div>
            <div class="cs-onboarding-sub">${escapeHtml(csT("Pick one way to build it:"))}</div>
            <div class="cs-onboarding-options">
                <button class="cs-onboarding-option" type="button" data-cs-onboard="presets">
                    ${csIcon("bookmark")}
                    <b>${escapeHtml(csT("Start from a genre preset"))}</b>
                    <span>${escapeHtml(csT("Fantasy, System, Cultivation, Survival, Romance… one click, then adjust."))}</span>
                </button>
                <button class="cs-onboarding-option" type="button" data-cs-onboard="${cardPath ? "card" : "chat"}">
                    ${csIcon("pen-ruler")}
                    <b>${escapeHtml(csT("Design it by hand"))}</b>
                    <span>${escapeHtml(csT("Open the card editor and add stats one by one."))}</span>
                </button>
                <button class="cs-onboarding-option" type="button" data-cs-onboard="paste">
                    ${csIcon("paste")}
                    <b>${escapeHtml(csT("Paste a schema"))}</b>
                    <span>${escapeHtml(csT("Paste a schema you copied from another character or preset."))}</span>
                </button>
                <button class="cs-onboarding-option" type="button" data-cs-onboard="ai">
                    ${csIcon("wand-magic-sparkles")}
                    <b>${escapeHtml(csT("Let the AI design it"))}</b>
                    <span>${escapeHtml(csT("Arm one-shot AI sheet creation in Settings, then ask the AI in chat."))}</span>
                </button>
            </div>
        </div>`;
}

function renderStatsViewV3(state, entityKey, { isUser = false, isSideNpc = false } = {}) {
    const { entries, groupOrder, byGroup, hasGroups } = getStatGroupLayout(state);
    const effects = getActiveEffects(state);
    const effectStrip = effects.length ? renderActiveEffectsChips(state, { withAdd: false }) : "";

    if (!entries.length) {
        return `${effectStrip}${renderStatsEmptyState(isUser, isSideNpc)}`;
    }

    const showFold = getModToBaseUiEnabled();
    const rememberedGroup = sheetUiMemory.groupByEntity.get(entityKey);
    const activeGroup = hasGroups
        ? (rememberedGroup === "__all__" || groupOrder.includes(rememberedGroup) ? rememberedGroup : groupOrder[0])
        : "__all__";

    const pills = hasGroups ? `
        <div class="cs-group-tabs" role="tablist">
            <button class="cs-group-tab${activeGroup === "__all__" ? " active" : ""}" type="button" data-cs-group="__all__">${escapeHtml(csT("All"))}<span class="cs-group-count">${entries.length}</span></button>
            ${groupOrder.map(group => `
                <button class="cs-group-tab${group === activeGroup ? " active" : ""}" type="button" data-cs-group="${escapeHtml(group)}">${escapeHtml(group === "Other" ? csT("Ungrouped") : group)}<span class="cs-group-count">${byGroup.get(group).length}</span></button>`).join("")}
        </div>` : "";

    const rows = (hasGroups ? groupOrder : ["__flat__"]).map(group => {
        const list = hasGroups ? byGroup.get(group) : entries;
        return list.map(([name, stat]) => renderStatRowHtml(name, stat, state, entityKey, hasGroups ? group : "__all__", showFold)).join("");
    }).join("");

    return `
        ${effectStrip}
        ${entityKey ? renderPinnedStripHtml(state, entityKey) : ""}
        <div class="cs-stat-toolbar">
            ${pills}
            <label class="cs-stat-filter">
                ${csIcon("magnifying-glass")}
                <input id="cs-stat-filter" class="text_pole" type="search" placeholder="${escapeHtml(csT("Filter stats…"))}" autocomplete="off" />
            </label>
        </div>
        <div class="cs-stat-list" data-cs-active-group="${escapeHtml(activeGroup)}">${rows}</div>
        <div class="cs-stat-filter-empty" hidden></div>`;
}

/* Group + filter visibility — pure DOM, no re-render. */
function applyStatListFilter(overlay) {
    const list = overlay.querySelector(".cs-stat-list");
    if (!list) return;

    const query = String(overlay.querySelector("#cs-stat-filter")?.value || "").trim().toLowerCase();
    const group = list.dataset.csActiveGroup || "__all__";
    let visible = 0;

    for (const row of list.querySelectorAll("[data-cs-stat-row]")) {
        const matchesQuery = !query || String(row.dataset.csSearch || "").includes(query);
        const matchesGroup = query || group === "__all__" || row.dataset.csGroupOf === group;
        const show = matchesQuery && matchesGroup;
        row.hidden = !show;
        if (show) visible += 1;
    }

    const empty = overlay.querySelector(".cs-stat-filter-empty");
    if (empty) {
        empty.hidden = visible > 0 || !query;
        empty.textContent = query ? csT("No stats match \"{q}\".", { q: query }) : "";
    }

    overlay.querySelector(".cs-group-tabs")?.classList.toggle("cs-group-tabs-dimmed", Boolean(query));
}

/* ---- effects panel (view) ----------------------------------------------- */

function renderEffectsPanelHtml(state) {
    const effects = getActiveEffects(state);

    const cards = effects.map(effect => {
        const editable = effect.source !== "item";
        const deltas = Object.entries(effect.stats || {})
            .map(([statName, delta]) => `<span class="cs-effect-delta ${Number(delta) >= 0 ? "cs-positive" : "cs-negative"}">${escapeHtml(applyCsMacros(statName))} ${Number(delta) > 0 ? "+" : ""}${escapeHtml(formatPlainValue(delta))}</span>`)
            .join("");
        const stack = effect.stack?.count > 1 ? `<span class="cs-effect-tag">×${escapeHtml(String(effect.stack.count))}</span>` : "";

        return `
            <div class="cs-effect-card cs-effect-chip cs-effect-${escapeHtml(effect.source)}${editable ? " cs-effect-editable" : ""}" data-cs-effect-id="${escapeHtml(effect.id)}" ${editable ? `role="button" tabindex="0"` : ""}>
                <div class="cs-effect-card-head">
                    <span class="cs-effect-card-name">${renderRichText(effect.name)}</span>
                    <span class="cs-effect-tag">${escapeHtml(effectSourceLabel(effect.source))}</span>
                    ${stack}
                    <span class="cs-effect-card-remaining">${escapeHtml(formatEffectRemainingUi(effect))}</span>
                    ${editable ? `<button class="cs-effect-remove cs-icon-btn" type="button" data-cs-effect-id="${escapeHtml(effect.id)}" title="${escapeHtml(csT("Delete"))}" aria-label="${escapeHtml(csT("Delete"))}">${csIcon("xmark")}</button>` : ""}
                </div>
                ${deltas ? `<div class="cs-effect-card-deltas">${deltas}</div>` : ""}
                ${effect.description ? `<div class="cs-effect-card-desc">${renderRichText(effect.description)}</div>` : ""}
            </div>`;
    }).join("");

    return `
        ${cards || `<div class="cs-empty-card"><div class="cs-empty-text">${escapeHtml(csT("No active effects"))}</div></div>`}
        <button class="cs-effect-add cs-add-row-btn" type="button">${csIcon("plus")} ${escapeHtml(csT("Add effect"))}</button>`;
}

/* =========================================================
   QUICK ADJUST + PINS + HUD (v3.1)
   - Quick adjust: change a value straight from the sheet view (number: Mod
     ±1 / ±10 with Shift, or set the value; choice / boolean / text set
     directly). User-owned edit: one audit entry per burst (800 ms debounce),
     one history point, one save — never a snapshot per tap.
   - Pins: ★ per stat, stored per chat + entity; pinned stats get a strip at
     the top of the Stats tab and the HUD above the chat input.
========================================================= */

const PINS_KEY = "character_state_pins";
const QUICK_EDIT_DEBOUNCE_MS = 800;
const quickEditBursts = new Map();

function getPinnedStatNames(context, entityKey) {
    const store = context?.chatMetadata?.[PINS_KEY];
    const list = store && typeof store === "object" && !Array.isArray(store) ? store[entityKey] : null;
    return Array.isArray(list) ? list.filter(name => typeof name === "string") : [];
}

async function togglePinnedStat(context, entityKey, statName) {
    if (!context?.chatMetadata || !entityKey) return false;

    if (!context.chatMetadata[PINS_KEY] || typeof context.chatMetadata[PINS_KEY] !== "object") {
        context.chatMetadata[PINS_KEY] = {};
    }

    const list = getPinnedStatNames(context, entityKey);
    const next = list.includes(statName) ? list.filter(name => name !== statName) : [...list, statName];

    if (next.length) context.chatMetadata[PINS_KEY][entityKey] = next;
    else delete context.chatMetadata[PINS_KEY][entityKey];

    await saveChatState(context);
    return next.includes(statName);
}

function statDisplayValue(state, stat) {
    if (stat?.type === "number") return Number(getEffectiveStatValue(state, stat));
    if (stat?.type === "boolean") return Boolean(stat.base);
    return String(stat?.base ?? "");
}

function liveStateForKey(context, entityKey) {
    const states = context?.chatMetadata?.character_states;
    return states && typeof states === "object" ? states[entityKey] || null : null;
}

/* Mutate first, report later: the burst keeps the value from BEFORE the
   first tap so the audit shows 62 → 70, not eight +1 rows. */
function applyQuickStatEdit(context, entityKey, statName, edit) {
    const state = liveStateForKey(context, entityKey);
    const stat = state?.stats?.[statName];
    if (!stat) return false;

    const burstKey = `${entityKey}\u0000${statName}`;
    if (!quickEditBursts.has(burstKey)) {
        quickEditBursts.set(burstKey, { before: statDisplayValue(state, stat), raw: JSON.stringify(stat), timer: null, chatId: currentChatIdSafe(), metadata: context.chatMetadata });
    }

    if (stat.type === "number") {
        const mod = Number(stat.mod || 0);
        const base = Number(stat.base || 0);

        if (Number.isFinite(edit.delta)) stat.mod = mod + edit.delta;
        else if (Number.isFinite(edit.value)) stat.mod = edit.value - base - getEffectDeltaForStat(state, statName);
        else return false;

        clampNumericStats(state);
    } else if (stat.type === "boolean") {
        stat.base = edit.value === undefined ? !stat.base : Boolean(edit.value);
    } else if (stat.type === "choice") {
        if (!stat.options?.includes(edit.value)) return false;
        stat.base = edit.value;
    } else {
        stat.base = String(edit.value ?? "");
    }

    const burst = quickEditBursts.get(burstKey);
    clearTimeout(burst.timer);
    burst.timer = setTimeout(() => void commitQuickEditBurst(context, entityKey, statName), QUICK_EDIT_DEBOUNCE_MS);
    return true;
}

async function commitQuickEditBurst(context, entityKey, statName) {
    const burstKey = `${entityKey}\u0000${statName}`;
    const burst = quickEditBursts.get(burstKey);
    quickEditBursts.delete(burstKey);

    /* review F5: a burst belongs to the chat it was made in — after a chat
       switch ST would save the OTHER chat; the edit cannot be persisted. */
    if (burst && (burst.chatId !== currentChatIdSafe() || burst.metadata !== SillyTavern.getContext()?.chatMetadata)) {
        console.warn("[Character State] Quick edit dropped: the chat changed before it was saved.");
        return;
    }

    const state = liveStateForKey(context, entityKey);
    const stat = state?.stats?.[statName];
    if (!burst || !stat) return;

    const after = statDisplayValue(state, stat);
    /* v3.1.1 U6: a Base outside its range displays clamped — the edit
       changed Mod even when the shown value did not move */
    if (after === burst.before && JSON.stringify(stat) === burst.raw) return;

    pushAuditEntry(context, {
        k: entityKey,
        src: "manual",
        sec: "stats",
        f: statName,
        op: "set",
        b: burst.before,
        a: after
    });
    recordStatHistory(context, entityKey, state);
    await saveChatState(context);
    refreshCsHud();
}

async function flushQuickEditBursts() {
    for (const [burstKey, burst] of [...quickEditBursts]) {
        clearTimeout(burst.timer);
        const [entityKey, statName] = burstKey.split("\u0000");
        await commitQuickEditBurst(SillyTavern.getContext(), entityKey, statName);
    }
}

function renderQuickControlsHtml(name, stat, pinned) {
    const pin = `<button class="cs-quick-btn cs-quick-pin${pinned ? " active" : ""}" type="button" data-cs-pin title="${escapeHtml(csT(pinned ? "Unpin" : "Pin"))}" aria-pressed="${pinned}">${csIcon("star")}</button>`;

    if (stat.type === "number") {
        return `
            <div class="cs-quick" data-cs-quick-stat="${escapeHtml(name)}">
                <button class="cs-quick-btn" type="button" data-cs-quick-delta="-1" title="${csH("−1 (Shift: −10)")}" aria-label="−1">${csIcon("minus")}</button>
                <button class="cs-quick-btn" type="button" data-cs-quick-delta="1" title="${csH("+1 (Shift: +10)")}" aria-label="+1">${csIcon("plus")}</button>
                <button class="cs-quick-btn cs-quick-wide" type="button" data-cs-quick-set>${escapeHtml(csT("Set…"))}</button>
                ${pin}
            </div>`;
    }

    if (stat.type === "boolean") {
        return `<div class="cs-quick" data-cs-quick-stat="${escapeHtml(name)}"><button class="cs-quick-btn cs-quick-wide" type="button" data-cs-quick-toggle>${escapeHtml(csT("Toggle"))}</button>${pin}</div>`;
    }

    if (stat.type === "choice" && Array.isArray(stat.options) && stat.options.length) {
        return `
            <div class="cs-quick" data-cs-quick-stat="${escapeHtml(name)}">
                <select class="text_pole cs-quick-choice" data-cs-quick-choice aria-label="${escapeHtml(name)}">
                    ${stat.options.map(option => `<option value="${escapeHtml(option)}" ${option === stat.base ? "selected" : ""}>${escapeHtml(applyCsMacros(option))}</option>`).join("")}
                </select>
                ${pin}
            </div>`;
    }

    return `<div class="cs-quick" data-cs-quick-stat="${escapeHtml(name)}"><button class="cs-quick-btn cs-quick-wide" type="button" data-cs-quick-text>${escapeHtml(csT("Set…"))}</button>${pin}</div>`;
}

function renderPinnedStripHtml(state, entityKey) {
    const context = SillyTavern.getContext();
    const pinned = getPinnedStatNames(context, entityKey).filter(name => state?.stats?.[name]);
    if (!pinned.length) return "";

    return `
        <div class="cs-pinned-strip">
            ${pinned.map(name => renderPinnedChipHtml(context, state, entityKey, name)).join("")}
        </div>`;
}

function renderPinnedChipHtml(context, state, entityKey, name) {
    const stat = state.stats[name];

    if (stat.type !== "number") {
        return `<div class="cs-pin-chip"><span class="cs-pin-name">${renderRichText(name)}</span><b class="cs-pin-value">${stat.type === "boolean" ? (stat.base ? "✓" : "✕") : escapeHtml(applyCsMacros(String(stat.base ?? "")))}</b></div>`;
    }

    const value = Number(getEffectiveStatValue(state, stat));
    /* v3.1.1 U5: null (Number(null) = 0) and the 0/0 pair mean unlimited */
    const minLimit = normalizeNumberOrNull(stat.min);
    const maxLimit = normalizeNumberOrNull(stat.max);
    const min = minLimit ?? 0;
    const max = maxLimit ?? NaN;
    const hasRange = maxLimit !== null && !(minLimit === 0 && maxLimit === 0) && max > min;
    const percent = hasRange ? Math.max(0, Math.min(100, ((value - min) / (max - min)) * 100)) : null;

    return `
        <div class="cs-pin-chip">
            <span class="cs-pin-name">${renderRichText(name)}</span>
            <b class="cs-pin-value">${escapeHtml(formatPlainValue(value))}${hasRange ? `<small>/${escapeHtml(formatPlainValue(max))}</small>` : ""}</b>
            ${renderStatTrend(getStatHistory(context, entityKey, name))}
            ${percent !== null ? `<span class="cs-pin-bar"><i style="width:${percent.toFixed(1)}%;"></i></span>` : ""}
        </div>`;
}

/* ---- HUD above the chat input ------------------------------------------ */

function getHudEntities(context) {
    const entities = [];
    const seen = new Set();

    /* v3.1.1 U4: every entity the sheet can pin (side NPCs included) */
    for (const character of [...getChatScopeCharacters(context), ...getAvailableSheetCharacters()]) {
        const key = getStateEntityKey(character);
        if (!key || seen.has(key)) continue;
        seen.add(key);
        entities.push({ key, character });
    }

    if (getStoredUserState(context)) entities.push({ key: USER_STATE_KEY, character: makeUserEntity() });
    return entities;
}

function refreshCsHud() {
    if (typeof document?.getElementById !== "function") return;

    const sendForm = document.getElementById("send_form");
    const existing = document.getElementById("cs-hud");
    const context = SillyTavern.getContext();

    if (!sendForm || getExtensionSettings().hudEnabled === false || !context?.chatMetadata) {
        existing?.remove();
        return;
    }

    const groups = getHudEntities(context)
        .map(({ key, character }) => {
            const state = liveStateForKey(context, key);
            const names = getPinnedStatNames(context, key).filter(name => state?.stats?.[name]);
            return names.length ? { key, character, state, names } : null;
        })
        .filter(Boolean);

    if (!groups.length) {
        existing?.remove();
        return;
    }

    const hud = existing || document.createElement("div");
    hud.id = "cs-hud";
    hud.className = "cs-hud";
    hud._entities = groups;
    hud.innerHTML = groups.map((group, index) => `
        <button class="cs-hud-entity" type="button" data-cs-hud-index="${index}" title="${escapeHtml(csT("Open sheet"))}">
            ${groups.length > 1 ? `<span class="cs-hud-who">${escapeHtml(group.character?.name || "")}</span>` : ""}
            ${group.names.map(name => renderPinnedChipHtml(context, group.state, group.key, name)).join("")}
        </button>`).join("");

    if (!existing) {
        hud.addEventListener("click", event => {
            const button = event.target.closest?.("[data-cs-hud-index]");
            const group = button ? hud._entities?.[Number(button.dataset.csHudIndex)] : null;
            if (group) void openCharacterSheet("view", group.character);
        });
        sendForm.parentElement?.insertBefore(hud, sendForm);
    }
}

globalThis.__csFeaturesForTests = {
    applyQuickStatEdit: (...args) => applyQuickStatEdit(...args),
    flushQuickEditBursts: (...args) => flushQuickEditBursts(...args),
    togglePinnedStat: (...args) => togglePinnedStat(...args),
    getPinnedStatNames: (...args) => getPinnedStatNames(...args),
    buildConfigExport: (...args) => buildConfigExport(...args),
    importConfigFromText: (...args) => importConfigFromText(...args),
    refreshCsHud: () => refreshCsHud()
};

/* Delegated quick-edit / pin handling for a view-mode sheet. */
function wireQuickEdits(overlay) {
    const rerenderRow = row => {
        const context = SillyTavern.getContext();
        const entityKey = overlay.dataset.characterKey || "";
        const state = liveStateForKey(context, entityKey);
        const name = row.dataset.csStatKey;
        const stat = state?.stats?.[name];
        if (!stat) return;

        const holder = document.createElement("div");
        holder.innerHTML = renderStatRowHtml(name, stat, state, entityKey, row.dataset.csGroupOf || "__all__", getModToBaseUiEnabled());
        const fresh = holder.firstElementChild;
        if (!fresh) return;

        row.replaceWith(fresh);
        toggleStatRowDetail(fresh, true);

        const strip = overlay.querySelector(".cs-pinned-strip");
        const stripHtml = renderPinnedStripHtml(state, entityKey);
        if (strip) {
            if (stripHtml) strip.outerHTML = stripHtml;
            else strip.remove();
        } else if (stripHtml) {
            overlay.querySelector(".cs-stat-toolbar")?.insertAdjacentHTML("beforebegin", stripHtml);
        }
    };

    overlay.addEventListener("click", async event => {
        const control = event.target.closest?.(".cs-quick [data-cs-quick-delta], .cs-quick [data-cs-quick-set], .cs-quick [data-cs-quick-toggle], .cs-quick [data-cs-quick-text], .cs-quick [data-cs-pin]");
        if (!control) return;

        event.stopPropagation();
        const row = control.closest(".cs-stat-row");
        const name = row?.dataset.csStatKey;
        const entityKey = overlay.dataset.characterKey || "";
        const context = SillyTavern.getContext();
        if (!row || !name || !entityKey) return;

        if (control.matches("[data-cs-pin]")) {
            await togglePinnedStat(context, entityKey, name);
            rerenderRow(row);
            refreshCsHud();
            return;
        }

        if (control.matches("[data-cs-quick-delta]")) {
            const step = Number(control.dataset.csQuickDelta) * (event.shiftKey ? 10 : 1);
            if (applyQuickStatEdit(context, entityKey, name, { delta: step })) rerenderRow(row);
            return;
        }

        if (control.matches("[data-cs-quick-toggle]")) {
            if (applyQuickStatEdit(context, entityKey, name, {})) rerenderRow(row);
            return;
        }

        const state = liveStateForKey(context, entityKey);
        const current = statDisplayValue(state, state?.stats?.[name]);
        const input = await csPrompt(csT("New value for {name}:", { name: applyCsMacros(name) }), String(current));
        if (input === null) return;

        const isNumber = state?.stats?.[name]?.type === "number";
        const value = isNumber ? Number(input) : input;
        if (isNumber && (!String(input).trim() || !Number.isFinite(value))) {
            csToast.error("Enter a number.");
            return;
        }

        if (applyQuickStatEdit(context, entityKey, name, { value })) rerenderRow(row);
    }, true);

    overlay.addEventListener("change", event => {
        const select = event.target.closest?.(".cs-quick [data-cs-quick-choice]");
        if (!select) return;

        const row = select.closest(".cs-stat-row");
        const entityKey = overlay.dataset.characterKey || "";
        if (row && applyQuickStatEdit(SillyTavern.getContext(), entityKey, row.dataset.csStatKey, { value: select.value })) {
            rerenderRow(row);
        }
    });
}

/* ---- relations panel (v3.1 — C2 edges had no UI) ------------------------
   User-owned edits through the same setRelationship / removeRelationship
   primitives the tool uses (#31: never generated from the story — this is
   the user editing data), each audited as source "manual". */
function relationEntityName(context, key) {
    return describeEntity(context, key)?.name || auditEntityDisplayName(key) || key;
}

function renderRelationEdgeRow(context, edge, direction) {
    const other = direction === "out" ? edge.to : edge.from;
    const metaChips = edge.meta && typeof edge.meta === "object"
        ? Object.entries(edge.meta).map(([key, value]) => `<span class="cs-effect-tag">${escapeHtml(key)}: ${escapeHtml(customLeafText(value, 40))}</span>`).join("")
        : "";

    return `
        <div class="cs-relation-row">
            <span class="cs-relation-arrow">${direction === "out" ? "→" : "←"}</span>
            <span class="cs-relation-type">${escapeHtml(edge.type)}</span>
            <span class="cs-relation-arrow">${direction === "out" ? "→" : "←"}</span>
            <span class="cs-relation-other">${escapeHtml(relationEntityName(context, other))}</span>
            ${metaChips}
            <button class="cs-icon-btn cs-relation-delete" type="button" title="${escapeHtml(csT("Delete"))}" aria-label="${escapeHtml(csT("Delete"))}"
                data-cs-rel-from="${escapeHtml(edge.from)}" data-cs-rel-type="${escapeHtml(edge.type)}" data-cs-rel-to="${escapeHtml(edge.to)}">${csIcon("trash")}</button>
        </div>`;
}

function renderRelationsPanelHtml(context, entityKey) {
    if (!entityKey) return `<div class="cs-empty-card"><div class="cs-empty-text">${escapeHtml(csT("No relations"))}</div></div>`;

    const outgoing = listRelationships(context, { from: entityKey });
    const incoming = listRelationships(context, { to: entityKey });
    const usedTypes = [...new Set(getRelationships(context).map(edge => String(edge?.type ?? "").trim()).filter(Boolean))].sort();
    const targets = listEntities(context).filter(entity => entity.key !== entityKey);

    const section = (title, rows) => `
        <div class="cs-relation-section">
            <div class="cs-menu-heading">${escapeHtml(title)} · ${rows.length}</div>
            ${rows.length ? rows.join("") : `<div class="cs-empty-text cs-relation-empty">${escapeHtml(csT("None"))}</div>`}
        </div>`;

    return `
        ${section(csT("Outgoing"), outgoing.map(edge => renderRelationEdgeRow(context, edge, "out")))}
        ${section(csT("Incoming"), incoming.map(edge => renderRelationEdgeRow(context, edge, "in")))}
        <div class="cs-relation-add">
            <div class="cs-menu-heading">${escapeHtml(csT("Add relation"))}</div>
            <div class="cs-relation-form">
                <input id="cs-rel-type" class="text_pole" type="text" list="cs-rel-type-options" placeholder="${escapeHtml(csT("Type (e.g. friend_of)"))}" />
                <datalist id="cs-rel-type-options">${usedTypes.map(type => `<option value="${escapeHtml(type)}"></option>`).join("")}</datalist>
                <select id="cs-rel-to" class="text_pole">
                    ${targets.map(entity => `<option value="${escapeHtml(entity.key)}">${escapeHtml(entity.name || entity.key)}</option>`).join("")}
                </select>
                <input id="cs-rel-meta" class="text_pole" type="text" placeholder="${escapeHtml(csT("Notes, optional (key=value; key=value)"))}" />
                <button class="cs-chip cs-chip-accent" id="cs-rel-add-btn" type="button" ${targets.length ? "" : "disabled"}>${csIcon("plus")} ${escapeHtml(csT("Add"))}</button>
            </div>
        </div>`;
}

function parseRelationMeta(text) {
    const meta = {};

    for (const part of String(text || "").split(";")) {
        const [rawKey, ...rest] = part.split("=");
        const key = String(rawKey || "").trim();
        if (!key || key === "__proto__" || key === "constructor" || key === "prototype") continue;
        meta[key] = rest.join("=").trim();
    }

    return Object.keys(meta).length ? meta : null;
}

function wireRelationsPanel(overlay, entityKey) {
    const panel = overlay.querySelector('[data-cs-tab-panel="relations"] .cs-card');
    if (!panel || !entityKey) return;

    const rerender = () => {
        panel.innerHTML = renderRelationsPanelHtml(SillyTavern.getContext(), entityKey);
        const count = listRelationships(SillyTavern.getContext(), { from: entityKey }).length +
            listRelationships(SillyTavern.getContext(), { to: entityKey }).length;
        const badge = overlay.querySelector('.cs-tab[data-cs-tab="relations"] .cs-tab-count');
        if (badge) badge.textContent = String(count);
    };

    panel.addEventListener("click", async event => {
        const context = SillyTavern.getContext();
        const removeButton = event.target.closest?.(".cs-relation-delete");

        if (removeButton) {
            const { csRelFrom: from, csRelType: type, csRelTo: to } = removeButton.dataset;
            if (!await csConfirm(csT("Delete relation \"{type}\"?", { type }), { okLabel: csT("Delete"), danger: true })) return;

            const result = removeRelationship(context, from, type, to);
            if (!result.ok) {
                csToast.error(result.reason);
                return;
            }

            pushAuditEntry(context, { k: from, src: "manual", sec: "relationship", f: `${type} → ${relationEntityName(context, to)}`, op: "remove" });
            await saveChatState(context);
            rerender();
            return;
        }

        if (event.target.closest?.("#cs-rel-add-btn")) {
            const type = String(panel.querySelector("#cs-rel-type")?.value || "").trim();
            const to = panel.querySelector("#cs-rel-to")?.value || "";
            const meta = parseRelationMeta(panel.querySelector("#cs-rel-meta")?.value);
            const result = setRelationship(context, entityKey, type, to, meta);

            if (!result.ok) {
                csToast.error(result.reason);
                return;
            }

            pushAuditEntry(context, { k: entityKey, src: "manual", sec: "relationship", f: `${type} → ${relationEntityName(context, to)}`, op: result.created ? "add" : "update" });
            await saveChatState(context);
            rerender();
        }
    });
}

/* ---- in-place refresh ----------------------------------------------------- */

function captureSheetUiState(overlay) {
    if (!overlay?.isConnected) return null;

    const content = overlay.querySelector(".cs-content");
    /* v3.1.1 U10: a refresh keeps the field being typed in (the stat
       filter used to lose its caret to the character <select>) */
    const active = document.activeElement;
    const focused = active && overlay.contains(active) && active.id ? active : null;

    return {
        entityKey: overlay.dataset.characterKey || "",
        mode: overlay.dataset.mode || "view",
        tab: overlay.querySelector(".cs-tab.active")?.dataset.csTab || sheetUiMemory.tab,
        scrollTop: content?.scrollTop || 0,
        filter: overlay.querySelector("#cs-stat-filter")?.value || "",
        openDetails: [...overlay.querySelectorAll(".cs-stat-row.cs-open")].map(row => row.dataset.csStatKey),
        focusId: focused?.id || null,
        selection: focused && typeof focused.selectionStart === "number" ? [focused.selectionStart, focused.selectionEnd] : null
    };
}

function restoreSheetUiState(overlay, saved) {
    if (!saved || saved.entityKey !== (overlay.dataset.characterKey || "") || saved.mode !== overlay.dataset.mode) return;

    const filter = overlay.querySelector("#cs-stat-filter");
    if (filter && saved.filter) {
        filter.value = saved.filter;
        applyStatListFilter(overlay);
    }

    for (const key of saved.openDetails || []) {
        const row = [...overlay.querySelectorAll(".cs-stat-row")].find(item => item.dataset.csStatKey === key);
        if (row) toggleStatRowDetail(row, true);
    }

    const content = overlay.querySelector(".cs-content");
    if (content) content.scrollTop = saved.scrollTop || 0;

    const byId = saved.focusId ? document.getElementById(saved.focusId) : null;
    const focusTarget = byId && overlay.contains(byId) ? byId : null;
    if (focusTarget) {
        focusTarget.focus?.({ preventScroll: true });
        if (saved.selection && typeof focusTarget.setSelectionRange === "function") {
            try {
                focusTarget.setSelectionRange(saved.selection[0], saved.selection[1]);
            } catch {
                /* not a text field */
            }
        }
    }
}

/* Re-open the sheet WITHOUT the remove-then-await gap (the old overlay stays
   on screen until the new one is ready) and keep tab / scroll / filter /
   expanded rows. Replaces the old `overlay.remove(); await openCharacterSheet()`. */
async function reopenCharacterSheet(overlay, mode = "view", character = null) {
    sheetUiMemory.pendingRestore = captureSheetUiState(overlay);
    return openCharacterSheet(mode, character || overlay?._character || null);
}

function toggleStatRowDetail(row, force = null) {
    const detail = row.querySelector(".cs-stat-detail");
    if (!detail) return;

    const open = force === null ? detail.hidden : Boolean(force);
    detail.hidden = !open;
    row.classList.toggle("cs-open", open);
    row.querySelector(".cs-stat-value")?.setAttribute("aria-expanded", open ? "true" : "false");
}

function closeAllSheetMenus(overlay, except = null) {
    for (const menu of overlay.querySelectorAll(".cs-menu")) {
        if (menu === except) continue;
        const popover = menu.querySelector(".cs-menu-popover");
        if (popover) popover.hidden = true;
        menu.querySelector(".cs-menu-trigger")?.setAttribute("aria-expanded", "false");
    }
}

function countCustomLeaves(node, limit = 100000) {
    let count = 0;
    const stack = [node];

    while (stack.length && count < limit) {
        const current = stack.pop();
        if (!current || typeof current !== "object") { count += 1; continue; }
        if (Array.isArray(current)) { count += 1; continue; }
        for (const value of Object.values(current)) stack.push(value);
    }

    return count;
}

function hydrateLazyCustomPanel(overlay) {
    const holder = overlay.querySelector("[data-cs-lazy-custom]");
    if (!holder || typeof overlay._renderCustomPanel !== "function") return;

    holder.innerHTML = overlay._renderCustomPanel();
    holder.removeAttribute?.("data-cs-lazy-custom");
    delete holder.dataset?.csLazyCustom;
}

function activateSheetTab(overlay, key) {
    const tabs = [...overlay.querySelectorAll(".cs-tab")];
    if (!tabs.some(tab => tab.dataset.csTab === key)) key = tabs[0]?.dataset.csTab || "stats";

    for (const tab of tabs) {
        const active = tab.dataset.csTab === key;
        tab.classList.toggle("active", active);
        tab.setAttribute("aria-selected", active ? "true" : "false");
    }

    for (const panel of overlay.querySelectorAll("[data-cs-tab-panel]")) {
        panel.hidden = panel.dataset.csTabPanel !== key;
    }

    if (key === "custom") hydrateLazyCustomPanel(overlay);

    sheetUiMemory.tab = key;
}

/* Delegated interactions shared by view + edit mode (menus, tabs) and the
   view-only stat list (groups, filter, row details, onboarding). */
function wireSheetChrome(overlay) {
    overlay.addEventListener("click", event => {
        const trigger = event.target.closest?.(".cs-menu-trigger");

        if (trigger && overlay.contains(trigger)) {
            const menu = trigger.closest(".cs-menu");
            const popover = menu?.querySelector(".cs-menu-popover");
            if (!popover) return;

            const open = popover.hidden;
            closeAllSheetMenus(overlay, menu);
            popover.hidden = !open;
            trigger.setAttribute("aria-expanded", open ? "true" : "false");
            if (open) popover.querySelector(".cs-menu-item")?.focus?.({ preventScroll: true });
            return;
        }

        if (event.target.closest?.(".cs-menu-item")) {
            closeAllSheetMenus(overlay);
            return;
        }

        if (!event.target.closest?.(".cs-menu-popover")) closeAllSheetMenus(overlay);

        const tab = event.target.closest?.(".cs-tab");
        if (tab && overlay.contains(tab)) {
            activateSheetTab(overlay, tab.dataset.csTab);
            return;
        }

        const groupTab = event.target.closest?.(".cs-group-tab");
        if (groupTab && overlay.contains(groupTab)) {
            const group = groupTab.dataset.csGroup || "__all__";
            overlay.querySelectorAll(".cs-group-tab").forEach(item => item.classList.toggle("active", item === groupTab));
            const list = overlay.querySelector(".cs-stat-list");
            if (list) list.dataset.csActiveGroup = group;
            sheetUiMemory.groupByEntity.set(overlay.dataset.characterKey || "", group);
            applyStatListFilter(overlay);
            return;
        }

        const onboard = event.target.closest?.("[data-cs-onboard]");
        if (onboard) {
            const target = {
                card: "cs-edit-card-btn",
                chat: "cs-edit-chat-btn",
                paste: "cs-paste-btn",
                presets: "cs-presets-btn",
                ai: "cs-settings-btn"
            }[onboard.dataset.csOnboard];
            overlay.querySelector(`#${target}`)?.click();
            return;
        }

        /* Row details: value button or empty row space (never the name —
           that opens the history graph). */
        const row = event.target.closest?.(".cs-stat-row");
        if (row && !event.target.closest(".cs-stat-name-label, .cs-mod-to-base-row-btn, .cs-quick, a, input, select, textarea")) {
            toggleStatRowDetail(row);
        }
    });

    overlay.addEventListener("keydown", event => {
        if (event.key !== "Enter" && event.key !== " ") return;
        const label = event.target.closest?.(".cs-stat-name-label, .cs-effect-card[role=button]");
        if (!label) return;
        if (event.target !== label && event.target.closest("button, input, select, textarea, a")) return;
        event.preventDefault();
        label.click();
    });

    overlay.querySelector("#cs-stat-filter")?.addEventListener("input", () => applyStatListFilter(overlay));

    /* initial group visibility */
    applyStatListFilter(overlay);
}

/* =========================================================
   STATS VIEW
========================================================= */

function renderStatsView(state, entityKey = null) {
    const chips = renderActiveEffectsChips(state);
    const entries = Object.entries(state.stats || {});

    /* Stat groups are pure presentation metadata: when no stat carries a
       group, the classic flat table renders exactly as before. */
    const groupOrder = [];
    const byGroup = new Map();

    for (const [name, stat] of entries) {
        const group = String(stat?.group ?? "").trim() || "Other";

        if (!byGroup.has(group)) {
            byGroup.set(group, []);
            groupOrder.push(group);
        }

        byGroup.get(group).push([name, stat]);
    }

    const hasGroups = getExtensionSettings().groupsEnabled && (
        groupOrder.length > 1 ||
        (groupOrder.length === 1 && groupOrder[0] !== "Other")
    );

    if (!hasGroups) {
        return `${chips}${renderStatsTableHtml(entries, state, entityKey)}`;
    }

    const tabs = groupOrder.map((group, index) => `
        <button
            class="cs-group-tab${index === 0 ? " active" : ""}"
            type="button"
            data-cs-group="${escapeHtml(group)}"
        >
            ${escapeHtml(group)}
        </button>
    `).join("");

    const panels = groupOrder.map((group, index) => `
        <div
            class="cs-group-table${index === 0 ? "" : " cs-group-table-hidden"}"
            data-cs-group-panel="${escapeHtml(group)}"
        >
            ${renderStatsTableHtml(byGroup.get(group), state, entityKey)}
        </div>
    `).join("");

    return `
        ${chips}
        <div class="cs-group-tabs">${tabs}</div>
        ${panels}
    `;
}

function renderStatsTableHtml(entries, state, entityKey = null) {
    /* Per-stat Mod→Base fold buttons are opt-in (per-chat toggle). */
    const showFoldColumn = getModToBaseUiEnabled();

    const rows = entries.map(([name, stat]) => {
        if (stat.type === "number") {
            const base = Number(stat.base || 0);
            const mod = Number(stat.mod || 0);
            const eff = base + mod;
            const effectDelta = getEffectDeltaForStat(state, name);
            const totalEff = eff + effectDelta;
            const modText =
                mod > 0 ? `+${formatNumber(mod)}` :
                mod < 0 ? formatNumber(mod) :
                "—";

            const progress = stat.progressBar?.enabled && stat.max !== null && Number.isFinite(Number(stat.max))
                ? renderStatProgressBar(stat, totalEff)
                : "";

            const sparkline = entityKey
                ? renderStatSparkline(getStatHistory(SillyTavern.getContext(), entityKey, name))
                : "";

            /* Display name resolves macros ({{user}} → persona); the RAW
               name stays on data-* attributes — every interaction targets
               the stored key, never the resolved label. */
            const nameLabel = entityKey
                ? `<span class="cs-stat-name-label" data-cs-stat-name="${escapeHtml(name)}" title="${csH("Click for history")}">${renderRichText(name)}</span>`
                : renderRichText(name);

            const foldCell = showFoldColumn
                ? `<td class="cs-fold-col">${mod !== 0
                    ? `<button class="cs-mod-to-base-row-btn" type="button" data-cs-stat-name="${escapeHtml(name)}" title="${csH("Fold Mod into Base (Base += Mod, Mod = 0)")}">⇣</button>`
                    : ""}</td>`
                : "";

            /* Field description tooltip (v2.0.23): hovering the VALUE cells
               (Base / Mod / Eff) explains what this field is for — the name
               cell keeps its own history-click tooltip. Empty description →
               no tooltip (nothing to say). */
            const descText = applyCsMacros(String(stat.description || "")).trim();
            const descAttr = descText ? ` title="${escapeHtml(descText)}"` : "";
            const effTitleParts = [descText, effectDelta ? csT("Includes effects {delta}", { delta: `${effectDelta > 0 ? "+" : ""}${effectDelta}` }) : ""];
            const effTitleAttr = effTitleParts.some(Boolean) ? ` title="${escapeHtml(effTitleParts.filter(Boolean).join(" · "))}"` : "";

            return `
                <tr>
                    <td class="cs-stat-name">
                        ${nameLabel}
                        ${sparkline}
                        ${progress}
                    </td>
                    <td${descAttr}>${formatNumber(base)}${stat.unit ? ` ${escapeHtml(stat.unit)}` : ""}</td>
                    <td class="${mod > 0 ? "cs-positive" : mod < 0 ? "cs-negative" : "cs-empty"}"${descAttr}>${escapeHtml(modText)}</td>
                    <td class="cs-effective${effectDelta ? " cs-effective-buffed" : ""}"${effTitleAttr}>${formatNumber(totalEff)}${stat.unit ? ` ${escapeHtml(stat.unit)}` : ""}${effectDelta ? `<span class="cs-eff-delta cs-eff-delta-${effectDelta > 0 ? "gain" : "loss"}">(${effectDelta > 0 ? "+" : ""}${formatNumber(effectDelta)})</span>` : ""}</td>
                    ${foldCell}
                </tr>
            `;
        }

        /* Text / Choice / Boolean stats: Mod is always 0 for them
           (they carry no runtime delta) and Eff equals Base, so all
           columns stay meaningful instead of showing empty cells. */
        const nonNumberValue = formatNonNumberValue(stat);

        const foldCell = showFoldColumn ? `<td class="cs-fold-col"></td>` : "";

        const descText = applyCsMacros(String(stat.description || "")).trim();
        const descAttr = descText ? ` title="${escapeHtml(descText)}"` : "";

        return `
            <tr>
                <td class="cs-stat-name">${renderRichText(name)}</td>
                <td class="cs-non-number-value"${descAttr}>${nonNumberValue}</td>
                <td class="cs-empty"${descAttr}>0</td>
                <td class="cs-effective"${descAttr}>${nonNumberValue}</td>
                ${foldCell}
            </tr>
        `;
    }).join("");

    return `
        <table class="cs-table">
            <thead>
                <tr>
                    <th class="cs-stat-name">${csH("Stat")}</th>
                    <th>${csH("Base")}</th>
                    <th>${csH("Mod")}</th>
                    <th>${csH("Eff.")}</th>
                    ${showFoldColumn ? `<th class="cs-fold-col" title="${csH("Fold Mod into Base (Base += Mod, Mod = 0)")}">⇣</th>` : ""}
                </tr>
            </thead>
            <tbody>${rows}</tbody>
        </table>
    `;
}

function historyYRange(values) {
    const min = Math.min(...values);
    const max = Math.max(...values);

    /* Zero-anchored scale for non-negative values: small deltas (56 → 60)
       must not be stretched across the whole chart height. */
    const anchorMin = values.every(value => value >= 0)
        ? Math.min(min, 0)
        : min;

    const range = (max - anchorMin) || 1;

    return { anchorMin, max, range };
}

function renderStatSparkline(points, width = 110, height = 22) {
    if (!Array.isArray(points) || !points.length) return "";

    /* v3.1 P6: 200 points into 64-110 px drew ~2 KB of SVG per stat — keep
       about one point per 2 px (first and last always kept). */
    const maxPoints = Math.max(2, Math.floor(width / 2));
    if (points.length > maxPoints) {
        const step = (points.length - 1) / (maxPoints - 1);
        points = Array.from({ length: maxPoints }, (_, index) => points[Math.round(index * step)]);
    }

    const values = points.map(point => Number(point.eff));
    const { anchorMin, range } = historyYRange(values);
    const padY = 3;

    const yFor = eff => height - padY - ((Number(eff) - anchorMin) / range) * (height - padY * 2);

    if (points.length === 1) {
        /* Single point: draw a dot so history is visible immediately. */
        const cx = (width / 2).toFixed(1);
        const cy = yFor(values[0]).toFixed(1);

        return `
            <svg
                class="cs-sparkline"
                width="${width}"
                height="${height}"
                viewBox="0 0 ${width} ${height}"
                aria-hidden="true"
            >
                <circle cx="${cx}" cy="${cy}" r="3" fill="#5eead4" />
            </svg>
        `;
    }

    const stepX = (width - 2) / (points.length - 1);

    const coords = points.map((point, index) => {
        const x = 1 + index * stepX;
        const y = yFor(point.eff);

        return `${x.toFixed(1)},${y.toFixed(1)}`;
    }).join(" ");

    const rising = values[values.length - 1] >= values[0];
    const color = rising ? "#8ed7ae" : "#ea919c";

    return `
        <svg
            class="cs-sparkline"
            width="${width}"
            height="${height}"
            viewBox="0 0 ${width} ${height}"
            aria-hidden="true"
        >
            <polyline points="${coords}" fill="none" stroke="${color}" stroke-width="1.5" />
        </svg>
    `;
}

function formatHistoryTimeLabel(value, axis) {
    if (axis === "minutes") return formatGameTime(Number(value));
    return csT("msg {n}", { n: value });
}

function openStatHistoryModal(entityKey, statName) {
    const context = SillyTavern.getContext();
    const points = getStatHistory(context, entityKey, statName);
    const axis = context.chatMetadata?.[HISTORY_KEY]?.[entityKey]?.__axis === "minutes"
        ? "minutes"
        : "messages";

    document.getElementById("cs-history-overlay")?.remove();

    const overlay = document.createElement("div");
    overlay.id = "cs-history-overlay";
    overlay.className = "cs-log-overlay";

    let bodyHtml = "";

    if (!points.length) {
        bodyHtml = `<div class="cs-log-empty">${escapeHtml(csT("No history recorded for this stat yet."))}</div>`;
    } else {
        const values = points.map(point => Number(point.eff));
        const dataMin = Math.min(...values);
        const dataMax = Math.max(...values);
        const { anchorMin, range } = historyYRange(values);
        const width = 620;
        const height = 180;
        const padX = 40;
        const padY = 14;
        const stepX = points.length > 1
            ? (width - padX * 2) / (points.length - 1)
            : 0;

        const yFor = eff => height - padY - ((Number(eff) - anchorMin) / range) * (height - padY * 2);

        const coords = points.map((point, index) => {
            const x = points.length > 1
                ? padX + index * stepX
                : width / 2;
            const y = yFor(point.eff);

            return `${x.toFixed(1)},${y.toFixed(1)}`;
        });

        const dots = coords.map((pair, index) => {
            const [x, y] = pair.split(",");

            return `<circle cx="${x}" cy="${y}" r="3" fill="${points[index] === points[points.length - 1] ? "#5eead4" : "rgba(94,234,212,0.55)"}" />`;
        }).join("");

        const polyline = points.length > 1
            ? `<polyline points="${coords.join(" ")}" fill="none" stroke="${values[values.length - 1] >= values[0] ? "#8ed7ae" : "#ea919c"}" stroke-width="2" stroke-linejoin="round" />`
            : "";

        /* Y-axis ticks: 4 levels over the plotted range, each with a
           horizontal gridline (plain lines — they stretch safely inside
           the scaled SVG) and a value label rendered OUTSIDE the SVG so
           text is never distorted. */
        const axisTicks = Array.from({ length: 4 }, (_, i) => {
            const value = anchorMin + (range * i) / 3;
            const y = yFor(value);

            return {
                value: Math.round(value * 10) / 10,
                y,
                percent: (y / height) * 100
            };
        });

        const gridlines = axisTicks
            .map(tick => `
                <line
                    x1="${padX}"
                    y1="${tick.y.toFixed(1)}"
                    x2="${width - padX}"
                    y2="${tick.y.toFixed(1)}"
                    stroke="rgba(170,184,255,0.10)"
                    stroke-width="1"
                />
            `)
            .join("");

        const yLabels = axisTicks
            .map(tick => `
                <span class="cs-history-ylabel" style="top:${tick.percent.toFixed(2)}%;">${escapeHtml(formatNumber(tick.value))}</span>
            `)
            .join("");

        const latest = points[points.length - 1];
        const first = points[0];

        const recentRows = points.slice(-10).reverse().map(point => `
            <div class="cs-log-row">
                <span class="cs-log-time">${escapeHtml(formatHistoryTimeLabel(point.t, axis))}</span>
                <span class="cs-log-main">${csH("eff")} <b>${escapeHtml(formatNumber(point.eff))}</b></span>
            </div>
        `).join("");

        bodyHtml = `
            <div class="cs-history-chart">
                <div class="cs-history-plot">
                    <svg width="100%" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none">
                        ${gridlines}
                        <line x1="${padX}" y1="${height - padY}" x2="${width - padX}" y2="${height - padY}" stroke="rgba(170,184,255,0.20)" stroke-width="1" />
                        ${polyline}
                        ${dots}
                    </svg>
                    <div class="cs-history-ylabels">${yLabels}</div>
                </div>
                <div class="cs-history-axis">
                    <span>${escapeHtml(formatHistoryTimeLabel(first.t, axis))}</span>
                    <span class="cs-history-range">${escapeHtml(formatNumber(dataMin))} — ${escapeHtml(formatNumber(dataMax))} · ${csH("latest")} ${escapeHtml(formatNumber(latest.eff))}</span>
                    <span>${escapeHtml(formatHistoryTimeLabel(latest.t, axis))}</span>
                </div>
            </div>
            <div class="cs-history-recent-title">${escapeHtml(csT("Last 10 points"))}</div>
            <div class="cs-history-recent">${recentRows}</div>
        `;
    }

    overlay.innerHTML = `
        <div class="cs-log-window" style="width:min(700px,94vw);">
            <div class="cs-log-header">
                <div class="cs-log-title">${csIcon("chart-line")} ${escapeHtml(csT("{name} — history", { name: applyCsMacros(statName) }))}</div>
                <div class="cs-log-subtitle">${csH("One point per change · user-only, never sent to the model")}</div>
            </div>
            <div class="cs-log-body">
                ${bodyHtml}
            </div>
            <div class="cs-log-footer">
                <button class="cs-chip" id="cs-history-clear-btn" type="button">🗑 ${escapeHtml(csT("Clear history"))}</button>
                <button class="cs-chip cs-chip-soft" id="cs-history-close-btn" type="button">${csH("Close")}</button>
            </div>
        </div>
    `;

    document.body.appendChild(overlay);

    overlay.querySelector("#cs-history-close-btn")?.addEventListener("click", () => overlay.remove());

    overlay.querySelector("#cs-history-clear-btn")?.addEventListener("click", async () => {
        if (!await csConfirm(csT("Clear the recorded history of \"{name}\"?", { name: statName }))) return;

        const map = getStatHistoryMap(context);

        if (map?.[entityKey]) {
            delete map[entityKey][statName];
            await saveChatState(context);
        }

        overlay.remove();
        openStatHistoryModal(entityKey, statName);
    });

    overlay.addEventListener("click", event => {
        if (event.target === overlay) overlay.remove();
    });
}

/* Effect source keys are data (buff / debuff / skill / condition / item);
   only their on-screen label is translated. */
function effectSourceLabel(source) {
    const known = { buff: "buff", debuff: "debuff", skill: "skill", condition: "condition", item: "item" };
    return known[source] ? csT(known[source]) : String(source ?? "");
}

function renderActiveEffectsChips(state, { withAdd = true } = {}) {
    const effects = getActiveEffects(state);

    const chips = effects.map(effect => {
        const editable = effect.source !== "item";
        const deltas = Object.entries(effect.stats || {})
            .map(([statName, delta]) => `${statName} ${delta > 0 ? "+" : ""}${delta}`)
            .join(", ");

        const title = [
            `[${effectSourceLabel(effect.source)}] ${applyCsMacros(effect.name)}`,
            deltas ? deltas : `(${csT("condition")})`,
            formatEffectRemainingUi(effect),
            applyCsMacros(effect.description || ""),
            editable ? csT("Click to edit") : csT("Comes from an equipped item — unequip to remove")
        ].filter(Boolean).join(" · ");

        return `
            <span class="cs-effect-chip cs-effect-${escapeHtml(effect.source)}${editable ? " cs-effect-editable" : ""}" data-cs-effect-id="${escapeHtml(effect.id)}" title="${escapeHtml(title)}">
                <span class="cs-effect-chip-name">${renderRichText(effect.name)}</span>
                <span class="cs-effect-chip-remaining">${escapeHtml(formatEffectRemainingUi(effect))}</span>
                ${editable ? `<button class="cs-effect-edit" type="button" title="${csH("Edit effect")}">✎</button>` : ""}
                ${editable ? `<button class="cs-effect-remove" type="button" data-cs-effect-id="${escapeHtml(effect.id)}" title="${csH("Remove this effect")}">×</button>` : ""}
            </span>
        `;
    }).join("");

    return `
        <div class="cs-effect-chips">
            ${chips}
            ${withAdd ? `<button class="cs-effect-add" type="button" title="${csH("Add a buff / debuff / timed skill / condition")}">＋ ${csH("Effect")}</button>` : ""}
        </div>
    `;
}



function renderStatProgressBar(stat, value, { text = true } = {}) {
    const min = stat.min !== null && Number.isFinite(Number(stat.min))
        ? Number(stat.min)
        : 0;
    const max = Number(stat.max);

    if (!(max > min)) return "";

    const color = stat.progressBar?.color || "#2dd4bf";
    const negativeColor = stat.progressBar?.negativeColor || color;

    /* Two-axis (bipolar) bar: the range crosses zero (min < 0 < max).
       Zero sits at its proportional position; the fill grows AWAY from
       zero — positive values rightward with the main color, negative
       values leftward with the second color. */
    if (min < 0 && max > 0) {
        const range = max - min;
        const zeroPercent = Math.max(0, Math.min(100, ((0 - min) / range) * 100));
        const valuePercent = Math.max(0, Math.min(100, ((value - min) / range) * 100));
        const left = Math.min(zeroPercent, valuePercent);
        const width = Math.max(0, Math.abs(valuePercent - zeroPercent));
        const fillColor = value < 0 ? negativeColor : color;

        return `
            <div class="cs-progress-wrap">
                <div class="cs-progress-track">
                    <div
                        class="cs-progress-fill cs-progress-bipolar"
                        style="left:${left.toFixed(2)}%;width:${width.toFixed(2)}%;background:${escapeHtml(fillColor)};"
                    ></div>
                    <div
                        class="cs-progress-zero-tick"
                        style="left:${zeroPercent.toFixed(2)}%;"
                    ></div>
                </div>
                ${text ? `<div class="cs-progress-text" title="${csH("range")} ${formatNumber(min)} … ${formatNumber(max)}">
                    ${formatNumber(value)}
                </div>` : ""}
            </div>
        `;
    }

    const percent = Math.max(
        0,
        Math.min(100, ((value - min) / (max - min)) * 100)
    );

    return `
        <div class="cs-progress-wrap">
            <div class="cs-progress-track">
                <div
                    class="cs-progress-fill"
                    style="width:${percent.toFixed(1)}%;background:${escapeHtml(color)};"
                ></div>
            </div>
            ${text ? `<div class="cs-progress-text">
                ${formatNumber(value)} / ${formatNumber(max)}
            </div>` : ""}
        </div>
    `;
}

/* ---- Rich text view (v2.0.23): macros + minimal markdown -----------
 * DISPLAY layer only — storage and the AI-facing prompt stay raw, so a
 * value written as "{{user}}" still MATCHES macros but is never baked
 * into the data. Safety: the source is ALWAYS escaped first; the only
 * tags in the output are the ones this helper itself generates.
 * -------------------------------------------------------------------- */
function applyCsMacros(text) {
    const raw = String(text ?? "");

    try {
        const substitute = SillyTavern.getContext()?.substituteParams;

        if (typeof substitute === "function") return String(substitute(raw));
    } catch {
        /* fall through to the minimal built-in map */
    }

    const context = SillyTavern.getContext();

    return raw
        .replace(/\{\{user\}\}/gi, context?.name1 || "User")
        .replace(/\{\{char\}\}/gi, context?.name2 || "Character");
}

function renderRichText(text) {
    const raw = String(text ?? "");

    if (!raw) return "";

    let html = escapeHtml(applyCsMacros(raw));

    html = html
        .replace(/\*\*([^*\n]+)\*\*/g, "<b>$1</b>")
        .replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g, "$1<i>$2</i>")
        .replace(/`([^`\n]+)`/g, "<code>$1</code>")
        .replace(/\r?\n/g, "<br>");

    return html;
}

/* ---- schema-diff dismissals (v2.0.23) ------------------------------
 * "Group stat schema now offers stats this user sheet is missing" can be
 * INTENTIONAL (a leaner user sheet is a design choice). "✕ Never" hides
 * the offer persistently per chat + entity (chatMetadata), per stat
 * name — new stats the group schema gains later are still offered.
 * -------------------------------------------------------------------- */
const SCHEMA_DISMISSALS_KEY = "character_state_schema_dismissals";

function getSchemaDiffDismissedNames(context, entityKey) {
    if (!entityKey) return [];

    const store = context?.chatMetadata?.[SCHEMA_DISMISSALS_KEY];
    const list = store && typeof store === "object" && !Array.isArray(store) ? store[entityKey] : null;

    return Array.isArray(list) ? list : [];
}

async function dismissSchemaDiffStats(context, entityKey, names) {
    if (!entityKey || !Array.isArray(names) || !names.length) return;

    const meta = context.chatMetadata;

    if (!meta[SCHEMA_DISMISSALS_KEY] || typeof meta[SCHEMA_DISMISSALS_KEY] !== "object") {
        meta[SCHEMA_DISMISSALS_KEY] = {};
    }

    const list = Array.isArray(meta[SCHEMA_DISMISSALS_KEY][entityKey])
        ? meta[SCHEMA_DISMISSALS_KEY][entityKey]
        : [];

    for (const name of names) {
        if (!list.includes(name)) list.push(name);
    }

    meta[SCHEMA_DISMISSALS_KEY][entityKey] = list;

    if (typeof context.saveMetadata === "function") {
        await saveChatState(context);
    }
}

/* ---- safety auto-snapshot (v2.0.23): UI mutations get an undo point --
 * AI-turn mutations are journaled (swipe/delete rollback), but MANUAL
 * UI mutations (paste, field paste, editor save, user reset) had NO
 * safety net — a mis-paste was only recoverable through ST chat
 * backups. Every risky manual path now takes a LABELED snapshot first;
 * the existing ⏪ Snapshots UI lists them ("auto · …") and restores.
 * Rides the path's own saveMetadata — no extra write.
 * -------------------------------------------------------------------- */
function takeSafetySnapshot(context, label) {
    try {
        return takeStateSnapshot(context, "auto · " + label);
    } catch (error) {
        console.warn("[Character State] Safety snapshot failed:", error);
        return { ok: false };
    }
}

function formatNonNumberValue(stat, options = {}) {
    if (stat.type === "boolean") {
        /* plain rows are stored in csEvents (and may reach the marker) —
           English; the rich variant is sheet HTML only. */
        if (options.rich === false) return stat.base ? "✓ True" : "✕ False";
        return stat.base ? `✓ ${csH("True")}` : `✕ ${csH("False")}`;
    }

    if (options.rich === false) {
        /* v3 B14: PLAIN text (macros substituted, no markup, NOT escaped) —
           stored in csEvents rows and escaped exactly once at render time.
           Pre-escaping here produced "&#039;" on cards and in prompts. */
        return String(applyCsMacros(stat.base ?? ""));
    }

    return renderRichText(stat.base ?? "");
}

/* =========================================================
   STATS EDITOR
========================================================= */

function renderStatsEditor(state) {
    const rows = Object.entries(state.stats || {}).map(([name, stat]) => {
        const row = createEditableStatRow(name, stat);
        row.classList.add("cs-drag-row");
        row.draggable = true;
        return row.outerHTML;
    }).join("");

    return `
        <div class="cs-edit-stats-header">
            <div>${csH("Stat")}</div>
            <div>${csH("Base")}</div>
            <div>${csH("Mod")}</div>
            <div>${csH("Actions")}</div>
        </div>

        <div id="cs-edit-stats">
            ${rows}
        </div>

        <div class="cs-add-stat-wrap">
            <button id="cs-add-stat" class="cs-add-stat-btn" type="button">+ ${csH("Add Stat")}</button>
            <button id="cs-stat-select-toggle" class="cs-clear-all-btn" type="button" title="${csH("Select several fields to copy them in one go")}">▣ ${csH("Select")}</button>
            <button id="cs-copy-selected" class="cs-clear-all-btn" type="button" style="display:none" title="${csH("Copy the selected fields (definitions + values) for field paste")}">⧉ ${csH("Copy selected")}</button>
            <button id="cs-save-selection-component" class="cs-clear-all-btn" type="button" style="display:none" title="${csH("Save the selected field definitions as a reusable component (🧩)")}">🧩 ${csH("Save as component")}</button>
            <button id="cs-apply-all-mod-to-base" class="cs-clear-all-btn" type="button" title="${csH("Fold every number stat's Mod into its Base (Base += Mod, Mod = 0). Press Save this chat to keep.")}">⇣ ${csH("Apply All Mod→Base")}</button>
            <button id="cs-clear-stats" class="cs-clear-all-btn" type="button" title="${csH("Delete all stats in this editor")}">🗑 ${csH("Clear All")}</button>
        </div>
    `;
}


function createEditableStatRow(name, stat) {
    const row = document.createElement("div");
    row.className = "cs-edit-stat-row";
    row.dataset.originalName = name;
    row._statDefinition = structuredClone(stat);

    const type = stat.type || "number";

    row.innerHTML = `
        <div class="cs-edit-stat-name">
            <input type="checkbox" class="cs-stat-select" title="${csH("Select for batch copy")}" />
            <span class="cs-drag-handle" title="${csH("Drag to reorder")}">☷</span>
            <input class="text_pole cs-edit-stat-name-input" type="text" value="${escapeHtml(name)}" />
        </div>

        <div class="cs-edit-base-wrap">
            ${createBaseEditor(stat)}
        </div>

        <div class="cs-edit-mod-wrap">
            ${type === "number"
                ? `<input class="text_pole cs-edit-mod" type="number" value="${escapeHtml(stat.mod ?? 0)}" />`
                : `<div class="cs-mod-hidden">—</div>`
            }
        </div>

        <div class="cs-edit-stat-actions">
            <button class="menu_button cs-copy-stat" type="button" title="${csH("Copy this field (definition + value) — paste it onto another character")}">⧉</button>
            <button class="menu_button cs-insert-above" type="button" title="${csH("Insert stat above")}">⤒</button>
            <button class="menu_button cs-insert-below" type="button" title="${csH("Insert stat below")}">⤓</button>
            ${type === "number" && getModToBaseUiEnabled()
                ? `<button class="menu_button cs-mod-to-base-edit" type="button" title="${csH("Fold Mod into Base (Base += Mod, Mod = 0)")}">⇣</button>`
                : ""}
            <button class="menu_button cs-edit-stat" type="button" title="${csH("Edit stat definition")}">✎</button>
            <button class="menu_button cs-remove-stat" type="button" title="${csH("Delete stat")}">🗑</button>
        </div>
    `;

    return row;
}


function createBaseEditor(stat) {
    if (stat.type === "number") {
        return `<input class="text_pole cs-edit-base" type="number" value="${escapeHtml(stat.base ?? 0)}" />`;
    }

    if (stat.type === "boolean") {
        return `
            <label class="cs-boolean-editor">
                <input class="cs-edit-base-checkbox" type="checkbox" ${stat.base ? "checked" : ""} />
                <span>${stat.base ? csH("True") : csH("False")}</span>
            </label>
        `;
    }

    if (stat.type === "choice") {
        return `
            <select class="text_pole cs-edit-base-select">
                ${(stat.options || []).map(option => `
                    <option value="${escapeHtml(option)}" ${option === stat.base ? "selected" : ""}>
                        ${escapeHtml(option)}
                    </option>
                `).join("")}
            </select>
        `;
    }

    return `<input class="text_pole cs-edit-base" type="text" value="${escapeHtml(stat.base ?? "")}" />`;
}


/* =========================================================
   ADD STAT MODAL
========================================================= */

function openAddStatModal() {
    openStatModal({ mode: "add" });
}


function renderAddStatOptions(modal, type, stat = null) {
    const container = modal.querySelector("#cs-stat-modal-options");
    if (!container) return;

    const current = stat || {};
    const base = current.base;
    const onChange = String(current.onChange || "");

    if (type === "number") {
        const minValue = current.min === null || current.min === undefined ? "" : current.min;
        const maxValue = current.max === null || current.max === undefined ? "" : current.max;
        const enabled = Boolean(current.progressBar?.enabled);
        const color = current.progressBar?.color || "#2dd4bf";
        const negativeColor = current.progressBar?.negativeColor || "#ff6b6b";

        container.innerHTML = `
            <div class="cs-option-title">${csH("Number Options")}</div>
            <div class="cs-form-grid">
                <div class="cs-form-group">
                    <label>${csH("Start at")}</label>
                    <input id="cs-stat-base" class="text_pole" type="number" value="${escapeHtml(base ?? 0)}" />
                </div>
                <div class="cs-form-group">
                    <label>Min</label>
                    <input id="cs-stat-min" class="text_pole" type="number" value="${escapeHtml(minValue)}" placeholder="${csH("Optional")}" />
                </div>
                <div class="cs-form-group">
                    <label>Max</label>
                    <input id="cs-stat-max" class="text_pole" type="number" value="${escapeHtml(maxValue)}" placeholder="${csH("Optional")}" />
                </div>
                <div class="cs-form-group">
                    <label>${csH("Unit")}</label>
                    <input id="cs-stat-unit" class="text_pole" type="text" value="${escapeHtml(current.unit || "")}" placeholder="HP, %, Lv..." />
                </div>
            </div>

            <div class="cs-form-group">
                <label class="cs-checkbox-row">
                    <input id="cs-stat-progress" type="checkbox" ${enabled ? "checked" : ""} />
                    <span>${csH("Show in progress bar")}</span>
                </label>
            </div>

            <div class="cs-form-group">
                <label class="cs-checkbox-row">
                    <input id="cs-stat-aibaseedit" type="checkbox" ${current.aiBaseEdit ? "checked" : ""} />
                    <span>${csH("AI may edit Base / Min / Max of this stat (aiBaseEdit)")}</span>
                </label>
            </div>

            <div id="cs-progress-color-wrap" class="cs-form-group" style="display:${enabled ? "" : "none"};">
                <label>${csH("Progress bar color")}</label>
                <div class="cs-color-input-row">
                    <input id="cs-stat-progress-color" type="color" value="${escapeHtml(color)}" />
                    <span id="cs-progress-color-value">${escapeHtml(color)}</span>
                </div>
                <label class="cs-progress-neg-label" title="${csH("Used when the range crosses zero (min negative) and the value is negative — the fill grows leftward from the zero mark")}">${csH("Second color (negative side, two-axis bar)")}</label>
                <div class="cs-color-input-row">
                    <input id="cs-stat-progress-negative-color" type="color" value="${escapeHtml(negativeColor)}" />
                    <span id="cs-progress-negative-color-value">${escapeHtml(negativeColor)}</span>
                </div>
            </div>

            ${renderOnChangeField(onChange)}
        `;

        const progress = modal.querySelector("#cs-stat-progress");
        const colorWrap = modal.querySelector("#cs-progress-color-wrap");
        const colorInput = modal.querySelector("#cs-stat-progress-color");
        const colorValue = modal.querySelector("#cs-progress-color-value");
        const negativeInput = modal.querySelector("#cs-stat-progress-negative-color");
        const negativeValue = modal.querySelector("#cs-progress-negative-color-value");

        progress?.addEventListener("change", () => {
            colorWrap.style.display = progress.checked ? "" : "none";
        });

        colorInput?.addEventListener("input", () => {
            colorValue.textContent = colorInput.value;
        });

        negativeInput?.addEventListener("input", () => {
            negativeValue.textContent = negativeInput.value;
        });

        return;
    }

    if (type === "boolean") {
        container.innerHTML = `
            <div class="cs-option-title">${csH("True / False Options")}</div>
            <div class="cs-form-group">
                <label class="cs-checkbox-row">
                    <input id="cs-stat-base" type="checkbox" ${base ? "checked" : ""} />
                    <span>${csH("Start at True")}</span>
                </label>
            </div>
            ${renderOnChangeField(onChange)}
        `;
        return;
    }

    if (type === "choice") {
        const options = normalizeOptions(current.options);
        container.innerHTML = `
            <div class="cs-option-title">${csH("Choice List")}</div>
            <div id="cs-choice-values" class="cs-choice-values"></div>
            <button id="cs-add-choice-value" class="menu_button cs-add-choice-btn" type="button">+ ${csH("Add Value")}</button>
            <div class="cs-form-group cs-choice-start-group">
                <label>${csH("Start at")}</label>
                <select id="cs-stat-base" class="text_pole"></select>
            </div>
            ${renderOnChangeField(onChange)}
        `;

        const valuesContainer = modal.querySelector("#cs-choice-values");
        const addButton = modal.querySelector("#cs-add-choice-value");
        const startSelect = modal.querySelector("#cs-stat-base");

        const refresh = () => {
            const previous = startSelect.value;
            startSelect.innerHTML = "";

            optionsFromInputs(valuesContainer).forEach(value => {
                const option = document.createElement("option");
                option.value = value;
                option.textContent = value;
                startSelect.appendChild(option);
            });

            if (current.base && [...startSelect.options].some(o => o.value === current.base)) {
                startSelect.value = current.base;
            } else if (previous && [...startSelect.options].some(o => o.value === previous)) {
                startSelect.value = previous;
            } else if (startSelect.options.length) {
                startSelect.value = startSelect.options[0].value;
            }
        };

        const addValue = (initial = "") => {
            const row = document.createElement("div");
            row.className = "cs-choice-row";
            row.innerHTML = `
                <input class="text_pole cs-choice-value-input" type="text" value="${escapeHtml(initial)}" placeholder="${csH("Value")}" />
                <button class="menu_button cs-remove-choice" type="button">×</button>
            `;

            valuesContainer.appendChild(row);

            row.querySelector(".cs-choice-value-input")?.addEventListener("input", refresh);
            row.querySelector(".cs-remove-choice")?.addEventListener("click", () => {
                row.remove();
                refresh();
            });
        };

        options.forEach(addValue);
        addButton?.addEventListener("click", () => addValue());
        refresh();
        return;
    }

    container.innerHTML = `
        <div class="cs-option-title">${csH("Text Options")}</div>
        <div class="cs-form-group">
            <label>${csH("Start at")}</label>
            <input id="cs-stat-base" class="text_pole" type="text" value="${escapeHtml(base ?? "")}" placeholder="${csH("Initial text...")}" />
        </div>
        ${renderOnChangeField(onChange)}
    `;
}


function renderOnChangeField(value = "") {
    return `
        <div class="cs-form-group">
            <label>${csH("On Change")}</label>
            <textarea id="cs-stat-onchange" class="text_pole" rows="4" placeholder="${csH("Tell the AI what to do when this stat changes...")}">${escapeHtml(value)}</textarea>
        </div>
    `;
}


function addNewStatFromModal(modal) {
    const overlay = document.getElementById("character-state-overlay");
    if (!overlay) return;

    const name = modal.querySelector("#cs-stat-name")?.value.trim();

    if (!name) {
        csToast.error("Stat name is required.");
        return;
    }

    const type = modal.querySelector("#cs-stat-type")?.value || "number";

    const duplicate = [...overlay.querySelectorAll(".cs-edit-stat-row")]
        .some(row => {
            const originalName = row.dataset.originalName || "";
            const currentName = row.querySelector(".cs-edit-stat-name-input")?.value.trim() || "";
            return currentName === name && originalName !== name;
        });

    if (duplicate) {
        csToast.error(csT("Stat \"{name}\" already exists.", { name }));
        return;
    }

    const stat = readStatFromModal(modal, name, type);
    if (!stat) return;

    const row = createEditableStatRow(name, stat);
    row.classList.add("cs-drag-row");
    row.draggable = true;
    document.getElementById("cs-edit-stats")?.appendChild(row);

    modal.remove();

    wireStatRowButtons(overlay);
    csToast.success(csT("Stat \"{name}\" added to editor.", { name }));
}



function optionsFromInputs(container) {
    return [...container.querySelectorAll(".cs-choice-value-input")]
        .map(input => input.value.trim())
        .filter(Boolean)
        .filter((value, index, list) => list.indexOf(value) === index);
}

function readStatFromModal(modal, name, type) {
    const description = modal.querySelector("#cs-stat-description")?.value.trim() || "";
    const onChange = modal.querySelector("#cs-stat-onchange")?.value || "";
    const group = modal.querySelector("#cs-stat-group")?.value.trim() || "";

    let triggers = null;
    const triggersRaw = modal.querySelector("#cs-stat-triggers")?.value.trim() || "";

    if (triggersRaw) {
        try {
            const parsed = JSON.parse(triggersRaw);
            triggers = normalizeTriggers(parsed);

            if (Array.isArray(parsed) && parsed.length && !triggers.length) {
                csToast.error('Triggers must be a JSON array of {"when","action","message"} objects.');
                return null;
            }
        } catch {
            csToast.error("Triggers must be valid JSON.");
            return null;
        }
    }

    const triggerField = triggers && triggers.length ? { triggers } : {};

    const syncCustom = (modal.querySelector("#cs-stat-synccustom")?.value || "")
        .split(",")
        .map(path => path.trim())
        .filter(Boolean);

    const syncCustomField = syncCustom.length ? { syncCustom } : {};

    if (type === "number") {
        const baseRaw = modal.querySelector("#cs-stat-base")?.value ?? "";
        const base = Number(baseRaw);
        const minRaw = modal.querySelector("#cs-stat-min")?.value ?? "";
        const maxRaw = modal.querySelector("#cs-stat-max")?.value ?? "";
        const min = minRaw === "" ? null : Number(minRaw);
        const max = maxRaw === "" ? null : Number(maxRaw);

        if (baseRaw.trim() === "" || !Number.isFinite(base)) {
            csToast.error("Start at is required and must be a valid number.");
            return null;
        }

        if (min !== null && !Number.isFinite(min)) {
            csToast.error("Min must be a valid number.");
            return null;
        }

        if (max !== null && !Number.isFinite(max)) {
            csToast.error("Max must be a valid number.");
            return null;
        }

        if (min !== null && max !== null && min > max) {
            csToast.error("Min cannot be greater than Max.");
            return null;
        }

        const progressEnabled = Boolean(modal.querySelector("#cs-stat-progress")?.checked);
        const progressColor = modal.querySelector("#cs-stat-progress-color")?.value || "#2dd4bf";
        const progressNegativeColor = modal.querySelector("#cs-stat-progress-negative-color")?.value || "";
        const aiBaseEdit = Boolean(modal.querySelector("#cs-stat-aibaseedit")?.checked);

        const unlimitedRange = min === 0 && max === 0;
        if (progressEnabled && !unlimitedRange && (max === null || (min !== null && max <= min))) {
            csToast.error("Progress Bar requires a Max greater than Min.");
            return null;
        }

        return {
            name,
            description,
            type: "number",
            base,
            mod: 0,
            min,
            max,
            unit: modal.querySelector("#cs-stat-unit")?.value.trim() || "",
            progressBar: {
                enabled: progressEnabled,
                color: progressColor,
                negativeColor: progressNegativeColor
            },
            aiBaseEdit,
            onChange,
            ...(group ? { group } : {}),
            ...triggerField,
            ...syncCustomField
        };
    }

    if (type === "boolean") {
        return {
            name,
            description,
            type: "boolean",
            base: Boolean(modal.querySelector("#cs-stat-base")?.checked),
            mod: 0,
            onChange,
            ...(group ? { group } : {}),
            ...triggerField,
            ...syncCustomField
        };
    }

    if (type === "choice") {
        const options = optionsFromInputs(modal.querySelector("#cs-choice-values"));

        if (!options.length) {
            csToast.error("Choice List needs at least one value.");
            return null;
        }

        const base = modal.querySelector("#cs-stat-base")?.value || "";

        if (!options.includes(base)) {
            csToast.error("Start at must be one of the Choice List values.");
            return null;
        }

        return {
            name,
            description,
            type: "choice",
            base,
            mod: 0,
            options,
            onChange,
            ...(group ? { group } : {}),
            ...triggerField,
            ...syncCustomField
        };
    }

    return {
        name,
        description,
        type: "text",
        base: modal.querySelector("#cs-stat-base")?.value || "",
        mod: 0,
        onChange,
        ...(group ? { group } : {})
    };
}

function openStatModal({ mode = "add", stat = null, row = null, anchorRow = null, position = null } = {}) {
    document.getElementById("cs-stat-modal-overlay")?.remove();

    const isEdit = mode === "edit";
    const current = stat || {
        name: "",
        description: "",
        type: "number",
        base: "",
        mod: 0,
        min: null,
        max: null,
        unit: "",
        progressBar: { enabled: false, color: "#2dd4bf", negativeColor: "" },
        onChange: ""
    };

    const modal = document.createElement("div");
    modal.id = "cs-stat-modal-overlay";

    modal.innerHTML = `
        <div class="cs-add-stat-modal">
            <div class="cs-add-stat-header">
                <div>
                    <div class="cs-add-stat-title">${isEdit ? csH("Edit Stat") : csH("Add Stat")}</div>
                    <div class="cs-add-stat-subtitle">
                        ${isEdit ? csH("Edit the complete stat definition.") : csH("Define a new persistent stat.")}
                    </div>
                </div>
                <button id="cs-stat-modal-close" class="cs-icon-btn cs-close-icon cs-modal-close" type="button" aria-label="${csH("Close")}">×</button>
            </div>

            <div class="cs-add-stat-content">
                <!-- v3: basics first (name, type, value), advanced JSON last -->
                <div class="cs-form-grid">
                    <div class="cs-form-group">
                        <label for="cs-stat-name">${csH("Name")}</label>
                        <input id="cs-stat-name" class="text_pole" type="text" value="${escapeHtml(current.name || "")}" placeholder="${csH("HP, Rank, Condition...")}" />
                    </div>

                    <div class="cs-form-group">
                        <label for="cs-stat-type">${csH("Stat Type")}</label>
                        <select id="cs-stat-type" class="text_pole">
                            <option value="number" ${current.type === "number" ? "selected" : ""}>${csH("Number")}</option>
                            <option value="text" ${current.type === "text" ? "selected" : ""}>${csH("Text")}</option>
                            <option value="boolean" ${current.type === "boolean" ? "selected" : ""}>${csH("True / False")}</option>
                            <option value="choice" ${current.type === "choice" ? "selected" : ""}>${csH("Choice List")}</option>
                        </select>
                    </div>
                </div>

                <div id="cs-stat-modal-options"></div>

                <div class="cs-form-group">
                    <label for="cs-stat-description">${csH("Description")}</label>
                    <textarea id="cs-stat-description" class="text_pole" rows="3" placeholder="${csH("Describe what this stat represents (shown to the AI and in the sheet).")}">${escapeHtml(current.description || "")}</textarea>
                </div>

                <div class="cs-form-group">
                    <label for="cs-stat-group">${csH("Group (optional, display only)")}</label>
                    <input id="cs-stat-group" class="text_pole" type="text" value="${escapeHtml(current.group || "")}" placeholder="${csH("Combat, Social, ...")}" />
                </div>

                <details class="cs-form-advanced"${(Array.isArray(current.triggers) && current.triggers.length) || (Array.isArray(current.syncCustom) && current.syncCustom.length) ? " open" : ""}>
                    <summary>${csH("Advanced — triggers & custom sync")}</summary>

                    <div class="cs-form-group">
                        <label for="cs-stat-triggers">${csH("Triggers (JSON array, optional — auto-events)")}</label>
                        <textarea id="cs-stat-triggers" class="text_pole" rows="4" placeholder='[{"when":"eff <= 0","action":"toast","message":"{{name}} is down"}]'>${escapeHtml(current.triggers ? JSON.stringify(current.triggers, null, 2) : "")}</textarea>
                    </div>

                    <div class="cs-form-group">
                        <label for="cs-stat-synccustom">${csH("Sync with custom paths (comma-separated, optional)")}</label>
                        <input id="cs-stat-synccustom" class="text_pole" type="text" value="${escapeHtml(Array.isArray(current.syncCustom) ? current.syncCustom.join(", ") : "")}" placeholder="quest.gems_found, quest.relics_found" />
                    </div>
                </details>
            </div>

            <div class="cs-add-stat-footer">
                <button id="cs-stat-modal-cancel" class="cs-cancel-button" type="button">${csH("Cancel")}</button>
                <button id="cs-stat-modal-confirm" class="cs-save-button" type="button">${isEdit ? csH("Apply") : csH("Add Stat")}</button>
            </div>
        </div>
    `;

    document.body.appendChild(modal);

    const typeSelect = modal.querySelector("#cs-stat-type");
    typeSelect?.addEventListener("change", () => {
        const nextType = typeSelect.value;

        if (nextType === current.type) {
            renderAddStatOptions(modal, nextType, current);
            return;
        }

        renderAddStatOptions(modal, nextType, {
            name: current.name,
            description: current.description,
            type: nextType,
            base: "",
            mod: 0,
            min: null,
            max: null,
            unit: "",
            progressBar: { enabled: false, color: "#2dd4bf", negativeColor: "" },
            options: [],
            onChange: current.onChange || ""
        });
    });

    renderAddStatOptions(modal, current.type, current);

    modal.querySelector("#cs-stat-modal-close")?.addEventListener("click", () => modal.remove());
    modal.querySelector("#cs-stat-modal-cancel")?.addEventListener("click", () => modal.remove());

    modal.addEventListener("click", event => {
        if (event.target === modal) modal.remove();
    });

    modal.querySelector("#cs-stat-modal-confirm")?.addEventListener("click", () => {
        const name = modal.querySelector("#cs-stat-name")?.value.trim();

        if (!name) {
            csToast.error("Stat name is required.");
            return;
        }

        const overlay = document.getElementById("character-state-overlay");

        const duplicate = [...overlay.querySelectorAll(".cs-edit-stat-row")]
            .some(other => {
                if (isEdit && other === row) return false;
                return (other.querySelector(".cs-edit-stat-name-input")?.value.trim() || "") === name;
            });

        if (duplicate) {
            csToast.error(csT("Stat \"{name}\" already exists.", { name }));
            return;
        }

        const type = typeSelect?.value || current.type;
        const nextStat = readStatFromModal(modal, name, type);

        if (!nextStat) return;

        if (isEdit && row) {
            const oldMod = current.type === "number" ? Number(current.mod || 0) : 0;
            nextStat.mod = nextStat.type === "number"
                ? (Number.isFinite(oldMod) ? oldMod : 0)
                : 0;

            row.dataset.originalName = row.dataset.originalName || current.name;
            row.querySelector(".cs-edit-stat-name-input").value = name;
            row.querySelector(".cs-edit-base-wrap").innerHTML = createBaseEditor(nextStat);
            row.querySelector(".cs-edit-mod-wrap").innerHTML =
                nextStat.type === "number"
                    ? `<input class="text_pole cs-edit-mod" type="number" value="${escapeHtml(nextStat.mod)}" />`
                    : `<div class="cs-mod-hidden">—</div>`;
            row._statDefinition = structuredClone(nextStat);
        } else {
            const newRow = createEditableStatRow(name, nextStat);
            newRow.classList.add("cs-drag-row");
            newRow.draggable = true;

            const statsContainer = document.getElementById("cs-edit-stats");

            if (statsContainer && anchorRow && statsContainer.contains(anchorRow)) {
                if (position === "before") {
                    anchorRow.before(newRow);
                } else {
                    anchorRow.after(newRow);
                }
            } else {
                statsContainer?.appendChild(newRow);
            }

            newRow.querySelector(".cs-edit-stat-name-input")?.focus();
        }

        modal.remove();
        wireStatRowButtons(overlay);
        csToast.success(isEdit ? csT("Stat \"{name}\" updated.", { name }) : csT("Stat \"{name}\" added.", { name }));
    });
}

function wireStatRowButtons(overlay) {
    overlay.querySelectorAll(".cs-edit-stat").forEach(button => {
        if (button.dataset.bound === "1") return;
        button.dataset.bound = "1";

        button.addEventListener("click", async () => {
            const row = button.closest(".cs-edit-stat-row");
            if (!row) return;

            const state = overlay?._editState || getCharacterState(overlay?._character);
            const definition = row._statDefinition || state.stats[row.dataset.originalName];
            if (!definition) return;

            const current = structuredClone(definition);
            current.name = row.querySelector(".cs-edit-stat-name-input")?.value.trim() || current.name;

            if (current.type === "number") {
                const base = Number(row.querySelector(".cs-edit-base")?.value);
                const mod = Number(row.querySelector(".cs-edit-mod")?.value);

                if (Number.isFinite(base)) current.base = base;
                if (Number.isFinite(mod)) current.mod = mod;
            } else if (current.type === "boolean") {
                current.base = Boolean(row.querySelector(".cs-edit-base-checkbox")?.checked);
            } else if (current.type === "choice") {
                current.base = row.querySelector(".cs-edit-base-select")?.value || current.base;
            } else {
                current.base = row.querySelector(".cs-edit-base")?.value || "";
            }

            openStatModal({
                mode: "edit",
                stat: current,
                row
            });
        });
    });
}

function setupCharacterSheetDragDrop(overlay) {
    const containers = [
        overlay.querySelector("#cs-edit-stats"),
        overlay.querySelector("#cs-edit-skills"),
        overlay.querySelector("#cs-edit-inventory")
    ].filter(Boolean);

    containers.forEach(container => {
        /* Rows are always draggable (native DnD), but drag is only
           accepted when it starts from the ☷ handle — dragging an input
           area is blocked so text editing keeps working.
           dragstart fires on the draggable row itself, so the handle
           check cannot run there: the mousedown origin is tracked
           instead and dragstart only validates it. */
        container.querySelectorAll(".cs-drag-row").forEach(row => {
            row.draggable = true;
        });

        container.addEventListener("mousedown", event => {
            const row = event.target.closest(".cs-drag-row");
            const fromHandle = Boolean(event.target.closest(".cs-drag-handle"));

            container._dragArmedRow =
                row && fromHandle && container.contains(row) ? row : null;
        });

        container.addEventListener("mouseup", () => {
            container._dragArmedRow = null;
        });

        container.addEventListener("dragstart", event => {
            const row = event.target.closest(".cs-drag-row");
            if (!row || !container.contains(row)) {
                event.preventDefault();
                return;
            }

            if (container._dragArmedRow !== row) {
                event.preventDefault();
                return;
            }

            container._dragRow = row;
            row.classList.add("cs-dragging");
            if (event.dataTransfer) event.dataTransfer.effectAllowed = "move";
        });

        container.addEventListener("dragover", event => {
            event.preventDefault();

            const dragging = container._dragRow;
            const target = event.target.closest(".cs-drag-row");

            if (!dragging || !target || dragging === target || !container.contains(target)) return;

            const rect = target.getBoundingClientRect();
            const after = event.clientY > rect.top + rect.height / 2;

            if (after) {
                target.after(dragging);
            } else {
                target.before(dragging);
            }
        });

        container.addEventListener("dragend", () => {
            const dragging = container._dragRow;
            if (dragging) dragging.classList.remove("cs-dragging");
            container._dragRow = null;
            container._dragArmedRow = null;
        });
    });
}

/* =========================================================
   SAVE EDIT MODE
========================================================= */

const CHARACTER_CARD_UNSET_SENTINEL = "__@@UNSET@@__";

/*
 * In-memory card write: MERGE into the existing extension blob instead of
 * replacing it wholesale. A bare `{ startingState }` assignment dropped an
 * externally-authored stable `characterId` — getCharacterKey then flipped
 * from `id:<stableId>` to `character:<avatar>|name:<name>` mid-session, so
 * the just-seeded entry could not be found again (split state, duplicate
 * seeds, duplicate audit). Hoisted: safe to call from earlier sections.
 */
function setCardStateData(character, startingState) {
    if (!character || typeof character !== "object") return;
    if (!character.data) character.data = {};
    if (!character.data.extensions) character.data.extensions = {};
    const existing = character.data.extensions["character-state"];
    character.data.extensions["character-state"] = {
        ...(existing && typeof existing === "object" ? existing : {}),
        startingState
    };
}

/*
 * Persist the Character Card startingState for `character` directly into
 * the card file via the native ST merge endpoint. Works for any character
 * object (active or a group member) and never touches chat runtime state.
 * Returns true when the card file was written.
 */
async function persistCharacterCardStartingState(character, startingState) {
    const context = SillyTavern.getContext();
    const avatar = String(character?.avatar ?? "").trim();

    if (!avatar) return false;

    try {
        const headers = typeof context.getRequestHeaders === "function"
            ? context.getRequestHeaders()
            : { "Content-Type": "application/json" };

        const body = {
            avatar,
            data: {
                extensions: {
                    "character-state": {}
                }
            }
        };

        /* 1) Remove any stale startingState keys from the card. */
        const clearBody = structuredClone(body);
        clearBody.data.extensions["character-state"].startingState = CHARACTER_CARD_UNSET_SENTINEL;

        const clearResponse = await fetch("/api/characters/merge-attributes", {
            method: "POST",
            headers,
            body: JSON.stringify(clearBody)
        });

        if (!clearResponse.ok) {
            throw new Error(`merge-attributes clear failed: ${clearResponse.status}`);
        }

        /* 2) Write the fresh startingState. */
        const setBody = structuredClone(body);
        setBody.data.extensions["character-state"].startingState = startingState;

        const setResponse = await fetch("/api/characters/merge-attributes", {
            method: "POST",
            headers,
            body: JSON.stringify(setBody)
        });

        if (!setResponse.ok) {
            throw new Error(`merge-attributes save failed: ${setResponse.status}`);
        }

        return true;
    } catch (error) {
        console.error(`[Character State] Character Card file save failed for ${avatar}:`, error);
        return false;
    }
}

/* =========================================================
   CARD DEFAULT RECOVERY (ONE-TIME, CONFIRMED)
   Cards used to be edited before defaults lived on the card:
   real defaults can still sit in the runtime of the character's
   single chats while data.extensions["character-state"] is missing.
   When a runtime seed would otherwise come out empty, we scan the
   character's single-chat headers (server-side metadata only) and,
   if a non-empty runtime is found, ask ONCE per session to write
   those defaults into the Character Card (same write path as ⇪ Push).
   Declining never modifies anything; the empty seed is skipped so the
   chat is not poisoned with an empty runtime entry.
========================================================= */

const cardDefaultRecoveryAskedKeys = new Set();
const cardDefaultRecoveryBusyKeys = new Set();

/*
 * Scan the single chats of `character` (metadata only, no message
 * bodies) for a runtime state that can act as the missing card
 * defaults. Returns candidates sorted by relevance:
 *   character's own current chat first, then chat size, then recency.
 */
async function findDefaultStateCandidateChats(character) {
    const context = SillyTavern.getContext();
    const avatar = String(character?.avatar ?? "").trim();
    if (!avatar) return [];

    try {
        const headers = typeof context.getRequestHeaders === "function"
            ? context.getRequestHeaders()
            : { "Content-Type": "application/json" };

        const response = await fetch("/api/characters/chats", {
            method: "POST",
            headers,
            body: JSON.stringify({ avatar_url: avatar, metadata: true })
        });

        if (!response.ok) {
            console.warn(`[Character State] Default-state chat scan failed for ${avatar}: HTTP ${response.status}`);
            return [];
        }

        const data = await response.json();
        if (!Array.isArray(data)) {
            console.warn(`[Character State] Default-state chat scan failed for ${avatar}: invalid server response.`);
            return [];
        }

        const key = getCharacterKey(character);
        if (!key) return [];

        const currentChatId = String(character?.chat ?? "").trim();
        const candidates = [];

        for (const item of data) {
            const fileId = String(item?.file_id ?? "").trim();
            if (!fileId) continue;

            const metadata = item?.chat_metadata &&
                typeof item.chat_metadata === "object"
                ? item.chat_metadata
                : {};

            let runtime = metadata?.character_states?.[key];

            if (!runtime || typeof runtime !== "object" || isStaleEmptyRuntime(runtime)) {
                runtime = undefined;
            }

            if (!runtime &&
                metadata.character_state &&
                typeof metadata.character_state === "object" &&
                !isStaleEmptyRuntime(metadata.character_state)) {
                /* Legacy single-character format still present in this chat. */
                runtime = metadata.character_state;
            }

            if (!runtime) continue;

            const starting = buildStartingStateFromRuntimeState(runtime);
            if (!hasStartingStateData(starting)) continue;

            candidates.push({
                fileId,
                chatItems: Number(item?.chat_items ?? 0),
                lastMes: Number(item?.last_mes ?? 0),
                isCurrent: fileId === currentChatId,
                starting
            });
        }

        candidates.sort((a, b) =>
            (Number(b.isCurrent) - Number(a.isCurrent)) ||
            (b.chatItems - a.chatItems) ||
            (b.lastMes - a.lastMes)
        );

        return candidates;
    } catch (error) {
        console.warn(`[Character State] Default-state chat scan failed for ${avatar}:`, error);
        return [];
    }
}

/*
 * One-time (per session) confirmed recovery of Character Card defaults
 * from a single-chat runtime of the same character. Writes the card via
 * the same merge-attributes path as the ⇪ Push button. Never touches any
 * chat runtime.
 */
async function attemptCardDefaultRecovery(character, force = false) {
    const key = getCharacterKey(character);
    const name = character?.name || key || "character";

    if (!key || (!force && cardDefaultRecoveryAskedKeys.has(key))) return false;
    if (cardDefaultRecoveryBusyKeys.has(key)) return false;

    cardDefaultRecoveryBusyKeys.add(key);

    try {
        const candidates = await findDefaultStateCandidateChats(character);

        if (!candidates.length) {
            console.warn(
                `[Character State] No single-chat runtime defaults found for ${name} (${character?.avatar}); empty seed avoided.`
            );
            /* No decision was made (nothing to offer): do NOT mark the key
               as asked, so a later scan can still offer recovery once the
               other chat actually carries defaults. */
            return false;
        }

        const candidate = candidates[0];

        const summaryParts = [];

        const statEntries = Object.entries(candidate.starting.stats || {})
            .slice(0, 8)
            .map(([statName, stat]) => `${statName} ${stat?.base ?? 0}`);

        if (statEntries.length) {
            summaryParts.push(statEntries.join(", "));
        }

        if (Array.isArray(candidate.starting.skills) && candidate.starting.skills.length) {
            summaryParts.push(`${candidate.starting.skills.length} skills`);
        }

        if (Array.isArray(candidate.starting.inventory) && candidate.starting.inventory.length) {
            summaryParts.push(`${candidate.starting.inventory.length} items`);
        }

        const summary = summaryParts.length
            ? summaryParts.join("; ")
            : "defaults";

        console.log(
            `[Character State] Card default recovery candidate for ${name}: chat "${candidate.fileId}" (${summary})`
        );

        const confirmed = await csConfirm(csT(
            "Character Card \"{name}\" has no saved default stats yet, and this chat has no runtime state for {name}.\n\nDefaults were found in the single-chat runtime \"{file}\": {summary}.\n\nCopy these defaults into the Character Card file (same as ⋯ ▸ Save this chat as the card defaults)?\nNo chat runtime is modified.",
            { name, file: candidate.fileId, summary }
        ));

        if (!confirmed) {
            console.warn(
                `[Character State] Card default recovery declined for ${name} (${character?.avatar}).`
            );
            /* A real decision was made: stop auto-offering this session.
               The sheet still offers the "⬆ Recover defaults" button. */
            cardDefaultRecoveryAskedKeys.add(key);
            return false;
        }

        const written = await persistCharacterCardStartingState(
            character,
            structuredClone(candidate.starting)
        );

        if (!written) {
            console.warn(
                `[Character State] Card default recovery for ${name} (${character?.avatar}) could not write the card file.`
            );
            return false;
        }

        /* Keep the in-memory card in sync so the seed below (and the
           sheet) reads the fresh defaults without another fetch. */
        setCardStateData(character, structuredClone(candidate.starting));

        console.log(
            `[Character State] Card defaults recovered for ${name} from chat "${candidate.fileId}":`,
            candidate.starting
        );

        cardDefaultRecoveryAskedKeys.add(key);
        return true;
    } catch (error) {
        console.error(
            `[Character State] Card default recovery failed for ${name} (${character?.avatar}):`,
            error
        );
        return false;
    } finally {
        cardDefaultRecoveryBusyKeys.delete(key);
    }
}

/*
 * Shared form parser for BOTH editors (card defaults and chat runtime).
 * Reads stat/skill/inventory/custom rows out of an overlay and fills
 * `state`. Returns false and shows a toast when the form is invalid.
 */
function readEditorFormIntoState(overlay, state) {
    const newStats = {};
    const statNames = new Set();

    for (const row of overlay.querySelectorAll(".cs-edit-stat-row")) {
        const originalName = row.dataset.originalName || "";
        const fallback = row._statDefinition || state.stats[originalName];
        if (!fallback) continue;

        const name = row.querySelector(".cs-edit-stat-name-input")?.value.trim();
        if (!name) continue;

        if (statNames.has(name)) {
            csToast.error(csT("Duplicate stat name: \"{name}\".", { name }));
            return false;
        }

        const stat = structuredClone(row._statDefinition || fallback);
        stat.name = name;

        if (stat.type === "number") {
            const base = Number(row.querySelector(".cs-edit-base")?.value);
            const mod = Number(row.querySelector(".cs-edit-mod")?.value);

            stat.base = Number.isFinite(base) ? base : Number(stat.base || 0);
            stat.mod = Number.isFinite(mod) ? mod : 0;
        } else if (stat.type === "boolean") {
            stat.base = Boolean(row.querySelector(".cs-edit-base-checkbox")?.checked);
            stat.mod = 0;
        } else if (stat.type === "choice") {
            const select = row.querySelector(".cs-edit-base-select");
            stat.base = select?.value || stat.base || "";

            if (!stat.options?.includes(stat.base)) {
                csToast.error(csT("Invalid Choice List value for \"{name}\".", { name }));
                return false;
            }

            stat.mod = 0;
        } else {
            stat.base = row.querySelector(".cs-edit-base")?.value || "";
            stat.mod = 0;
        }

        statNames.add(name);
        newStats[name] = stat;
    }

    state.stats = newStats;

    state.skills = [];

    for (const row of overlay.querySelectorAll(".cs-edit-skill-row")) {
        const name = row.querySelector(".cs-edit-skill-name")?.value.trim() || "";
        const description = row.querySelector(".cs-edit-skill-description")?.value || "";

        if (!name && !description.trim()) continue;

        state.skills.push({
            name: name || "Unnamed Skill",
            description
        });
    }

    state.skills = normalizeSkills(state.skills);

    /* Preserve item effect definitions the editor rows do not expose yet
       (AI-declared effects must survive a manual save). */
    const previousItemsByName = new Map(
        (state.inventory || []).map(item => [item.name, item])
    );

    state.inventory = [];

    for (const row of overlay.querySelectorAll(".cs-edit-item-row")) {
        const name = row.querySelector(".cs-edit-item-name")?.value.trim() || "";
        const description = row.querySelector(".cs-edit-item-description")?.value || "";

        const parsedQuantity = Number(
            row.querySelector(".cs-edit-item-quantity")?.value
        );

        const quantity = Number.isFinite(parsedQuantity)
            ? Math.max(0, Math.floor(parsedQuantity))
            : 1;

        const equippable = Boolean(
            row.querySelector(".cs-edit-item-equippable")?.checked
        );

        const equipped = equippable && Boolean(
            row.querySelector(".cs-edit-item-equipped")?.checked
        );

        if (!name && !description.trim()) continue;

        state.inventory.push({
            name: name || "Unnamed Item",
            quantity,
            description,
            equippable,
            equipped,
            effects: previousItemsByName.get(name)?.effects || []
        });
    }

    state.inventory = normalizeInventory(state.inventory);

    state.customText =
        overlay.querySelector("#cs-edit-custom")?.value || "";

    return true;
}

async function saveCharacterSheetEditor(overlay) {
    const character = overlay?._character || resolveActiveCharacter();

    if (!character || isUserEntity(character)) {
        csToast.error("No character card could be resolved for this editor.");
        return;
    }

    const state = overlay._editState || buildEditorStateForCharacter(character);

    if (!readEditorFormIntoState(overlay, state)) return;

    const customProblem = customTextJsonProblem(state);
    if (customProblem) {
        csToast.error(customProblem);
        return;
    }

    /* The Custom text area is authoritative for the custom defaults too:
       adopt its embedded JSON into the structured custom object so a
       Reset really restores the values the user just typed. */
    adoptCustomTextAsCustomObject(state);

    /* =========================
       SAVE STARTING STATE
       Character Card defaults only. Chat runtime is never written here:
       runtime is per-chat save data and must not follow card edits.
       Mod stays chat/runtime-only and is zeroed on the card.
    ========================== */

    if (!character.data) character.data = {};
    if (!character.data.extensions) character.data.extensions = {};

    const startingStats = {};

    for (const [name, stat] of Object.entries(state.stats)) {
        const definition = structuredClone(stat);
        definition.mod = 0;
        startingStats[name] = definition;
    }

    /* v3 B1: setCardStateData takes the startingState itself — the old
       call wrapped it once more and wrote startingState.startingState into
       the card (getStartingState then read an EMPTY sheet). */
    setCardStateData(character, {
        stats: startingStats,
        custom: structuredClone(state.custom || {}),
        customText: state.customText || "",
        skills: structuredClone(state.skills || []),
        inventory: structuredClone(state.inventory || [])
    });

    const cardWritten = await persistCharacterCardStartingState(
        character,
        structuredClone(
            character.data.extensions["character-state"].startingState
        )
    );

    if (!cardWritten) {
        csToast.error(
            "Character Card file could not be written — defaults kept in memory only and will NOT appear in new chats. Check the console for errors."
        );
    } else {
        csToast.success("Character Card defaults saved. This chat is unchanged — use ⋯ ▸ Reset this chat from the card to apply them here.");
    }
    await reopenCharacterSheet(overlay, "view", character);
}

/*
 * Save the "✎ Chat" runtime editor: writes the edited Base/Mod/skills/
 * inventory/custom straight into chatMetadata.character_states of THIS
 * chat only. Works for NPC characters and for the {{user}} entity.
 * The Character Card is never touched here.
 */
async function saveRuntimeChatEditor(overlay) {
    const character = overlay?._character || resolveActiveCharacter();

    if (!character) {
        csToast.error("No active character could be resolved.");
        return;
    }

    const context = SillyTavern.getContext();
    takeSafetySnapshot(context, "editor save -> " + (overlay._character?.name || "?"));

    if (!context.chatMetadata) {
        csToast.error("No active chat metadata.");
        return;
    }

    if (!context.chatMetadata.character_states ||
        typeof context.chatMetadata.character_states !== "object" ||
        Array.isArray(context.chatMetadata.character_states)) {
        context.chatMetadata.character_states = {};
    }

    const key = getStateEntityKey(character);
    if (!key) {
        csToast.error("Could not resolve a state key for this character.");
        return;
    }

    /* Start from the editor state the overlay was opened with: it holds
       the current definitions (fallback for rows without an attached
       definition). Building from getDefaultState() here would drop every
       row whose definition lives only in the previous state, wiping all
       stats on save. */
    const state = overlay._editState && typeof overlay._editState === "object"
        ? structuredClone(overlay._editState)
        : getDefaultState();

    if (!readEditorFormIntoState(overlay, state)) return;

    const customProblem = customTextJsonProblem(state);
    if (customProblem) {
        csToast.error(customProblem);
        return;
    }

    /* A pasted JSON block in the Custom text area becomes the structured
       custom object again (AI updates will merge on top of it). */
    adoptCustomTextAsCustomObject(state);

    context.chatMetadata.character_states[key] = normalizeRuntimeState(state);

    pushWholeAudit(context, key, "manual", "editor");

    await saveChatState(context);

    if (isUserEntity(character)) {
        csToast.success("{{user}} runtime state saved for this chat.");
    } else if (character?.csSideNpc) {
        csToast.success("Side NPC runtime state saved for this chat.");
    } else {
        const cardHasDefaults = hasStartingStateData(
            unwrapNestedStartingState(character?.data?.extensions?.["character-state"]?.startingState)
        );

        if (cardMissingRuntimeDefinitions(character, state)) {
            const shouldPush = await csConfirm(
                "Runtime saved for THIS chat.\n\nThe Character Card is missing some of these definitions (stats, min/max, AI base-edit, ...) — NEW chats of this character will NOT inherit them.\n\nPush these definitions to the Character Card now? (same as ⇪ Push)"
            );

            if (shouldPush) {
                const starting = buildStartingStateFromRuntimeState(state);

                setCardStateData(character, structuredClone(starting));

                const written = await persistCharacterCardStartingState(
                    character,
                    structuredClone(starting)
                );

                if (written) {
                    csToast.success("Character Card definitions updated — new chats will inherit them.");
                } else {
                    csToast.error("Character Card file could not be written — settings will NOT be inherited by new chats. Check the console for errors.");
                }
            }
        }

        csToast.success(
            cardHasDefaults
                ? csT("Chat runtime state saved for this chat. The Character Card was not modified.")
                : csT("Chat runtime state saved for THIS chat only. Use ⋯ ▸ Save this chat as the card defaults so other chats of this character get the same schema.")
        );
    }

    await reopenCharacterSheet(overlay, "view", character);
}


