function renderInventoryView(state) {
    if (!Array.isArray(state.inventory) || !state.inventory.length) {
        return `<div class="cs-empty-card"><div class="cs-empty-text">${escapeHtml(csT("No items"))}</div></div>`;
    }

    return state.inventory.map(item => {
        const equipBadge = item.equippable
            ? `<span class="${item.equipped ? "cs-equipped-check" : "cs-equipped-cross"}" title="${item.equipped ? csH("Equipped") : csH("Not equipped")}">${item.equipped ? "✓" : "✕"}</span>`
            : "";

        const effectTags = Array.isArray(item.effects) && item.effects.length
            ? item.effects.map(effect => {
                const deltas = Object.entries(effect?.stats || {})
                    .map(([statName, delta]) => `${statName} ${delta > 0 ? "+" : ""}${delta}`)
                    .join(", ");
                const label = [effect?.name, deltas].filter(Boolean).join(" · ");

                return `<span class="cs-item-effect-tag" title="${item.equipped ? csH("Active while equipped") : csH("Applies when equipped")}">${escapeHtml(applyCsMacros(label))}</span>`;
            }).join("")
            : "";

        return `
            <div class="cs-item-card">
                <div class="cs-item-main">
                    <div class="cs-item-name">${renderRichText(item.name || "")}</div>
                    <div class="cs-item-description">${renderRichText(item.description || "")}</div>
                    ${effectTags ? `<div class="cs-item-effects">${effectTags}</div>` : ""}
                </div>

                <div class="cs-item-right">
                    <div class="cs-item-quantity">x${escapeHtml(item.quantity ?? 1)}</div>
                    ${equipBadge}
                </div>
            </div>
        `;
    }).join("");
}


