function getCsLanguage() {
    try {
        const choice = getExtensionSettings().uiLanguage;
        if (choice === "en" || choice === "vi") return choice;
    } catch {
        /* settings unreadable — fall through to the ST locale */
    }

    try {
        const locale = String(SillyTavern.getContext()?.getCurrentLocale?.() || globalThis.navigator?.language || "en").toLowerCase();
        return locale.startsWith("vi") ? "vi" : "en";
    } catch {
        return "en";
    }
}

/* csT("No stats match \"{q}\".", { q }) — vars are substituted AFTER the
   lookup and are NOT escaped: escape at the HTML sink as usual. */
function csT(text, vars = null) {
    let result = getCsLanguage() === "vi" && Object.prototype.hasOwnProperty.call(CS_VI, text)
        ? CS_VI[text]
        : text;

    if (vars) {
        for (const [name, value] of Object.entries(vars)) {
            result = result.replaceAll(`{${name}}`, () => String(value));
        }
    }

    return result;
}

/* csH(): csT() for an HTML text / attribute sink — the WHOLE result
   (template + vars) is escaped, so pass vars RAW. Keys whose English
   source contains markup or entities use csT() at the sink instead. */
function csH(text, vars = null) {
    return escapeHtml(csT(text, vars));
}

/* v3.1: every toast goes through the dictionary (English text = key). */
const csToast = Object.fromEntries(["success", "error", "warning", "info"].map(kind => [
    kind,
    (message, title, ...rest) => globalThis.toastr?.[kind]?.(
        typeof message === "string" ? csT(message) : message,
        typeof title === "string" ? csT(title) : title,
        ...rest
    )
]));

function csPopupApi() {
    const context = SillyTavern.getContext?.();
    if (typeof context?.callGenericPopup === "function" && context?.POPUP_TYPE) return context;
    return null;
}

function csPopupBody(message, danger = false) {
    /* Popup content is HTML: escape, keep line breaks. ST 1.18 popups have
       no customClass option — the class lives on the content wrapper. */
    return `<div class="cs-popup${danger ? " cs-popup-danger" : ""}"><div class="cs-popup-text">${escapeHtml(String(message ?? "")).replace(/\n/g, "<br>")}</div></div>`;
}

async function csConfirm(message, { okLabel = null, cancelLabel = null, danger = false } = {}) {
    /* Callers pass English (or an already csT()-ed string with vars) —
       translated here like csToast. */
    message = typeof message === "string" ? csT(message) : message;
    okLabel = typeof okLabel === "string" ? csT(okLabel) : okLabel;
    cancelLabel = typeof cancelLabel === "string" ? csT(cancelLabel) : cancelLabel;
    const api = csPopupApi();

    if (!api) {
        return typeof globalThis.confirm === "function" ? Boolean(globalThis.confirm(message)) : false;
    }

    try {
        const result = await api.callGenericPopup(csPopupBody(message, danger), api.POPUP_TYPE.CONFIRM, "", {
            okButton: okLabel || csT("OK"),
            cancelButton: cancelLabel || csT("Cancel"),
            leftAlign: true
        });
        return result === api.POPUP_RESULT?.AFFIRMATIVE || result === 1 || result === true;
    } catch (error) {
        console.warn("[Character State] Popup failed, falling back to confirm():", error);
        return typeof globalThis.confirm === "function" ? Boolean(globalThis.confirm(message)) : false;
    }
}

async function csPrompt(message, defaultValue = "") {
    message = typeof message === "string" ? csT(message) : message;
    const api = csPopupApi();

    if (!api) {
        return typeof globalThis.prompt === "function" ? globalThis.prompt(message, defaultValue) : null;
    }

    try {
        const result = await api.callGenericPopup(csPopupBody(message), api.POPUP_TYPE.INPUT, String(defaultValue ?? ""), {
            okButton: csT("OK"),
            cancelButton: csT("Cancel"),
            leftAlign: true
        });
        return typeof result === "string" ? result : null;
    } catch (error) {
        console.warn("[Character State] Popup failed, falling back to prompt():", error);
        return typeof globalThis.prompt === "function" ? globalThis.prompt(message, defaultValue) : null;
    }
}

/* ---- overlay behaviours ----------------------------------------------- */

/* Overlays whose form content is worth protecting from an accidental
   backdrop click / Esc. View-only overlays (log, timeline, world, …) close
   freely even when their filter box has text. */
const CS_FORM_OVERLAY_IDS = new Set([
    "cs-stat-modal-overlay",
    "cs-effect-modal-overlay",
    "cs-settings-overlay",
    "cs-custom-meta-overlay",
    "cs-side-npc-modal-overlay",
    "cs-field-paste-overlay",
    "cs-clock-overlay"
]);

const CS_FOCUSABLE = 'button:not([disabled]), [href], input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

function isCsOverlayRoot(element) {
    if (!element || element.nodeType !== 1 || element.parentElement !== document.body) return false;
    const id = String(element.id || "");
    return id === "character-state-overlay" || (id.startsWith("cs-") && id.endsWith("-overlay"));
}

function getTopCsOverlay() {
    const roots = [...(document.body?.children || [])].filter(isCsOverlayRoot);
    if (!roots.length) return null;

    /* Highest z-index wins; DOM order breaks ties (later = on top). */
    let top = null;
    let topZ = -Infinity;

    for (const root of roots) {
        const z = Number(getComputedStyle(root).zIndex) || 0;
        if (z >= topZ) {
            top = root;
            topZ = z;
        }
    }

    return top;
}

function overlayHasUnsavedInput(overlay) {
    if (overlay?.dataset?.csDirty !== "1") return false;
    if (overlay.id === "character-state-overlay") {
        return overlay.dataset.mode === "edit" || overlay.dataset.mode === "editRuntime";
    }
    return CS_FORM_OVERLAY_IDS.has(overlay.id);
}

/* Close through the overlay's OWN path so promises resolve and cleanup
   runs: a backdrop click (every overlay handles target === root), then an
   explicit close/cancel button, then a plain remove. */
function requestCsOverlayClose(overlay) {
    if (!overlay?.isConnected) return;

    overlay.__csCloseConfirmed = true;
    overlay.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true }));
    if (!overlay.isConnected) return;

    const closer = overlay.querySelector(
        '#cs-x-btn, #cs-cancel-btn, [id$="-close-btn"], [id$="-cancel-btn"], .cs-modal-close:not(.cs-shell-close), .cs-cancel-button'
    );

    /* The closer owns the close (it may reopen the sheet asynchronously,
       e.g. edit Cancel → view) — never also remove() behind its back. */
    if (closer) {
        closer.click();
        return;
    }

    overlay.remove();
}

async function confirmDiscardIfDirty(overlay) {
    if (!overlayHasUnsavedInput(overlay)) return true;
    return csConfirm(csT("Discard unsaved changes?"), {
        okLabel: csT("Discard"),
        cancelLabel: csT("Keep editing"),
        danger: true
    });
}

/* v3.1 shell for the classic secondary overlays (.cs-log-window): one size
   scale instead of 13 inline width/height styles (those beat the phone
   full-screen rule), dialog semantics, and a header ✕ on every window. */
function enhanceCsOverlayShell(overlay) {
    const windowEl = overlay.querySelector?.(":scope > .cs-log-window");
    if (!windowEl || windowEl.dataset.csShell === "1") return;
    windowEl.dataset.csShell = "1";

    const inline = String(windowEl.getAttribute("style") || "");
    const width = Number(inline.match(/min\((\d+)px/)?.[1] || 0);

    if (inline) {
        windowEl.removeAttribute("style");
        windowEl.classList.add(width && width <= 480 ? "cs-size-s" : width && width <= 640 ? "cs-size-m" : "cs-size-l");
        if (/height\s*:/.test(inline)) windowEl.classList.add("cs-size-tall");
    }

    windowEl.setAttribute("role", "dialog");
    windowEl.setAttribute("aria-modal", "true");

    const title = windowEl.querySelector(".cs-log-title");
    if (title) {
        title.id ||= `${overlay.id}-title`;
        windowEl.setAttribute("aria-labelledby", title.id);
    }

    /* v3.1: Change log / Timeline / Snapshots behave as ONE "History" screen
       — a shared tab bar switches between them in place. */
    const historyTabs = {
        "cs-log-overlay": "log",
        "cs-timeline-overlay": "timeline",
        "cs-snapshots-overlay": "snapshots"
    };

    if (historyTabs[overlay.id] && !windowEl.querySelector(".cs-history-tabs")) {
        const bar = document.createElement("div");
        bar.className = "cs-tabs cs-history-tabs";
        bar.setAttribute("role", "tablist");
        bar.innerHTML = [
            ["log", "list", csT("Change log")],
            ["timeline", "timeline", csT("Timeline")],
            ["snapshots", "clock-rotate-left", csT("Snapshots")]
        ].map(([key, icon, label]) => `
            <button class="cs-tab${historyTabs[overlay.id] === key ? " active" : ""}" type="button" role="tab"
                aria-selected="${historyTabs[overlay.id] === key}" data-cs-history-tab="${key}">${csIcon(icon)}<span class="cs-tab-label">${escapeHtml(label)}</span></button>`).join("");

        bar.addEventListener("click", event => {
            const tab = event.target.closest?.("[data-cs-history-tab]");
            if (!tab || tab.classList.contains("active")) return;

            const sheetCharacter = document.getElementById("character-state-overlay")?._character || null;
            overlay.remove();

            if (tab.dataset.csHistoryTab === "log") void openAuditLogOverlay(sheetCharacter);
            else if (tab.dataset.csHistoryTab === "timeline") openTimelineOverlay();
            else openSnapshotManager(sheetCharacter);
        });

        windowEl.querySelector(".cs-log-header")?.after(bar);
    }

    const header = windowEl.querySelector(".cs-log-header");
    if (header && !header.querySelector(".cs-shell-close")) {
        const close = document.createElement("button");
        close.type = "button";
        close.className = "cs-shell-close cs-modal-close";
        close.setAttribute("aria-label", csT("Close"));
        close.title = csT("Close");
        close.innerHTML = csIcon("xmark");
        close.addEventListener("click", async () => {
            if (await confirmDiscardIfDirty(overlay)) requestCsOverlayClose(overlay);
        });
        header.prepend(close);
    }
}

let csOverlayBehaviorsInstalled = false;

function installCsOverlayBehaviors() {
    if (csOverlayBehaviorsInstalled || typeof document?.addEventListener !== "function") return;
    csOverlayBehaviorsInstalled = true;

    /* Unsaved-input tracking (form overlays only, see overlayHasUnsavedInput). */
    const markDirty = event => {
        const root = event.target?.closest?.('#character-state-overlay, body > [id^="cs-"][id$="-overlay"]');
        if (root && isCsOverlayRoot(root)) root.dataset.csDirty = "1";
    };
    document.addEventListener("input", markDirty, true);
    document.addEventListener("change", markDirty, true);

    /* Structural edits fire no input event (add / delete / reorder rows,
       fold buttons, the stat modal writing back into the editor): any
       button press inside an EDIT sheet's content, or a confirmed stat
       modal, marks the sheet dirty. */
    document.addEventListener("click", event => {
        const target = event.target;
        if (!target?.closest) return;

        if (target.closest("#cs-stat-modal-confirm")) {
            const sheet = document.getElementById("character-state-overlay");
            if (sheet && sheet.dataset.mode !== "view") sheet.dataset.csDirty = "1";
            return;
        }

        const sheet = target.closest("#character-state-overlay");
        if (sheet && sheet.dataset.mode !== "view" && target.closest(".cs-content button, .cs-content [draggable]")) {
            sheet.dataset.csDirty = "1";
        }
    }, true);
    document.addEventListener("drop", markDirty, true);

    /* Backdrop click on a dirty form: ask before the overlay's own handler
       removes it (capture phase runs first). */
    document.addEventListener("click", event => {
        const root = event.target;
        if (!isCsOverlayRoot(root) || event.target !== root) return;
        if (root.__csCloseConfirmed) return;
        if (!overlayHasUnsavedInput(root)) return;

        event.stopImmediatePropagation();
        event.preventDefault();

        void confirmDiscardIfDirty(root).then(ok => {
            if (ok) requestCsOverlayClose(root);
        });
    }, true);

    document.addEventListener("keydown", event => {
        const top = getTopCsOverlay();
        if (!top) return;

        /* ST popups (dialog top layer) own the keyboard while open. */
        if (document.querySelector("dialog[open].popup")) return;

        if (event.key === "Escape") {
            /* A floating menu inside the sheet closes first. */
            const menu = top.querySelector(".cs-menu-popover:not([hidden])");
            if (menu) {
                menu.hidden = true;
                event.preventDefault();
                event.stopPropagation();
                return;
            }

            event.preventDefault();
            event.stopPropagation();

            void confirmDiscardIfDirty(top).then(ok => {
                if (ok) requestCsOverlayClose(top);
            });
            return;
        }

        if (event.key === "Tab") {
            const focusables = [...top.querySelectorAll(CS_FOCUSABLE)]
                .filter(element => element.offsetParent !== null || element === document.activeElement);
            if (!focusables.length) return;

            const first = focusables[0];
            const last = focusables[focusables.length - 1];

            if (!top.contains(document.activeElement)) {
                event.preventDefault();
                first.focus();
            } else if (event.shiftKey && document.activeElement === first) {
                event.preventDefault();
                last.focus();
            } else if (!event.shiftKey && document.activeElement === last) {
                event.preventDefault();
                first.focus();
            }
        }
    }, true);

    /* Initial focus: first field of a new overlay (or its dialog box). */
    if (typeof MutationObserver !== "undefined" && document.body) {
        new MutationObserver(mutations => {
            for (const mutation of mutations) {
                /* v3.1.1 U10: focus goes back to what opened the overlay
                   (unless another Character State overlay is still open) */
                for (const node of mutation.removedNodes) {
                    /* detached now: isCsOverlayRoot (parent = body) is false */
                    const id = String(node?.id || "");
                    if (node?.nodeType !== 1 || !(id === "character-state-overlay" || (id.startsWith("cs-") && id.endsWith("-overlay")))) continue;
                    const opener = node._csOpener;
                    if (!opener?.isConnected) continue;
                    if ([...document.body.children].some(child => isCsOverlayRoot(child))) continue;
                    if (document.activeElement && document.activeElement !== document.body) continue;
                    opener.focus?.({ preventScroll: true });
                }

                for (const node of mutation.addedNodes) {
                    if (!isCsOverlayRoot(node)) continue;

                    const active = document.activeElement;
                    if (active && active !== document.body && !node.contains(active)) node._csOpener = active;
                    enhanceCsOverlayShell(node);

                    requestAnimationFrame(() => {
                        if (!node.isConnected || node.contains(document.activeElement)) return;
                        const field = node.querySelector('input:not([type="hidden"]):not([type="checkbox"]), textarea, select');
                        const target = field && !node.id.endsWith("log-overlay") && node.id !== "character-state-overlay"
                            ? field
                            : node.querySelector(CS_FOCUSABLE);
                        target?.focus?.({ preventScroll: true });
                    });
                }
            }
        }).observe(document.body, { childList: true });
    }
}

/* =========================================================
   HELPERS
========================================================= */

function escapeHtml(text) {
    return String(text)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
}

function formatNumber(value) {
    if (typeof value !== "number" || !Number.isFinite(value)) return escapeHtml(value);
    return value.toLocaleString("en-US");
}

/* Same as formatNumber for numbers, but NEVER HTML-escapes: for prompt
   text, marker summaries and tool results (plain-text sinks). */
function formatPlainValue(value) {
    if (typeof value === "number" && Number.isFinite(value)) return value.toLocaleString("en-US");
    return String(value ?? "");
}

function downloadTextFile(filename, text) {
    try {
        const blob = new Blob([text], { type: "text/plain;charset=utf-8" });
        const url = URL.createObjectURL(blob);
        const anchor = document.createElement("a");
        anchor.href = url;
        anchor.download = filename;
        document.body.appendChild(anchor);
        anchor.click();

        setTimeout(() => {
            document.body.removeChild(anchor);
            URL.revokeObjectURL(url);
        }, 0);
    } catch (error) {
        console.error("[Character State] Download failed:", error);
        csToast.error("Could not download the file.");
    }
}

async function copyTextToClipboard(text) {
    if (navigator?.clipboard?.writeText) {
        try {
            await navigator.clipboard.writeText(text);
            return true;
        } catch {
            /* fall through to the legacy path */
        }
    }

    try {
        const textarea = document.createElement("textarea");
        textarea.value = text;
        textarea.style.position = "fixed";
        textarea.style.opacity = "0";
        document.body.appendChild(textarea);
        textarea.select();
        const ok = document.execCommand("copy");
        document.body.removeChild(textarea);
        return ok;
    } catch {
        return false;
    }
}

/* =========================================================
   SETTINGS PANEL (GLOBAL, localStorage)
   One screen controls the extension's optional behaviors. Every
   feature stays OFF unless the user opts in; defaults keep the
   classic behavior of every chat type (RPG or not).
========================================================= */

const SETTINGS_STORAGE_KEY = "character-state:settings:v1";

const DEFAULT_SETTINGS = {
    heuristicEnabled: false,
    clockFallbackMinutes: 0,
    snapshotAutoInterval: 20,
    historyEnabled: true,
    groupsEnabled: true,
    auditCapDefault: 1000,
    customModeDefault: null,
    showEventCards: true,
    groupLazyLoading: true,
    aiSheetCreate: false,
    /* v3 UI */
    uiLanguage: "en",
    promptDetail: "standard",
    hudEnabled: true,
    eventCardsExpanded: false,
    eventCardSnapshotRow: false
};

/* v3 P9: getExtensionSettings runs ~17× per turn — keep the parsed object
   keyed on the raw string (getItem is cheap, JSON.parse is not). Callers
   get a fresh shallow copy so nobody can mutate the cache. */
let extensionSettingsCache = { raw: undefined, value: null };

function getExtensionSettings() {
    try {
        const raw = globalThis.localStorage?.getItem(SETTINGS_STORAGE_KEY) ?? null;

        if (raw !== extensionSettingsCache.raw || !extensionSettingsCache.value) {
            const parsed = raw ? JSON.parse(raw) : {};
            extensionSettingsCache = {
                raw,
                value: {
                    ...DEFAULT_SETTINGS,
                    ...(parsed && typeof parsed === "object" ? parsed : {})
                }
            };
        }

        return { ...extensionSettingsCache.value };
    } catch {
        return { ...DEFAULT_SETTINGS };
    }
}

function saveExtensionSettings(patch) {
    try {
        const merged = { ...getExtensionSettings(), ...patch };
        globalThis.localStorage?.setItem(SETTINGS_STORAGE_KEY, JSON.stringify(merged));
        return merged;
    } catch {
        return getExtensionSettings();
    }
}

/* v3.1: one JSON file with everything stored in THIS browser — settings,
   presets, components, user template — to back up or move to another
   machine. Chat data is not included (it lives in the chat files). */
const CS_CONFIG_EXPORT_FORMAT = "character-state-config";
const CS_CONFIG_STORAGE_KEYS = {
    settings: SETTINGS_STORAGE_KEY,
    presets: PRESET_STORAGE_KEY,
    components: COMPONENTS_STORAGE_KEY,
    userTemplate: USER_TEMPLATE_STORAGE_KEY
};

function buildConfigExport() {
    const sections = {};

    for (const [section, storageKey] of Object.entries(CS_CONFIG_STORAGE_KEYS)) {
        try {
            const raw = globalThis.localStorage?.getItem(storageKey);
            sections[section] = raw ? JSON.parse(raw) : null;
        } catch {
            sections[section] = null;
        }
    }

    return { format: CS_CONFIG_EXPORT_FORMAT, version: 1, exportedAt: new Date().toISOString(), ...sections };
}

async function importConfigFromText(text) {
    let parsed;

    try {
        parsed = JSON.parse(String(text || ""));
    } catch {
        csToast.error("Pasted JSON could not be parsed.");
        return false;
    }

    if (parsed?.format !== CS_CONFIG_EXPORT_FORMAT) {
        csToast.error(csT("This file is not a Character State configuration export."));
        return false;
    }

    /* review F7: only sections with the shape their reader expects —
       `presets: {}` used to replace every preset with nothing */
    const shapeOk = {
        settings: value => Boolean(value) && typeof value === "object" && !Array.isArray(value),
        presets: value => Array.isArray(value),
        components: value => Array.isArray(value),
        userTemplate: value => Boolean(value) && typeof value === "object" && !Array.isArray(value)
    };
    const present = Object.keys(CS_CONFIG_STORAGE_KEYS).filter(section =>
        parsed[section] !== null && parsed[section] !== undefined && shapeOk[section](parsed[section]));

    if (!present.length) {
        csToast.error(csT("This file is not a Character State configuration export."));
        return false;
    }
    const presetCount = Array.isArray(parsed.presets) ? parsed.presets.length : 0;
    const componentCount = Array.isArray(parsed.components) ? parsed.components.length : 0;

    if (!await csConfirm(csT("Import this configuration?\n\nSections: {sections}\nPresets: {presets} · Components: {components}\n\nThe current settings / presets / components / user template of this browser are REPLACED by the file (chat data is not touched).", {
        sections: present.join(", ") || "—",
        presets: presetCount,
        components: componentCount
    }), { okLabel: csT("Import"), danger: true })) return false;

    for (const section of present) {
        globalThis.localStorage?.setItem(CS_CONFIG_STORAGE_KEYS[section], JSON.stringify(parsed[section]));
    }

    csToast.success(csT("Configuration imported."));
    return true;
}

function openSettingsOverlay() {
    document.getElementById("cs-settings-overlay")?.remove();

    const overlay = document.createElement("div");
    overlay.id = "cs-settings-overlay";
    overlay.className = "cs-log-overlay";

    const settings = getExtensionSettings();

    const checkboxRow = (id, label, hint, checked) => `
        <div class="cs-settings-row">
            <label class="cs-settings-label">
                <input id="${id}" type="checkbox" ${checked ? "checked" : ""} />
                <span>${label}</span>
            </label>
            <div class="cs-settings-hint">${hint}</div>
        </div>
    `;

    overlay.innerHTML = `
        <div class="cs-log-window" style="width:min(640px,94vw);">
            <div class="cs-log-header">
                <div class="cs-log-title">${csIcon("gear")} ${escapeHtml(csT("Character State — Settings"))}</div>
                <div class="cs-log-subtitle">${csH("Stored in this browser · defaults keep the classic behavior")}</div>
            </div>
            <div class="cs-log-body" style="padding:16px 20px;">
                <div class="cs-settings-row">
                    <label class="cs-settings-label" for="cs-set-ui-language">${escapeHtml(csT("Interface language"))}${getCsLanguage() === "vi" ? " · Interface language" : ""}</label>
                    <select id="cs-set-ui-language" class="text_pole cs-log-select" style="width:240px;">
                        <option value="auto" ${settings.uiLanguage !== "en" && settings.uiLanguage !== "vi" ? "selected" : ""}>${escapeHtml(csT("Auto (follow SillyTavern)"))}</option>
                        <option value="en" ${settings.uiLanguage === "en" ? "selected" : ""}>English</option>
                        <option value="vi" ${settings.uiLanguage === "vi" ? "selected" : ""}>Tiếng Việt</option>
                    </select>
                </div>
                <div class="cs-settings-row">
                    <label class="cs-settings-label" for="cs-set-prompt-detail">${escapeHtml(csT("Prompt detail"))}</label>
                    <select id="cs-set-prompt-detail" class="text_pole cs-log-select" style="width:240px;">
                        <option value="standard" ${settings.promptDetail !== "maximum" ? "selected" : ""}>${escapeHtml(csT("Standard"))}</option>
                        <option value="maximum" ${settings.promptDetail === "maximum" ? "selected" : ""}>${escapeHtml(csT("Maximum (smartest, more tokens)"))}</option>
                    </select>
                    <div class="cs-settings-hint">${escapeHtml(csT("Maximum shows the model up to 40,000 characters of custom data (Standard: 8,000) and always sends every group member in full. Best when input tokens are not a concern."))}</div>
                </div>
                ${checkboxRow(
                    "cs-set-hud",
                    escapeHtml(csT("Show pinned stats above the chat input")),
                    escapeHtml(csT("Pin stats with ★ on the sheet; they appear as a compact bar with the last change.")),
                    settings.hudEnabled !== false
                )}
                ${checkboxRow(
                    "cs-set-heuristic",
                    csH("Heuristic parser (fallback when the model forgets STATE_UPDATE)"),
                    csH("Detects clear patterns like \"takes 12 damage\" in plain text and applies them. Risk of false positives — recommended only with weak models."),
                    Boolean(settings.heuristicEnabled)
                )}
                ${checkboxRow(
                    "cs-set-history",
                    csH("Record stat history (graphs & sparklines)"),
                    csH("One point per change, capped per stat. User-only data."),
                    Boolean(settings.historyEnabled)
                )}
                ${checkboxRow(
                    "cs-set-groups",
                    csH("Show stat groups as tabs"),
                    csH("Only matters when stats carry a group field."),
                    Boolean(settings.groupsEnabled)
                )}
                ${checkboxRow(
                    "cs-set-event-cards",
                    csH("Show state-change cards in chat"),
                    csH("A styled card appears after every STATE_UPDATE / effect expiry (system message, never sent to the model)."),
                    Boolean(settings.showEventCards)
                )}
                ${checkboxRow(
                    "cs-set-event-cards-expanded",
                    escapeHtml(csT("Expand event cards by default")),
                    csH("Off: each card is one line (who changed + the two biggest moves); click to see every change."),
                    Boolean(settings.eventCardsExpanded)
                )}
                ${checkboxRow(
                    "cs-set-event-card-snapshot",
                    escapeHtml(csT("Show the full stat list on event cards")),
                    csH("Adds a line with EVERY stat's current value inside each card (long for big sheets)."),
                    Boolean(settings.eventCardSnapshotRow)
                )}
                ${checkboxRow(
                    "cs-set-group-lazy",
                    csH("Lazy group prompt (token saver)"),
                    csH("In group chats, members that are not active this turn get a one-line summary instead of their full state; read the full state with state_get. Turn OFF to restore full injection for every member (needed for text-protocol-only models)."),
                    Boolean(settings.groupLazyLoading)
                )}
                ${checkboxRow(
                    "cs-set-ai-sheet-create",
                    csH("ARM: let the AI design a sheet once (SHEET_CREATE, this chat only)"),
                    csH("When armed, the model may (re)define a character's stats and seed custom data IN THIS CHAT via <SHEET_CREATE> / state_create_sheet — for first-time setup of a character whose card has no sheet yet, or a redesign. Definitions stay chat-scoped; the card is NEVER modified (saving it as the card defaults stays manual: ⋯ ▸ Save this chat as the card defaults…). Auto-disarms after one successful create."),
                    Boolean(settings.aiSheetCreate)
                )}

                <div class="cs-settings-row">
                    <label class="cs-settings-label" for="cs-set-clock-fallback">${csH("Game clock fallback (+minutes per turn when the model forgets <TIME>)")}</label>
                    <input id="cs-set-clock-fallback" class="text_pole" type="number" min="0" value="${escapeHtml(settings.clockFallbackMinutes)}" style="width:110px;" />
                </div>

                <div class="cs-settings-row">
                    <label class="cs-settings-label" for="cs-set-snapshot-interval">${csH("Auto-snapshot every N chat messages (0 = off)")}</label>
                    <input id="cs-set-snapshot-interval" class="text_pole" type="number" min="0" value="${escapeHtml(settings.snapshotAutoInterval)}" style="width:110px;" />
                </div>

                <div class="cs-settings-row">
                    <label class="cs-settings-label" for="cs-set-audit-cap">${csH("Default audit cap per chat (0 = unlimited)")}</label>
                    <input id="cs-set-audit-cap" class="text_pole" type="number" min="0" value="${escapeHtml(settings.auditCapDefault)}" style="width:110px;" />
                </div>

                <div class="cs-settings-row">
                    <label class="cs-settings-label" for="cs-set-custom-mode">${csH("Default custom display mode for new chats")}</label>
                    <select id="cs-set-custom-mode" class="text_pole cs-log-select" style="width:140px;">
                        <option value="ui" ${settings.customModeDefault !== "full" && settings.customModeDefault !== "compact" ? "selected" : ""}>${csH("UI (default)")}</option>
                        <option value="compact" ${settings.customModeDefault === "compact" ? "selected" : ""}>${csH("Compact")}</option>
                        <option value="full" ${settings.customModeDefault === "full" ? "selected" : ""}>${csH("Full")}</option>
                    </select>
                </div>

                <div class="cs-settings-row">
                    <label class="cs-settings-label" for="cs-set-user-template">${csH("User State Template (optional JSON stats — used as the default schema when creating the {{user}} sheet, across chats)")}</label>
                    <textarea id="cs-set-user-template" class="text_pole" rows="4" style="width:100%;font-family:ui-monospace,monospace;font-size:11px;" placeholder='{"HP":{"type":"number","base":10,"min":0,"max":100}}'>${getUserStateTemplate() ? escapeHtml(JSON.stringify(getUserStateTemplate().stats)) : ""}</textarea>
                    <div class="cs-settings-hint">${csH("Leave empty to keep deriving the user schema from the character/group. Saved globally; never auto-creates a user state.")}</div>
                </div>
            </div>
            <div class="cs-log-footer">
                <button class="cs-chip cs-chip-soft" id="cs-settings-export-btn" type="button">${csIcon("file-export")} ${escapeHtml(csT("Export configuration"))}</button>
                <button class="cs-chip cs-chip-soft" id="cs-settings-import-btn" type="button">${csIcon("file-import")} ${escapeHtml(csT("Import…"))}</button>
                <input id="cs-settings-import-file" type="file" accept="application/json,.json" hidden />
                <button class="cs-chip cs-chip-accent" id="cs-settings-save-btn" type="button">${csIcon("floppy-disk")} ${escapeHtml(csT("Save"))}</button>
                <button class="cs-chip cs-chip-soft" id="cs-settings-close-btn" type="button">${csH("Close")}</button>
            </div>
        </div>
    `;

    document.body.appendChild(overlay);

    const readSettings = () => {
        const heuristic = Boolean(overlay.querySelector("#cs-set-heuristic")?.checked);
        const history = Boolean(overlay.querySelector("#cs-set-history")?.checked);
        const groups = Boolean(overlay.querySelector("#cs-set-groups")?.checked);
        const eventCards = Boolean(overlay.querySelector("#cs-set-event-cards")?.checked);
        const groupLazy = Boolean(overlay.querySelector("#cs-set-group-lazy")?.checked);
        const aiSheetCreate = Boolean(overlay.querySelector("#cs-set-ai-sheet-create")?.checked);

        const clockFallback = Math.max(0, Math.floor(Number(overlay.querySelector("#cs-set-clock-fallback")?.value) || 0));
        const snapshotInterval = Math.max(0, Math.floor(Number(overlay.querySelector("#cs-set-snapshot-interval")?.value) || 0));
        const auditCap = Math.max(0, Math.floor(Number(overlay.querySelector("#cs-set-audit-cap")?.value) || 0));
        const customMode = overlay.querySelector("#cs-set-custom-mode")?.value || "ui";
        const uiLanguage = overlay.querySelector("#cs-set-ui-language")?.value;

        return {
            promptDetail: overlay.querySelector("#cs-set-prompt-detail")?.value === "maximum" ? "maximum" : "standard",
            hudEnabled: Boolean(overlay.querySelector("#cs-set-hud")?.checked),
            uiLanguage: uiLanguage === "en" || uiLanguage === "vi" ? uiLanguage : "auto",
            eventCardsExpanded: Boolean(overlay.querySelector("#cs-set-event-cards-expanded")?.checked),
            eventCardSnapshotRow: Boolean(overlay.querySelector("#cs-set-event-card-snapshot")?.checked),
            heuristicEnabled: heuristic,
            historyEnabled: history,
            groupsEnabled: groups,
            showEventCards: eventCards,
            groupLazyLoading: groupLazy,
            aiSheetCreate,
            clockFallbackMinutes: clockFallback,
            snapshotAutoInterval: snapshotInterval,
            auditCapDefault: auditCap,
            customModeDefault: customMode === "full" || customMode === "compact" ? customMode : null
        };
    };

    /* v3 B2: re-parse here — templateStats used to be block-scoped inside
       readSettings and threw a ReferenceError on every Save with a template. */
    const readTemplateStats = templateRaw => {
        if (!templateRaw) return null;

        try {
            const parsedTemplate = JSON.parse(templateRaw);
            return parsedTemplate?.stats && typeof parsedTemplate.stats === "object" && !Array.isArray(parsedTemplate.stats)
                ? parsedTemplate.stats
                : parsedTemplate;
        } catch {
            return "MALFORMED";
        }
    };

    overlay.querySelector("#cs-settings-save-btn")?.addEventListener("click", () => {
        const saved = saveExtensionSettings(readSettings());

        /* B6: template lives in its own storage (not settings JSON). */
        const templateRaw = String(overlay.querySelector("#cs-set-user-template")?.value || "").trim();
        const templateStats = readTemplateStats(templateRaw);

        if (!templateRaw) {
            clearUserStateTemplate();
        } else if (templateStats === "MALFORMED") {
            csToast.error("User State Template JSON is malformed — the previous template was kept.");
        } else {
            const templateResult = setUserStateTemplate(templateStats);

            if (templateResult.ok) {
                csToast.success("User State Template saved (used as default schema on create).");
            } else {
                csToast.error(templateResult.reason || csT("User State Template was rejected."));
            }
        }

        csToast.success("Character State settings saved.");
        overlay.remove();
        applySettingsToUi();
    });

    overlay.querySelector("#cs-settings-close-btn")?.addEventListener("click", () => overlay.remove());

    overlay.querySelector("#cs-settings-export-btn")?.addEventListener("click", () => {
        const stamp = new Date().toISOString().slice(0, 10);
        downloadTextFile(`character-state-config-${stamp}.json`, JSON.stringify(buildConfigExport(), null, 2));
    });

    const importInput = overlay.querySelector("#cs-settings-import-file");
    overlay.querySelector("#cs-settings-import-btn")?.addEventListener("click", () => importInput?.click());
    importInput?.addEventListener("change", async () => {
        const file = importInput.files?.[0];
        if (!file) return;

        const imported = await importConfigFromText(await file.text());
        importInput.value = "";

        if (imported) {
            overlay.remove();
            /* v3.1.1 U11: language / HUD / card options apply right away */
            applySettingsToUi();
            openSettingsOverlay();
        }
    });

    overlay.addEventListener("click", event => {
        if (event.target === overlay) overlay.remove();
    });
}

/* v3: language / card options apply right away — rebuild the main button
   label, re-render visible cards, refresh an open sheet. Shared by Save and
   (v3.1.1) configuration import. */
function applySettingsToUi() {
    document.getElementById("character-state-button")?.remove();
    document.getElementById("cs-extensions-menu-entry")?.remove();
    createButton();
    refreshCsHud();
    resweepAllEventCardsForced();

    const sheet = document.getElementById("character-state-overlay");
    if (sheet && sheet.dataset.mode === "view") void reopenCharacterSheet(sheet, "view", sheet._character);
}

/* =========================================================
   SNAPSHOTS / RESTORE POINTS
   Save the whole chat state set (all entity states + game clock) as a
   restore point — manual or automatic every N chat messages.
   Restore replaces the current states and resets trigger flags.
========================================================= */

const SNAPSHOT_KEY = "character_state_snapshots";
const SNAPSHOT_MAX = 20;
/* v3 B10: periodic auto snapshots get their own small quota so they can
   never push manual / safety restore points out of the list. */
const SNAPSHOT_AUTO_MAX = 6;
const SNAPSHOT_LAST_AUTO_KEY = "character_state_last_auto_snapshot_len";

function getSnapshots(context) {
    if (!context?.chatMetadata) return null;

    if (!Array.isArray(context.chatMetadata[SNAPSHOT_KEY])) {
        context.chatMetadata[SNAPSHOT_KEY] = [];
    }

    /* v3.1.1 D7: a null / non-object entry (hand-edited or damaged file)
       made every snapshot write throw in the delta encoder. */
    const list = context.chatMetadata[SNAPSHOT_KEY];
    if (list.some(entry => !entry || typeof entry !== "object" || Array.isArray(entry))) {
        const clean = list.filter(entry => entry && typeof entry === "object" && !Array.isArray(entry));
        list.length = 0;
        list.push(...clean);
    }

    return list;
}

/* ---- delta storage (v3.1, invariant #22 exemption agreed with the user) --
   20 full clones of every entity were ~82% of a busy chat's metadata
   (rewritten on EVERY ST chat save). Storage is now a chain: the OLDEST
   entry keeps full `data`, every later entry keeps `data.__delta` = leaf
   ops against the entry before it. Legacy entries (full data everywhere)
   are read as-is and re-packed on the next snapshot write. Arrays and
   scalars are atomic values; paths are key arrays (keys may hold dots). */
const SNAPSHOT_DELTA_VERSION = 1;

function isPlainJsonObject(value) {
    return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function jsonValueEqual(a, b) {
    if (a === b) return true;
    if (a === null || b === null || typeof a !== "object" || typeof b !== "object") return false;
    return JSON.stringify(a) === JSON.stringify(b);
}

/* Deletes keep relative order and sets APPEND, so a diff can only rebuild
   key order "previous minus deleted, then new keys". Any other order change
   stores the container whole — key order is visible (sheet, prompt). */
function keyOrderRebuildable(previous, next) {
    const nextKeys = Object.keys(next);
    const kept = Object.keys(previous).filter(key => Object.prototype.hasOwnProperty.call(next, key));

    for (let index = 0; index < kept.length; index++) {
        if (nextKeys[index] !== kept[index]) return false;
    }

    return true;
}

function diffJsonTree(previous, next, path = [], ops = { set: [], del: [] }) {
    if (path.length && !keyOrderRebuildable(previous, next)) {
        ops.set.push([path, next]);
        return ops;
    }

    for (const key of Object.keys(previous)) {
        if (!Object.prototype.hasOwnProperty.call(next, key)) ops.del.push([...path, key]);
    }

    for (const [key, value] of Object.entries(next)) {
        const childPath = [...path, key];

        if (!Object.prototype.hasOwnProperty.call(previous, key)) {
            ops.set.push([childPath, value]);
        } else if (isPlainJsonObject(previous[key]) && isPlainJsonObject(value)) {
            diffJsonTree(previous[key], value, childPath, ops);
        } else if (!jsonValueEqual(previous[key], value)) {
            ops.set.push([childPath, value]);
        }
    }

    return ops;
}

/* v3.1.1 K9: keys like "constructor" / "prototype" / "__proto__" are
   ordinary data in user custom JSON. Read only OWN properties and write
   with defineProperty: exact round trip, and no prototype is ever touched
   (the old skip-list dropped those keys from every delta). */
function ownTreeChild(node, key) {
    return Object.prototype.hasOwnProperty.call(node, key) ? node[key] : undefined;
}

function setOwnTreeChild(node, key, value) {
    Object.defineProperty(node, key, { value, writable: true, enumerable: true, configurable: true });
}

function applyJsonTreeOps(base, ops, { inPlace = false } = {}) {
    const result = inPlace ? base : structuredClone(base);

    for (const path of ops?.del || []) {
        let node = result;
        for (let index = 0; index < path.length - 1 && isPlainJsonObject(node); index++) node = ownTreeChild(node, path[index]);
        if (isPlainJsonObject(node)) delete node[path[path.length - 1]];
    }

    for (const [path, value] of ops?.set || []) {
        let node = result;

        for (let index = 0; index < path.length - 1; index++) {
            if (!isPlainJsonObject(ownTreeChild(node, path[index]))) setOwnTreeChild(node, path[index], {});
            node = node[path[index]];
        }

        setOwnTreeChild(node, path[path.length - 1], structuredClone(value));
    }

    return result;
}

/* Walk the chain ONCE with a single working copy (deltas applied in place)
   and clone the full data only for the requested entry ids. */
/* Delta ops of an entry: v3.1 stores them in `entry.delta` (data absent);
   early v3.1 dev builds used `data.__delta`. */
function snapshotDeltaOf(entry) {
    if (entry?.delta && typeof entry.delta === "object") return entry.delta;
    if (entry?.data && typeof entry.data === "object" && entry.data.__delta) return entry.data.__delta;
    return null;
}

function snapshotFullOf(entry) {
    const data = entry?.data;
    return data && typeof data === "object" && !data.__delta && !entry.delta ? data : null;
}

function materializeSnapshotsById(snapshots, wantedIds) {
    const result = new Map();
    let current = null;

    for (const entry of snapshots) {
        const full = snapshotFullOf(entry);
        const delta = snapshotDeltaOf(entry);

        if (full) {
            current = structuredClone(full);
        } else if (delta && current) {
            applyJsonTreeOps(current, delta, { inPlace: true });
        } else {
            /* v3.1 review R1: a delta with no full entry before it (chain
               head spliced off, e.g. by an older build) cannot be rebuilt —
               never restore a guessed / empty world. */
            current = null;
        }

        if (current && wantedIds.has(entry?.id)) result.set(entry.id, structuredClone(current));
    }

    return result;
}

/* Every entry's full data (tests / tools). */
function materializeSnapshotData(snapshots) {
    const byId = materializeSnapshotsById(snapshots, new Set(snapshots.map(entry => entry?.id)));
    return snapshots.map(entry => byId.get(entry?.id));
}

/* Re-encode only what changed: the head must be full; every other entry is
   a delta against the entry right before it (`base` = that entry's id). An
   entry whose predecessor changed (prune / delete / new / legacy full) is
   re-encoded from `fulls` (Map id → full data of the ORIGINAL chain). */
function snapshotNeedsEncoding(snapshots, index) {
    const entry = snapshots[index];
    const isDelta = Boolean(snapshotDeltaOf(entry));
    if (index === 0) return isDelta || Boolean(entry?.data?.__delta);
    return !isDelta || !entry.delta || entry.base !== snapshots[index - 1]?.id;
}

function snapshotIdsNeededForEncoding(snapshots) {
    const wanted = new Set();

    snapshots.forEach((entry, index) => {
        if (!snapshotNeedsEncoding(snapshots, index)) return;
        wanted.add(entry.id);
        if (index > 0) wanted.add(snapshots[index - 1].id);
    });

    return wanted;
}

function encodeSnapshots(snapshots, fulls) {
    snapshots.forEach((entry, index) => {
        if (!snapshotNeedsEncoding(snapshots, index)) return;

        const full = fulls.get(entry.id);
        if (!full) return;

        /* R10: keep the entity count once data stops being full */
        if (!Number.isFinite(entry.entityCount)) {
            entry.entityCount = Object.keys(full.states || {}).length;
        }

        const storeFull = () => {
            entry.data = full;
            delete entry.delta;
            delete entry.base;
            delete entry.v;
        };

        if (index === 0) {
            storeFull();
            return;
        }

        const previous = fulls.get(snapshots[index - 1].id);
        if (!previous) return;

        const ops = diffJsonTree(previous, full);

        if (JSON.stringify(ops).length < JSON.stringify(full).length) {
            entry.delta = ops;
            entry.base = snapshots[index - 1].id;
            entry.v = SNAPSHOT_DELTA_VERSION;
            delete entry.data;
        } else {
            storeFull();
        }
    });
}

function getSnapshotFullData(context, snapshotId) {
    const snapshots = getSnapshots(context) || [];
    const index = snapshots.findIndex(item => item?.id === snapshotId);
    if (index < 0) return null;
    return materializeSnapshotsById(snapshots.slice(0, index + 1), new Set([snapshotId])).get(snapshotId) || null;
}

/* Remove one entry, keeping every other entry restorable. */
function deleteSnapshotById(context, snapshotId) {
    const snapshots = getSnapshots(context);
    if (!snapshots) return false;

    const index = snapshots.findIndex(item => item?.id === snapshotId);
    if (index < 0) return false;

    const after = snapshots.filter(item => item?.id !== snapshotId);
    const fulls = materializeSnapshotsById(snapshots, snapshotIdsNeededForEncoding(after));

    snapshots.splice(index, 1);
    encodeSnapshots(snapshots, fulls);
    return true;
}

function takeStateSnapshot(context, source = "manual") {
    const snapshots = getSnapshots(context);
    if (!snapshots) return { ok: false };

    const states = context.chatMetadata.character_states;

    const data = {
        states: states && typeof states === "object" && !Array.isArray(states)
            ? JSON.parse(JSON.stringify(states))
            : {},
        gameTime: getGameTime(context),
        activeScene: typeof context.chatMetadata[SCENE_ACTIVE_KEY] === "string"
            ? context.chatMetadata[SCENE_ACTIVE_KEY]
            : null
    };

    const entityCount = Object.keys(data.states).length;
    const statCount = Object.values(data.states)
        .filter(state => state && typeof state === "object")
        .reduce((total, state) => total + Object.keys(state.stats || {}).length, 0);

    /* v3.1: delta storage — append, prune, then re-encode only the entries
       whose predecessor changed (full data read from the ORIGINAL chain). */
    const original = snapshots.slice();
    const entry = {
        id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        ts: Date.now(),
        source,
        summary: `${entityCount} entit${entityCount === 1 ? "y" : "ies"} · ${statCount} stats`,
        entityCount,
        /* v3.1.2 F9: chat length at capture — a branch can find the
           snapshot that matches where it starts */
        atLength: Array.isArray(context.chat) ? context.chat.length : null,
        data
    };

    snapshots.push(entry);
    pruneSnapshots(snapshots);

    const wanted = snapshotIdsNeededForEncoding(snapshots);
    wanted.delete(entry.id);
    const fulls = materializeSnapshotsById(original, wanted);
    fulls.set(entry.id, data);
    encodeSnapshots(snapshots, fulls);

    const created = snapshots[snapshots.length - 1];

    stateEventBus.emit("snapshot.created", {
        event: "snapshot.created",
        entity: null,
        timestamp: created.ts,
        result: { id: created.id, summary: created.summary, source },
        source
    });

    return { ok: true, summary: created.summary };
}

function pruneSnapshots(snapshots) {
    /* Periodic "auto" snapshots (exact source) first: keep the newest
       SNAPSHOT_AUTO_MAX. Then the overall cap, oldest first. */
    const periodic = snapshots.filter(item => item?.source === "auto");

    if (periodic.length > SNAPSHOT_AUTO_MAX) {
        const drop = new Set(periodic.slice(0, periodic.length - SNAPSHOT_AUTO_MAX));
        for (let index = snapshots.length - 1; index >= 0; index--) {
            if (drop.has(snapshots[index])) snapshots.splice(index, 1);
        }
    }

    if (snapshots.length > SNAPSHOT_MAX) {
        snapshots.splice(0, snapshots.length - SNAPSHOT_MAX);
    }
}

/* test-only handles (pure functions + the snapshot store operations) */
globalThis.__csSnapshotsForTests = {
    takeStateSnapshot: (...args) => takeStateSnapshot(...args),
    restoreStateSnapshot: (...args) => restoreStateSnapshot(...args),
    deleteSnapshotById: (...args) => deleteSnapshotById(...args),
    getSnapshotFullData: (...args) => getSnapshotFullData(...args),
    recordStatHistory: (...args) => recordStatHistory(...args),
    getStatHistory: (...args) => getStatHistory(...args)
};

function maybeAutoSnapshot(context) {
    const interval = Number(getExtensionSettings().snapshotAutoInterval);
    if (!(interval > 0) || !context?.chatMetadata) return false;

    /* v3 B10: "every N messages" measured as distance from the last auto
       snapshot — the old `length % N` never fired when AI replies always
       land on odd lengths (greeting + pairs), and re-fired on every
       swipe/continue of the matching message. */
    const length = Number(context.chat?.length ?? 0);
    const last = Number(context.chatMetadata[SNAPSHOT_LAST_AUTO_KEY]);

    if (!Number.isFinite(last) || last > length) {
        context.chatMetadata[SNAPSHOT_LAST_AUTO_KEY] = length;
        return false;
    }

    if (length - last < interval) return false;

    context.chatMetadata[SNAPSHOT_LAST_AUTO_KEY] = length;
    return takeStateSnapshot(context, "auto").ok;
}

async function restoreStateSnapshot(context, snapshotId, fallbackSnapshot = null) {
    const snapshots = getSnapshots(context);
    if (!snapshots) return false;

    const listed = snapshots.find(item => item?.id === snapshotId);
    const listedData = listed ? getSnapshotFullData(context, snapshotId) : null;
    const snapshot = listedData
        ? { ...listed, data: listedData }
        : !listed && fallbackSnapshot && snapshotFullOf(fallbackSnapshot) ? fallbackSnapshot : null;
    if (!snapshot || !snapshot.data) return false;

    context.chatMetadata.character_states = structuredClone(snapshot.data.states || {});

    if (snapshot.data.gameTime) {
        context.chatMetadata[GAME_TIME_KEY] = structuredClone(snapshot.data.gameTime);
    } else {
        delete context.chatMetadata[GAME_TIME_KEY];
    }

    /* Trigger edge-flags describe transitions before the restore point. */
    delete context.chatMetadata[TRIGGER_FLAGS_KEY];

    /* v3 B12: the active-scene pointer travels with the states (older
       snapshots have no field — leave the pointer alone then). */
    if (snapshot.data.activeScene !== undefined) {
        if (snapshot.data.activeScene) {
            context.chatMetadata[SCENE_ACTIVE_KEY] = snapshot.data.activeScene;
        } else {
            delete context.chatMetadata[SCENE_ACTIVE_KEY];
        }
    }

    /* v3 B12: journals / swipe snapshots / the APPLIED buffer describe the
       pre-restore world — replaying them would undo the restore. */
    clearTurnScopedMemory();
    delete context.chatMetadata[LAST_TURN_KEY];

    const entityKeys = Object.keys(context.chatMetadata.character_states);

    for (const entityKey of entityKeys) {
        pushAuditEntry(context, {
            k: entityKey,
            src: "manual",
            sec: "snapshot",
            f: entityKey === USER_STATE_KEY ? USER_STATE_UI_NAME : auditEntityDisplayName(entityKey),
            op: "restore"
        });
    }

    stateEventBus.emit("snapshot.restored", {
        event: "snapshot.restored",
        entity: null,
        timestamp: Date.now(),
        result: { id: snapshot.id, summary: snapshot.summary, entities: entityKeys.length },
        source: "manual"
    });

    await saveChatState(context);
    refreshCsHud();
    return true;
}

/* =========================================================
   UNIFIED TIMELINE (A4 — presentation-layer VIEW ONLY)
   Merges the EXISTING event sources — audit entries + snapshots —
   into one chronological feed. No new storage format: this is a
   projection over existing data, so nothing can lose compatibility.
   Rows are expandable: click shows everything the underlying record
   carries (entity, source, section, before/after, count, raw JSON).
========================================================= */

const TIMELINE_LIMIT_DEFAULT = 200;

function buildUnifiedTimeline(context, limit = TIMELINE_LIMIT_DEFAULT) {
    context ||= SillyTavern.getContext();

    const rows = [];

    const audit = Array.isArray(context.chatMetadata?.[AUDIT_STORAGE_KEY])
        ? context.chatMetadata[AUDIT_STORAGE_KEY]
        : [];

    for (const entry of audit) {
        if (!entry || typeof entry !== "object") continue;

        rows.push({
            kind: "audit",
            t: entry.t,
            entity: describeEntity(context, entry.k) || { key: String(entry.k || ""), type: getEntityTypeFromKey(entry.k), name: auditEntityDisplayName(entry.k) },
            source: entry.src || "system",
            section: entry.sec || "state",
            field: String(entry.f ?? ""),
            op: entry.op || "set",
            before: entry.b,
            after: entry.a,
            count: entry.c || 1,
            label: `${auditEntityDisplayName(entry.k)}: ${auditOpLabel(entry.op)}${entry.f ? ` ${entry.f}` : ""}${(entry.c || 1) > 1 ? ` ×${entry.c}` : ""}`
        });
    }

    const snapshots = Array.isArray(context.chatMetadata?.[SNAPSHOT_KEY])
        ? context.chatMetadata[SNAPSHOT_KEY]
        : [];

    for (const snapshot of snapshots) {
        if (!snapshot || typeof snapshot !== "object") continue;

        rows.push({
            kind: "snapshot",
            t: snapshot.ts,
            id: snapshot.id,
            source: snapshot.source || "manual",
            summary: snapshot.summary,
            entityCount: Number.isFinite(snapshot.entityCount)
                ? snapshot.entityCount
                : snapshotFullOf(snapshot)
                    ? Object.keys(snapshot.data.states || {}).length
                    : Number(String(snapshot.summary || "").match(/^(\d+) entit/)?.[1] || 0),
            label: `Snapshot — ${snapshot.summary} (${snapshot.source || "manual"})`
        });
    }

    rows.sort((a, b) => (b.t || 0) - (a.t || 0));

    return Number.isInteger(limit) && limit > 0 ? rows.slice(0, limit) : rows;
}

function renderTimelineDetailGrid(pairs) {
    const rows = pairs
        .filter(([, value]) => value !== undefined && value !== null && value !== "")
        .map(([label, value]) => `<dt>${escapeHtml(label)}</dt><dd>${escapeHtml(typeof value === "object" ? customLeafText(value, 400) : String(value))}</dd>`)
        .join("");
    return `<dl class="cs-detail-grid">${rows}</dl>`;
}

function openTimelineOverlay() {
    document.getElementById("cs-timeline-overlay")?.remove();

    const context = SillyTavern.getContext();
    const overlay = document.createElement("div");
    overlay.id = "cs-timeline-overlay";
    overlay.className = "cs-log-overlay";

    const formatTime = t => {
        const date = new Date(Number(t) || 0);

        return Number.isFinite(date.getTime()) && date.getTime() > 0
            ? date.toLocaleString()
            : "—";
    };

    /* buildUnifiedTimeline is also public API (English labels) — the
       overlay rebuilds the label in the UI language. */
    const displayLabel = row => row.kind === "snapshot"
        ? csT("Snapshot — {summary} ({source})", { summary: row.summary, source: row.source })
        : `${auditEntityDisplayName(row.entity?.key)}: ${auditOpLabelUi(row.op)}${row.field ? ` ${row.field}` : ""}${(row.count || 1) > 1 ? ` ×${row.count}` : ""}`;

    const renderRows = filterText => {
        const body = overlay.querySelector("#cs-timeline-body");
        if (!body) return;

        const needle = String(filterText || "").toLowerCase().trim();
        const rows = buildUnifiedTimeline(context, 400).filter(row =>
            !needle ||
            row.label.toLowerCase().includes(needle) ||
            displayLabel(row).toLowerCase().includes(needle) ||
            (row.entity?.name || "").toLowerCase().includes(needle) ||
            row.source.toLowerCase().includes(needle)
        );

        if (!rows.length) {
            body.innerHTML = `<div class="cs-log-empty">${csH("Timeline is empty — no changes recorded yet.")}</div>`;
            return;
        }

        body.innerHTML = rows.map(row => `
            <div class="cs-timeline-row cs-log-row" data-kind="${row.kind}" data-i="${rows.indexOf(row)}">
                <span class="cs-log-time">${escapeHtml(formatTime(row.t))}</span>
                <span class="cs-log-kind">${row.kind === "snapshot" ? "📸" : "•"}</span>
                <span class="cs-log-label">${renderRichText(displayLabel(row))}</span>
                <span class="cs-log-src">[${escapeHtml(row.source)}]</span>
                <div class="cs-timeline-detail" hidden>
                    ${renderTimelineDetailGrid(row.kind === "snapshot" ? [
                        [csT("Source"), row.source],
                        [csT("Summary"), row.summary],
                        [csT("Entities"), row.entityCount]
                    ] : [
                        [csT("Entity"), row.entity?.name || row.entity?.key || row.entity],
                        [csT("Source"), row.source],
                        [csT("Section"), row.section],
                        [csT("Field"), row.field],
                        [csT("Action"), row.op],
                        [csT("Before"), row.before],
                        [csT("After"), row.after],
                        [csT("Count"), row.count]
                    ])}
                </div>
            </div>
        `).join("");

        for (const rowEl of body.querySelectorAll(".cs-timeline-row")) {
            rowEl.addEventListener("click", () => {
                const detail = rowEl.querySelector(".cs-timeline-detail");
                if (detail) detail.hidden = !detail.hidden;
            });
        }
    };

    overlay.innerHTML = `
        <div class="cs-log-window" style="width:min(860px,96vw);height:min(72vh,720px);">
            <div class="cs-log-header">
                <div class="cs-log-title">${csIcon("timeline")} ${escapeHtml(csT("Unified Timeline"))}</div>
                <div class="cs-log-subtitle">${csH("Chronological view over the audit log + snapshots (projection — no new data)")}</div>
            </div>
            <div class="cs-log-toolbar">
                <input id="cs-timeline-filter" class="text_pole" type="text" placeholder="${csH("Filter by entity, action or source…")}" style="flex:1;" />
            </div>
            <div class="cs-log-body" id="cs-timeline-body"></div>
            <div class="cs-log-footer">
                <button class="cs-chip cs-chip-soft" id="cs-timeline-close-btn" type="button">${csH("Close")}</button>
            </div>
        </div>
    `;

    document.body.appendChild(overlay);
    renderRows("");

    overlay.querySelector("#cs-timeline-filter")?.addEventListener("input", event => {
        renderRows(event.target.value);
    });

    overlay.querySelector("#cs-timeline-close-btn")?.addEventListener("click", () => overlay.remove());
    overlay.addEventListener("click", event => {
        if (event.target === overlay) overlay.remove();
    });
}

/* =========================================================
   WORLD STATE OVERVIEW (C1 — structural projection ONLY)
   Groups every entity (by A1 type) with its data shape: counts only,
   no interpretation, no semantics per world kind. This is the top of
   the Character → Entity → Scene → World ladder: everything below is
   already regular runtime state handled by the same engine.
========================================================= */

const WORLD_MAX_ROWS = 200;

function buildWorldStateOverview(context) {
    context ||= SillyTavern.getContext();

    const entities = listEntities(context);
    const states = context.chatMetadata?.character_states || {};
    const groups = { character: [], side_npc: [], scene: [], user: [], unknown: [] };

    for (const entity of entities) {
        const state = states[entity.key] || null;

        const info = {
            key: entity.key,
            type: entity.type,
            name: entity.name,
            status: entity.status,
            hasState: entity.hasState,
            stats: state?.stats && typeof state.stats === "object" ? Object.keys(state.stats).length : 0,
            skills: Array.isArray(state?.skills) ? state.skills.length : 0,
            items: Array.isArray(state?.inventory) ? state.inventory.length : 0,
            effects: Array.isArray(state?.effects) ? state.effects.length : 0,
            customTopLevel: state?.custom && typeof state.custom === "object" ? Object.keys(state.custom).length : 0
        };

        (groups[entity.type] || groups.unknown).push(info);
    }

    for (const key of Object.keys(groups)) {
        if (groups[key].length > WORLD_MAX_ROWS) groups[key].length = WORLD_MAX_ROWS;
    }

    return {
        generatedAt: Date.now(),
        totalEntities: entities.length,
        activeScene: getActiveSceneKey(context),
        relationshipCount: getRelationships(context).length,
        gameTime: getGameTime(context),
        groups
    };
}

/* first three number stats: "HP 87/100 · Mood 62" */
function worldStatPreview(context, entityKey) {
    const state = context?.chatMetadata?.character_states?.[entityKey];
    if (!state?.stats) return "";

    return Object.entries(state.stats)
        .filter(([, stat]) => stat?.type === "number")
        .slice(0, 3)
        .map(([name, stat]) => {
            const value = formatPlainValue(Number(getEffectiveStatValue(state, stat)));
            const max = Number(stat.max);
            return `${escapeHtml(applyCsMacros(name))} <b>${escapeHtml(value)}</b>${Number.isFinite(max) && max > 0 ? `<small>/${escapeHtml(formatPlainValue(max))}</small>` : ""}`;
        })
        .join(" · ");
}

function openWorldOverviewOverlay() {
    document.getElementById("cs-world-overlay")?.remove();

    const context = SillyTavern.getContext();
    const overlay = document.createElement("div");
    overlay.id = "cs-world-overlay";
    overlay.className = "cs-log-overlay";

    const overview = buildWorldStateOverview(context);

    const groupSection = (title, rows) => {
        if (!rows.length) return "";

        const rowsHtml = rows.map(entity => {
            const preview = worldStatPreview(context, entity.key);
            const isScene = entity.type === "scene";
            const isActiveScene = isScene && entity.key === overview.activeScene;

            return `
            <div class="cs-world-row${isActiveScene ? " cs-world-row-active" : ""}">
                <button class="cs-world-open" type="button" data-cs-world-key="${escapeHtml(entity.key)}" title="${escapeHtml(csT("Open sheet"))}">
                    <span class="cs-world-name">${isActiveScene ? `${csIcon("location-dot")} ` : ""}${renderRichText(entity.name)}</span>
                    <span class="cs-world-meta">${entity.status && entity.status !== "active" ? `<span class="cs-effect-tag">${escapeHtml(entity.status)}</span> ` : ""}${csH("{stats} stats · {skills} skills · {items} items · {effects} effects", { stats: entity.stats, skills: entity.skills, items: entity.items, effects: entity.effects })}</span>
                    ${preview ? `<span class="cs-world-preview">${preview}</span>` : ""}
                </button>
                ${isScene && !isActiveScene ? `<button class="cs-chip cs-chip-soft" type="button" data-cs-world-activate="${escapeHtml(entity.key)}">${escapeHtml(csT("Set active"))}</button>` : ""}
            </div>`;
        }).join("");

        return `
            <div class="cs-world-group">
                <div class="cs-world-group-title">${escapeHtml(title)} (${rows.length})</div>
                ${rowsHtml}
            </div>
        `;
    };

    const sceneRows = overview.groups.scene.map(entity => ({
        ...entity,
        name: entity.key === overview.activeScene ? `📍 ${entity.name}` : entity.name
    }));

    overlay.innerHTML = `
        <div class="cs-log-window" style="width:min(720px,96vw);height:min(72vh,720px);">
            <div class="cs-log-header">
                <div class="cs-log-title">${csIcon("earth-asia")} ${escapeHtml(csT("World State"))}</div>
                <div class="cs-log-subtitle">${csH("{entities} entities · {relations} relationships · active scene: {scene}", { entities: overview.totalEntities, relations: overview.relationshipCount, scene: overview.activeScene ? applyCsMacros(overview.activeScene) : csT("none") })}</div>
            </div>
            <div class="cs-log-body" style="padding:10px 0;">
                ${groupSection(csT("Scenes"), sceneRows)}
                ${groupSection(csT("Character Cards"), overview.groups.character)}
                ${groupSection(csT("Side NPCs"), overview.groups.side_npc)}
                ${groupSection(csT("User"), overview.groups.user)}
                ${groupSection(csT("Other entities"), overview.groups.unknown)}
            </div>
            <div class="cs-log-footer">
                <button class="cs-chip cs-chip-soft" id="cs-world-close-btn" type="button">${csH("Close")}</button>
            </div>
        </div>
    `;

    document.body.appendChild(overlay);

    overlay.querySelector("#cs-world-close-btn")?.addEventListener("click", () => overlay.remove());
    overlay.addEventListener("click", async event => {
        if (event.target === overlay) {
            overlay.remove();
            return;
        }

        const activate = event.target.closest?.("[data-cs-world-activate]");
        if (activate) {
            const result = setActiveScene(context, activate.dataset.csWorldActivate);
            if (!result.ok) {
                csToast.error(result.reason);
                return;
            }
            await saveChatState(context);
            openWorldOverviewOverlay();
            return;
        }

        const open = event.target.closest?.("[data-cs-world-key]");
        if (open) {
            const target = resolveSheetCharacterByKey(open.dataset.csWorldKey);
            if (!target) {
                csToast.info(csT("This entity has no sheet in this chat."));
                return;
            }
            overlay.remove();
            await openCharacterSheet("view", target);
        }
    });
}

function openSnapshotManager(character) {
    const context = SillyTavern.getContext();

    document.getElementById("cs-snapshots-overlay")?.remove();

    const overlay = document.createElement("div");
    overlay.id = "cs-snapshots-overlay";
    overlay.className = "cs-log-overlay";

    const renderList = () => {
        const snapshots = getSnapshots(context) || [];
        const body = overlay.querySelector("#cs-snapshots-body");

        if (!body) return;

        if (!snapshots.length) {
            body.innerHTML = `<div class="cs-log-empty">${escapeHtml(csT("No snapshots yet. Use History ▸ Take snapshot now to save a restore point."))}</div>`;
            return;
        }

        body.innerHTML = snapshots
            .slice()
            .reverse()
            .map(snapshot => `
                <div class="cs-log-row cs-snapshot-row">
                    <span class="cs-log-time">${escapeHtml(formatAuditTime(snapshot.ts))}</span>
                    <span class="cs-log-main"><b>${csH(String(snapshot.source || "manual"))}</b> · ${escapeHtml(snapshot.summary || "")}</span>
                    <button class="cs-chip" type="button" data-cs-snapshot-restore="${escapeHtml(snapshot.id)}">${csIcon("clock-rotate-left")} ${escapeHtml(csT("Restore"))}</button>
                    <button class="cs-chip cs-chip-soft cs-chip-icon" type="button" data-cs-snapshot-delete="${escapeHtml(snapshot.id)}" title="${escapeHtml(csT("Delete"))}" aria-label="${escapeHtml(csT("Delete"))}">${csIcon("trash")}</button>
                </div>
            `)
            .join("");
    };

    overlay.innerHTML = `
        <div class="cs-log-window" style="width:min(600px,94vw);">
            <div class="cs-log-header">
                <div class="cs-log-title">${csIcon("clock-rotate-left")} ${escapeHtml(csT("Snapshots / Restore points"))}</div>
                <div class="cs-log-subtitle">${escapeHtml(csT("This chat only · up to {n} kept", { n: SNAPSHOT_MAX }))}</div>
            </div>
            <div class="cs-log-body" id="cs-snapshots-body"></div>
            <div class="cs-log-footer">
                <button class="cs-chip cs-chip-accent" id="cs-snapshots-take-btn" type="button">📸 ${escapeHtml(csT("Snapshot now"))}</button>
                <button class="cs-chip cs-chip-soft" id="cs-snapshots-close-btn" type="button">${csH("Close")}</button>
            </div>
        </div>
    `;

    document.body.appendChild(overlay);
    renderList();

    overlay.querySelector("#cs-snapshots-close-btn")?.addEventListener("click", () => overlay.remove());

    overlay.querySelector("#cs-snapshots-take-btn")?.addEventListener("click", async () => {
        const result = takeStateSnapshot(context, "manual");

        if (result.ok) {
            await saveChatState(context);
            csToast.success(csT("Snapshot saved ({summary}).", { summary: result.summary }));
            renderList();
        } else {
            csToast.error("Could not save a snapshot (no active chat).");
        }
    });

    overlay.querySelector("#cs-snapshots-body")?.addEventListener("click", async event => {
        const deleteButton = event.target.closest?.("[data-cs-snapshot-delete]");

        if (deleteButton) {
            const snapshotId = deleteButton.dataset.csSnapshotDelete || "";

            if (!await csConfirm("Delete this snapshot?", { okLabel: csT("Delete"), danger: true })) return;

            /* re-resolve: an AI turn may have pruned / shifted the list
               while the dialog was open; v3.1 deltas re-pack around it */
            if (!deleteSnapshotById(context, snapshotId)) return;
            await saveChatState(context);
            renderList();
            return;
        }

        const button = event.target.closest?.("[data-cs-snapshot-restore]");
        if (!button) return;

        const snapshotId = button.dataset.csSnapshotRestore || "";

        if (!await csConfirm(csT(
            "Restore this snapshot?\n\nALL current chat states will be replaced by the saved point. The current state is saved as a new \"before restore\" snapshot first, so this can be undone."
        ))) return;

        /* v3: restore is undoable — snapshot the present first. The target is
           cloned BEFORE that: a full list prunes its oldest entry, which may
           be the very snapshot being restored. */
        const target = (getSnapshots(context) || []).find(item => item?.id === snapshotId);
        const targetData = target ? getSnapshotFullData(context, snapshotId) : null;
        const targetCopy = target && targetData ? { ...structuredClone(target), data: targetData } : null;

        takeSafetySnapshot(context, "before restore");

        const ok = await restoreStateSnapshot(context, snapshotId, targetCopy);

        if (ok) {
            csToast.success("Snapshot restored.");
            overlay.remove();
            updateCharacterSheet(character);
        } else {
            csToast.error("Could not restore the snapshot.");
        }
    });

    overlay.addEventListener("click", event => {
        if (event.target === overlay) overlay.remove();
    });
}

/* =========================================================
   TOOL CALLING (DUAL-PATH)
   When the current model/connector supports native tool calling, the
   "UpdateCharacterState" tool handles STATE_UPDATE through the official
   ST tool pipeline (strict JSON, no text parsing). When it does not,
   the tool stays unregistered and the classic <STATE_UPDATE> text
   protocol keeps working — the model never sees duplicate instructions
   because the text schema is omitted while tools are active.
========================================================= */

/*
 * SEMANTIC TOOL REQUEST NORMALIZER (S2)
 * The tool layer translates semantic requests into the CANONICAL patch
 * shape — the same one the text protocol uses — so the Core State
 * Engine (computeStatePatch) stays the single update implementation.
 * Flow: Tool → normalize → canonical patch → Core State Engine.
 * Canonical stat keys: plain (default delta), _base (absolute set),
 * _max/_min (limit deltas). base/max/min/set stay gated by aiBaseEdit
 * inside the core — the tool layer adds no extra authority.
 * Semantic keys per stat object:
 *   change → plain key (default delta target)
 *   mod    → plain key (canonical alias of the default delta)
 *   base   → NAME_base (absolute set)
 *   set    → NAME_base (absolute set)
 *   max    → NAME_max (limit delta)
 *   min    → NAME_min (limit delta)
 * Returns { update, errors } with machine-readable error codes.
 */
/* v3.1.3: the fields of a semantic request that carry a change */
const SEMANTIC_CHANGE_FIELDS = ["stats", "custom", "effects", "skills", "inventory"];

function normalizeSemanticToolRequest(params) {
    const update = {};
    const errors = [];

    /* v3.1.3: "json" carries the whole request as ONE string. Some
       providers' tool decoding (seen: OpenRouter → InferenceNet) drops the
       free-form object fields and sends only {"character"} — a string
       always arrives. Non-empty object fields sent alongside win. */
    if (typeof params?.json === "string" && params.json.trim()) {
        let parsed = null;

        try {
            parsed = JSON.parse(params.json);
        } catch {
            errors.push("INVALID_JSON: \"json\" must be a JSON object string like {\"stats\":{\"HP\":-5}}.");
        }

        if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
            const merged = { ...parsed };
            for (const [field, value] of Object.entries(params)) {
                if (field === "json") continue;
                const emptyObject = value && typeof value === "object" && !Object.keys(value).length;
                if (!(emptyObject && parsed[field] !== undefined)) merged[field] = value;
            }
            params = merged;
        } else if (parsed !== null) {
            errors.push("INVALID_JSON: \"json\" must be a JSON object string like {\"stats\":{\"HP\":-5}}.");
        }
    }

    if (params?.stats !== undefined) {
        if (!params.stats || typeof params.stats !== "object" || Array.isArray(params.stats)) {
            errors.push("INVALID_STATS: stats must be a JSON object.");
        } else {
            const stats = {};
            const semanticKeys = new Set(["change", "mod", "base", "min", "max", "set"]);

            for (const [rawName, value] of Object.entries(params.stats)) {
                const name = String(rawName).trim();

                if (!name) {
                    errors.push("INVALID_STAT_KEY: empty stat key.");
                    continue;
                }

                if (value === null || typeof value !== "object") {
                    /* Shorthand: numeric delta / non-number set value. */
                    stats[name] = value;
                    continue;
                }

                const keys = Object.keys(value).filter(key => semanticKeys.has(key));

                if (!keys.length) {
                    errors.push(
                        `INVALID_SEMANTIC_STAT: "${name}" has no recognized semantic key (change|mod|base|min|max|set).`
                    );
                    continue;
                }

                for (const key of keys) {
                    if (key === "change" || key === "mod") {
                        stats[name] = value[key];
                    } else if (key === "base" || key === "set") {
                        stats[`${name}_base`] = value[key];
                    } else if (key === "max") {
                        stats[`${name}_max`] = value[key];
                    } else if (key === "min") {
                        stats[`${name}_min`] = value[key];
                    }
                }
            }

            if (Object.keys(stats).length) update.stats = stats;
        }
    }

    if (params?.custom !== undefined) {
        if (params.custom && typeof params.custom === "object" && !Array.isArray(params.custom)) {
            update.custom = params.custom;
        } else {
            errors.push("INVALID_CUSTOM: custom must be a JSON object.");
        }
    }

    if (params?.effects !== undefined) {
        if (params.effects && typeof params.effects === "object" && !Array.isArray(params.effects)) {
            update.effects = params.effects;
        } else {
            errors.push("INVALID_EFFECT: effects must be an object with add/remove/clear.");
        }
    }

    if (params?.skills !== undefined) update.skills = params.skills;
    if (params?.inventory !== undefined) update.inventory = params.inventory;

    return { update, errors };
}

/* Optional suffix for tool responses: surfaces core feedback/warning codes
   so the model can self-correct next turn (B5 seed). */
function describeToolResult(result) {
    const parts = [];

    if (result?.feedback?.length) parts.push(`FEEDBACK: ${result.feedback.join(" ")}`);
    if (result?.warnings?.length) parts.push(`WARNINGS: ${result.warnings.join(",")}`);

    return parts.length ? ` ${parts.join(" ")}` : "";
}

/* Anti-echo support: the tool response states the RESULTING values so the
   model can verify its intent immediately — a drifted value ("Age is now
   40") becomes visible in the same turn instead of the next sheet read. */
function buildToolResultEcho(result) {
    if (!result?.diff?.length) return "";

    const parts = [];

    for (const entry of result.diff) {
        if (entry.section === "stats") {
            if (entry.kind === "eff") {
                parts.push(`${entry.field} is now ${formatPlainValue(entry.after)}`);
            } else if (entry.kind === "base") {
                parts.push(`${entry.field} base is now ${formatPlainValue(entry.after)}`);
            } else {
                parts.push(`${entry.field} is now ${entry.after}`);
            }
        } else if (entry.section === "skills") {
            parts.push(`skill ${entry.op === "add" ? "+" : "−"}${entry.field}`);
        } else if (entry.section === "inventory") {
            if (entry.op === "add") {
                parts.push(`item +${entry.field} x${entry.after}`);
            } else if (entry.op === "remove") {
                parts.push(`item −${entry.field}`);
            } else {
                parts.push(`item ${entry.field} x${entry.before} → x${entry.after}`);
            }
        }
    }

    return parts.length ? ` (${parts.join("; ")})` : "";
}

/* Lean read serialization (v2.0.10): the raw pretty-print of a big entity
   reached 24-58 KB per state_get call, the model re-read the same entity
   every turn (result too big to stay useful in context → read again → loop:
   11+ consecutive turns observed). Keep every VALUE, drop UI-only noise,
   digest oversized custom subtrees and never inline customText (user rules,
   AI must never touch them). */

const STATE_READ_CUSTOM_INLINE_LIMIT = 4000;

function serializeStatForRead(state, stat) {
    const out = { type: stat.type || "number" };

    if (out.type === "number") {
        out.base = Number(stat.base || 0);
        out.mod = Number(stat.mod || 0);
        out.eff = getEffectiveStatValue(state, stat);

        const min = normalizeNumberOrNull(stat.min);
        const max = normalizeNumberOrNull(stat.max);

        if (!(min === 0 && max === 0)) {
            if (min !== null) out.min = min;
            if (max !== null) out.max = max;
        }

        if (stat.aiBaseEdit) out.aiBaseEdit = true;
        if (stat.unit) out.unit = stat.unit;
    } else if (out.type === "choice") {
        out.base = stat.base;
        if (Array.isArray(stat.options) && stat.options.length) out.options = stat.options;
    } else {
        out.base = stat.base;
    }

    return out;
}

function serializeCustomForRead(custom) {
    const source = custom && typeof custom === "object" ? custom : {};

    if (JSON.stringify(source).length <= STATE_READ_CUSTOM_INLINE_LIMIT) return source;

    const digest = {};

    for (const [key, value] of Object.entries(source)) {
        const encoded = JSON.stringify(value ?? null);
        const size = encoded.length;

        digest[key] = size <= 400
            ? value
            : `<${size} chars \u2014 read with {"path":"custom.${key}"}>`;
    }

    return digest;
}

function serializeStateForRead(state) {
    const stats = {};

    for (const [name, stat] of Object.entries(state.stats || {})) {
        stats[name] = serializeStatForRead(state, stat);
    }

    return {
        stats,
        skills: state.skills || [],
        inventory: state.inventory || [],
        effects: state.effects || [],
        custom: serializeCustomForRead(state.custom),
        customText: `<user rules, ${String(state.customText || "").length} chars \u2014 not shown; never modified by the AI>`
    };
}

/* Dot-path lookup for {"path": "custom.quest_tracker"} / "stats.HP". */
function readStatePath(state, path) {
    let node = state;

    for (const part of String(path).split(".").map(segment => segment.trim()).filter(Boolean)) {
        if (node === null || typeof node !== "object" || Array.isArray(node) || !(part in node)) {
            return undefined;
        }

        node = node[part];
    }

    return node;
}

/* Text-form tool-call fallback (v2.0.8): models (seen with deepseek) sometimes
   emit native tool calls AS XML text in the reply content
   (<tool_calls><invoke name="..."><parameter name="...">...). ST executes only
   NATIVE tool_calls, so those text calls were silently lost AND the raw XML
   showed up in the chat. Every registered action is remembered here and
   reused verbatim by processTextToolCalls — same validation, same semantics,
   no second engine. */
const CS_TEXT_TOOL_REGISTRY = new Map();
/* Read-only tools are pointless to run from a text block (their result can
   never reach the model) — skipped, but the block is still stripped. */
const CS_TEXT_TOOL_READ_ONLY = new Set(["state_get", "state_history"]);

/* v3 B6: native tool calls run BEFORE their system message exists, outside
   handleMessageReceived — journalEntityBefore was a no-op, so deleting the
   tool message + reply and regenerating double-applied the deltas. Native
   actions now journal into a pending journal that TOOL_CALLS_PERFORMED binds
   to the tool message's index (the delete sweep then covers it). */
let pendingToolJournal = null;

function wrapNativeToolAction(action) {
    return async (...args) => {
        if (activeMessageStateJournal) return action(...args);

        const context = SillyTavern.getContext();
        pendingToolJournal ||= {
            entities: new Map(),
            auditLen: getAuditArray(context)?.length ?? 0,
            gameTime: getGameTime(context),
            tool: true,
            /* v3.1.2 F5: the reply this round's text came with (if any) —
               not ST's empty placeholder it already deleted (non-streaming) */
            anchor: Array.isArray(context?.chat) && context.chat.includes(lastReplyThisGeneration) ? lastReplyThisGeneration : null
        };

        activeMessageStateJournal = pendingToolJournal;

        try {
            return await action(...args);
        } finally {
            if (activeMessageStateJournal === pendingToolJournal) activeMessageStateJournal = null;
        }
    };
}

/* v3.1.2 F5: ST skips TOOL_CALLS_PERFORMED (and the follow-up reply) when
   a STEALTH tool (Dice Weaver's roll_dice) is in the batch, and a Stop /
   failure can end a tool round without a reply. The CS tool changes then
   escaped every journal and their cards landed on the next, unrelated
   reply. At the next turn boundary they are bound to the last reply. */
let toolRecursionExpected = false;
let generationStopPending = false;

function settleToolLeftovers({ beforeIndex = Infinity, journalOnly = false } = {}) {
    const context = SillyTavern.getContext();
    const chat = Array.isArray(context?.chat) ? context.chat : [];
    const journal = pendingToolJournal;
    const hasCards = !journalOnly && messageEventCards.length > 0;
    if (!journal && !hasCards) return;

    pendingToolJournal = null;

    let target = -1;
    const anchor = journal?.anchor;
    if (anchor) {
        target = chat.indexOf(anchor);
        if (target < 0) {
            /* the reply that carried the tool calls was deleted / replaced:
               its tool changes go with it */
            applyJournalRollback(context, String(chat.length), journal, { keepJournal: true, fromDelete: true });
            if (!journalOnly) messageEventCards = [];
            persistLastTurnJournal(context);
            return;
        }
    } else {
        for (let index = Math.min(chat.length, beforeIndex) - 1; index >= 0; index--) {
            const message = chat[index];
            /* review R4: a reply BEFORE the user's message is another turn */
            if (!message || message.is_user) break;
            if (!message.is_system) {
                target = index;
                break;
            }
        }
    }

    if (target < 0) {
        /* no reply of this round: its cards describe no message — dropped
           (never put on an unrelated reply); the changes stay, unbound,
           and remain visible in the sheet and the change log */
        if (!journalOnly) messageEventCards = [];
        return;
    }

    if (journal && (journal.entities.size || journal.activeScene !== undefined)) {
        const key = String(target);
        const existing = messageStateJournals.get(key);
        if (existing && existing.mesRef === chat[target]) {
            /* the reply's own before-state is older — it wins */
            for (const [entityKey, before] of journal.entities) {
                if (!existing.entities.has(entityKey)) existing.entities.set(entityKey, before);
            }
            if (existing.activeScene === undefined && journal.activeScene !== undefined) existing.activeScene = journal.activeScene;
        } else {
            rememberMessageJournal(target, journal);
        }
    }

    if (hasCards && appendEventCardsToMessage(context, target) !== false) {
        try {
            if (typeof context.saveChatDebounced === "function") context.saveChatDebounced();
            else void context.saveChat?.();
        } catch (error) {
            console.warn("[Character State] Card save failed:", error);
        }
    }
    if (!journalOnly) messageEventCards = [];
    persistLastTurnJournal(context);
}

function bindPendingToolJournal() {
    if (!pendingToolJournal) return;

    const journal = pendingToolJournal;
    pendingToolJournal = null;

    if (!journal.entities.size && journal.activeScene === undefined) return;

    const context = SillyTavern.getContext();
    const chat = Array.isArray(context?.chat) ? context.chat : [];
    if (!chat.length) return;

    rememberMessageJournal(chat.length - 1, journal);
}

function registerCsTool(context, spec) {
    const nativeSpec = spec && typeof spec.action === "function"
        ? { ...spec, action: wrapNativeToolAction(spec.action) }
        : spec;

    context.registerFunctionTool(nativeSpec);

    if (spec?.name && typeof spec.action === "function") {
        CS_TEXT_TOOL_REGISTRY.set(spec.name, spec.action);
    }
}

function registerCharacterStateTool() {
    /* `context` here is ONLY used to register the tools (and is refreshed on
       APP_READY / CHAT_CHANGED). Tool ACTIONS must fetch
       SillyTavern.getContext() at CALL time: ST replaces the chatMetadata
       object on every chat load, while getContext() snapshots the CURRENT
       value — a context captured at registration time points at the
       PREVIOUS chat's metadata (clock writes silently went into a dead
       object while the tool still reported OK). */
    const context = SillyTavern.getContext();

    if (typeof context.registerFunctionTool !== "function") {
        return false;
    }

    try {
        registerCsTool(context, {
            name: "UpdateCharacterState",
            displayName: "Update Character State",
            description:
                "Apply persistent game-state changes to a character (or to the user via \"character\": \"USER\"). " +
                "Each turn, update EVERY entity whose state changed — including the player's sheet via \"character\": \"USER\" — not only the speaker; one call per entity. " +
                "Number stat values are DELTAS (added to Mod): \"HP\": -10 changes HP by -10 — it is NOT the new value. Boolean/text/choice stat values ARE the new value. " +
                "Send ONLY the keys that must change in THIS call; omitted keys are never touched. " +
                "NEVER re-send a stat's current value: re-sending \"Age\": 20 when Age is already 20 turns it into 40. " +
                "Absolute set of a number stat is only available on stats marked aiBaseEdit (\"STAT_base\" key, or state_update {\"set\":}). " +
                "Effects cover buffs, debuffs, timed skills and conditions with a duration in turns or game minutes. " +
                "STATS and CUSTOM are two views of the SAME state and must stay numerically consistent: " +
                "when one change affects both sides, update both in the SAME call. " +
                "NEVER create a NEW custom key that duplicates an existing stat name — any casing (stat \"Cash\" vs custom \"cash\"): change the stat via \"stats\" instead; custom holds only data without a stat counterpart.",
            parameters: {
                type: "object",
                properties: {
                    character: {
                        type: "string",
                        description: "Exact name of the target character, or \"USER\" for the player."
                    },
                    stats: {
                        type: "object",
                        description: "Map of exact stat key to a numeric DELTA (added to Mod). ONLY include keys that change — omit unchanged stats entirely; re-sending a current value double-applies it. Stats marked aiBaseEdit=allowed: the delta applies to Base (clamped to min/max) and STAT_max/STAT_min are deltas on the limits; other stats: the delta applies to Mod.",
                        additionalProperties: true
                    },
                    custom: {
                        type: "object",
                        description: "Partial JSON paths to deep-merge into the character's CUSTOM data. Keep it consistent with the STATS section: global stat counters are aggregates of the detailed custom counters. NEVER use this to create a key that duplicates an existing stat name (any casing) — change the stat via \"stats\" instead. When updating structured custom data (trackers), FOLLOW the existing structure: update existing keys in place with the same value shapes — do not invent parallel sections or change value shapes (read the subtree first with state_get path).",
                        additionalProperties: true
                    },
                    effects: {
                        type: "object",
                        description: "Add/remove/clear active effects.",
                        properties: {
                            add: {
                                type: "array",
                                items: {
                                    type: "object",
                                    properties: {
                                        name: { type: "string" },
                                        source: { type: "string", enum: ["buff", "debuff", "item", "skill", "condition"] },
                                        stats: { type: "object", description: "Map of stat key to numeric delta.", additionalProperties: true },
                                        unit: { type: "string", enum: ["turns", "minutes"] },
                                        duration: { type: "number" },
                                        description: { type: "string" }
                                    }
                                }
                            },
                            remove: { type: "array", items: { type: "string" } },
                            clear: { type: "boolean" }
                        }
                    }
                },
                required: ["character"]
            },
            shouldRegister: () => Boolean(context.isToolCallingSupported?.()),
            formatMessage: params => `[Character State] ${String(params?.character ?? "")}: state updated`,
            action: async params => {
                const targetName = String(params?.character ?? "").trim();
                const update = {};

                if (params?.stats && typeof params.stats === "object") {
                    update.stats = params.stats;
                }

                if (params?.custom && typeof params.custom === "object" && !Array.isArray(params.custom)) {
                    update.custom = params.custom;
                }

                if (params?.effects && typeof params.effects === "object") {
                    update.effects = params.effects;
                }

                const character = resolveStateUpdateCharacter(targetName);

                if (!character) {
                    const ambiguous = ambiguousNameHint(targetName);
                    if (ambiguous) return `ERROR:${ambiguous}`;
                    return `ERROR: no character named "${targetName}" exists in this chat. State tools CANNOT create characters — for a NEW character call the state_create_npc tool, or emit a <SIDE_NPC_CREATE>{...}</SIDE_NPC_CREATE> block in your reply text instead.`;
                }

                const result = await applyStateUpdate(update, character);

                return `OK: state of ${isUserEntity(character) ? USER_STATE_PROTOCOL_NAME : (promptNameFor(character) || targetName)} updated${buildToolResultEcho(result)}.${describeToolResult(result)}`;
            }
        });

        /* ---- state.get — read full state on demand (S3 lazy fallback) ---- */
        registerCsTool(context, {
            name: "state_get",
            displayName: "Get State",
            description:
                "Read the current state of one entity. Default: COMPACT read \u2014 stats as {type, base, mod, eff, min/max} (UI fields omitted, eff = value shown on the sheet), plus skills, inventory, active effects and custom data; oversized custom subtrees are digested and the user rules text is never shown. " +
                "Pass \"path\" to drill into one subtree when a digest says so, e.g. \"custom.quest_tracker\" or \"stats.HP\". " +
                "Use it when the entity's state is not fully present in the prompt, and do NOT re-read an entity whose values you already have in this conversation.",
            parameters: {
                type: "object",
                properties: {
                    character: {
                        type: "string",
                        description: "Exact name of the entity to read, or \"USER\" for the player."
                    },
                    path: {
                        type: "string",
                        description: "Optional dot-path into the state: \"stats.HP\", \"custom.quest_tracker\", \"skills\", ... Returns just that subtree."
                    }
                },
                required: ["character"]
            },
            shouldRegister: () => Boolean(context.isToolCallingSupported?.()),
            formatMessage: params => `[Character State] ${String(params?.character ?? "")}: state read`,
            action: async params => {
                /* Fresh context per call — ST replaces the chatMetadata
                   object on every chat load, so a context captured at
                   registration time points at the PREVIOUS chat. */
                const ctx = SillyTavern.getContext();
                const targetName = String(params?.character ?? "").trim();
                const character = resolveStateUpdateCharacter(targetName);

                if (!character) {
                    return `ERROR UNKNOWN_ENTITY: no character named "${targetName}" exists in this chat. State tools CANNOT create characters — for a NEW character call the state_create_npc tool (stats = starting values, schema keys), or emit ONE <SIDE_NPC_CREATE>{"name":"<exact name>","stats":{...}}</SIDE_NPC_CREATE> block in your reply text.`;
                }

                const state = isUserEntity(character)
                    ? getStoredUserState(ctx)
                    : ctx.chatMetadata?.character_states?.[getCharacterKey(character)];

                if (!state || typeof state !== "object") {
                    return `ERROR NO_STATE: "${targetName}" has no state in this chat yet.`;
                }

                /* Include the canonical key so the model can use it in
                   relationship endpoints (v2.0.8). */
                const entityKey = isUserEntity(character) ? USER_STATE_KEY : getCharacterKey(character);
                const header = `Entity: ${isUserEntity(character) ? USER_STATE_PROTOCOL_NAME : (promptNameFor(character) || targetName)} (key: ${entityKey})`;
                const view = normalizeRuntimeState(structuredClone(state));
                const statePath = String(params?.path ?? "").trim();

                if (statePath) {
                    const picked = readStatePath(view, statePath);

                    if (picked === undefined) {
                        return `ERROR UNKNOWN_PATH: "${statePath}" not found. Available roots: stats, skills, inventory, effects, custom, customText.`;
                    }

                    /* Lean stat shapes also apply to drill-down reads. */
                    if (/^stats\.[^.]+$/.test(statePath) && picked && typeof picked === "object" && typeof picked.type === "string") {
                        return `${header}\n${JSON.stringify(serializeStatForRead(view, picked), null, 2)}`;
                    }

                    if (statePath === "stats") {
                        return `${header}\n${JSON.stringify(serializeStateForRead(view).stats, null, 2)}`;
                    }

                    return `${header}\n${JSON.stringify(picked, null, 2)}`;
                }

                return `${header}\n${JSON.stringify(serializeStateForRead(view), null, 2)}\n`
                    + `(Compact read: eff = sheet value; UI-only fields omitted; digested custom subtrees are readable with {"path":"custom.<key>"}; customText is user-owned and never shown — never write it. Custom counters must stay numerically consistent with their STATS aggregates — update both sides in the same call.)`;
            }
        });

        /* ---- state_update: semantic request → canonical patch ---- */
        registerCsTool(context, {
            name: "state_update",
            displayName: "Update State (Semantic)",
            description:
                "Apply persistent state changes using SEMANTIC stat objects. " +
                "Each stat value is either a shorthand number/string (a DELTA for number stats — \"HP\": -10 changes HP by -10, NOT the new value; the new value for other stat types) or an object with at most one of: change|mod (delta), base|set (absolute value, ONLY for stats marked aiBaseEdit), max|min (limit deltas, ONLY for aiBaseEdit stats). " +
                "Send ONLY the keys that must change in THIS call; omitted keys are never touched. " +
                "NEVER re-send a stat's current value as change/mod: re-sending \"Age\": {\"change\": 20} when Age is already 20 turns it into 40. " +
                "Also accepts custom (deep-merge JSON), effects {add,remove,clear} and skills/inventory operations. " +
                "STATS and CUSTOM must stay numerically consistent: when one change affects both sides, update both in the SAME call. " +
                "NEVER create a NEW custom key that duplicates an existing stat name — any casing (stat \"Cash\" vs custom \"cash\"): change the stat via \"stats\" instead.",
            parameters: {
                type: "object",
                properties: {
                    character: {
                        type: "string",
                        description: "Exact name of the target entity, or \"USER\" for the player."
                    },
                    stats: {
                        type: "object",
                        description: "Map of exact stat key to: number shorthand (DELTA for number stats / new value for other types) OR semantic object {change|mod: delta} | {base|set: absolute (aiBaseEdit only)} | {max|min: limit delta}. ONLY include keys that change — omit unchanged stats entirely; re-sending current values as change/mod double-applies them.",
                        additionalProperties: true
                    },
                    custom: {
                        type: "object",
                        description: "Partial JSON paths to deep-merge into CUSTOM data. NEVER create a key that duplicates an existing stat name (any casing) — change the stat via \"stats\" instead. Structured trackers: follow the existing shape — update existing keys in place, do not invent parallel sections.",
                        additionalProperties: true
                    },
                    effects: {
                        type: "object",
                        description: "add (array of effect objects), remove (array of names/ids), clear (boolean).",
                        properties: {
                            add: { type: "array", items: { type: "object" } },
                            remove: { type: "array", items: { type: "string" } },
                            clear: { type: "boolean" }
                        }
                    },
                    skills: {
                        type: "object",
                        description: "Operations: {add|update|remove: [...], set: [...], clear: true}.",
                        additionalProperties: true
                    },
                    inventory: {
                        type: "object",
                        description: "Operations: {add|update|remove: [...], set: [...], clear: true}.",
                        additionalProperties: true
                    },
                    json: {
                        type: "string",
                        description: "Alternative to the fields above: the whole change as ONE JSON object string, e.g. {\"stats\":{\"HP\":-5},\"inventory\":{\"add\":[{\"name\":\"Rope\",\"qty\":1}]}}. Use it when the object fields do not come through."
                    }
                },
                required: ["character"]
            },
            shouldRegister: () => Boolean(context.isToolCallingSupported?.()),
            formatMessage: params => `[Character State] ${String(params?.character ?? "")}: state updated`,
            action: async params => {
                const targetName = String(params?.character ?? "").trim();
                const { update, errors } = normalizeSemanticToolRequest(params);

                if (errors.length) {
                    return `ERROR MALFORMED_REQUEST: ${errors.join(" ")}`;
                }

                /* v3.1.3: a call that arrives without any change must not
                   answer OK — the model would believe the state changed */
                const carriesChange = value => value !== undefined && value !== null &&
                    (typeof value !== "object" || Object.keys(value).length > 0);
                if (!SEMANTIC_CHANGE_FIELDS.some(field => carriesChange(update[field]))) {
                    return "ERROR EMPTY_REQUEST: this call carried NO change — only \"character\" arrived, so NOTHING was updated. " +
                        "Call state_update again with the whole change as ONE JSON string in \"json\", e.g. " +
                        "{\"character\":\"USER\",\"json\":\"{\\\"stats\\\":{\\\"HP\\\":-5},\\\"inventory\\\":{\\\"add\\\":[{\\\"name\\\":\\\"Rope\\\",\\\"qty\\\":1}]}}\"}, " +
                        "or write a <STATE_UPDATE>{\"character\":\"USER\",...}</STATE_UPDATE> block in your reply text.";
                }

                const character = resolveStateUpdateCharacter(targetName);

                if (!character) {
                    return `ERROR UNKNOWN_ENTITY: no character named "${targetName}" exists in this chat. State tools CANNOT create characters — for a NEW character call the state_create_npc tool (stats = starting values, schema keys), or emit ONE <SIDE_NPC_CREATE>{"name":"<exact name>","stats":{...}}</SIDE_NPC_CREATE> block in your reply text.`;
                }

                const result = await applyStateUpdate(update, character);

                return `OK: state of ${isUserEntity(character) ? USER_STATE_PROTOCOL_NAME : (promptNameFor(character) || targetName)} updated${buildToolResultEcho(result)}.${describeToolResult(result)}`;
            }
        });

        /* ---- state_history: stat time-series for one entity ---- */
        registerCsTool(context, {
            name: "state_history",
            displayName: "State History",
            description:
                "Read the recorded numeric time-series (effective values per stat) for one entity. Use it to check trends or past values.",
            parameters: {
                type: "object",
                properties: {
                    character: {
                        type: "string",
                        description: "Exact name of the entity, or \"USER\" for the player."
                    }
                },
                required: ["character"]
            },
            shouldRegister: () => Boolean(context.isToolCallingSupported?.()),
            formatMessage: params => `[Character State] ${String(params?.character ?? "")}: history read`,
            action: async params => {
                const targetName = String(params?.character ?? "").trim();
                const character = resolveStateUpdateCharacter(targetName);

                if (!character) {
                    return `ERROR UNKNOWN_ENTITY: no character named "${targetName}" exists in this chat. State tools CANNOT create characters — for a NEW character call the state_create_npc tool, or emit a <SIDE_NPC_CREATE>{"name":"<exact name>","stats":{...}}</SIDE_NPC_CREATE> block in your reply text (tags REQUIRED — a bare JSON object is ignored).`;
                }

                const entityKey = isUserEntity(character)
                    ? USER_STATE_KEY
                    : getCharacterKey(character);
                /* Fresh context per call — see state_get. */
                const series = SillyTavern.getContext().chatMetadata?.[HISTORY_KEY]?.[entityKey];

                if (!series || typeof series !== "object") {
                    return `OK: no recorded history for "${targetName}" yet.`;
                }

                const cleaned = {};

                for (const [statName, points] of Object.entries(series)) {
                    if (statName === "__axis") continue;
                    cleaned[statName] = readHistorySeries(points);
                }

                return JSON.stringify({
                    entity: isUserEntity(character) ? USER_STATE_PROTOCOL_NAME : (promptNameFor(character) || targetName),
                    axis: series.__axis || "messages",
                    series: cleaned
                });
            }
        });

        /* ---- state_create_npc: the ONLY tool path that creates a character ---- */
        registerCsTool(context, {
            name: "state_create_npc",
            displayName: "Create Side NPC",
            description:
                "Create a NEW chat-local side NPC together with its starting state (stats + audit + sheet entry). " +
                "ONLY call this when the user EXPLICITLY asked (in their latest message) to add/create this character — never on your own initiative. " +
                "Stat keys must exist in the chat's schema (the keys other entities' stats use); values are STARTING values (not deltas); numbers are clamped into each stat's own min/max. " +
                "When the chat has no schema at all, the stats you provide here DEFINE the new sheet. " +
                "State_get/state_update CANNOT create characters — this tool is the only tool-based way to create one.",
            parameters: {
                type: "object",
                properties: {
                    name: {
                        type: "string",
                        description: "Exact display name of the new character (1-60 characters, must not collide with an existing side NPC or Character Card)."
                    },
                    stats: {
                        type: "object",
                        description: "Starting stat values: {statKey: value}. Plain keys only (no _base/_mod/_max/_min suffixes).",
                        additionalProperties: true
                    }
                },
                required: ["name"]
            },
            shouldRegister: () => Boolean(context.isToolCallingSupported?.()),
            formatMessage: params => `[Character State] create side NPC: ${String(params?.name ?? "")}`,
            action: async params => {
                const name = String(params?.name ?? "").trim();

                if (!name || name.length > 60) {
                    return "ERROR NAME_INVALID: \"name\" must be 1-60 characters.";
                }

                if (name.toLowerCase() === "__user__" || name.includes("|")) {
                    return `ERROR NAME_RESERVED: "${name}" is a reserved name.`;
                }

                const result = await createSideNpcCore(SillyTavern.getContext(), name, params?.stats);

                if (!result.ok) {
                    return `ERROR ${result.code}: ${result.message}`;
                }

                const ignored = result.rejected.length
                    ? ` Ignored unknown stat key(s): ${result.rejected.map(k => `"${k}"`).join(", ")}.`
                    : "";

                return `OK: side NPC "${name}" created with ${result.statCount} stat(s).${ignored} Later changes go through state_update.`;
            }
        });

        /* ---- state_create_sheet: user-armed one-shot AI sheet design (v2.0.19) ---- */
        registerCsTool(context, {
            name: "state_create_sheet",
            displayName: "Create Sheet (armed)",
            description:
                "Design a character's STAT SHEET: define stats (type/value/min/max/unit/options) and seed custom data, chat-scoped. " +
                "ONLY available while the user has armed sheet-create mode in Character State settings; a successful call DISARMS the mode automatically. " +
                "This REPLACES the target's existing stat definitions — use state_update for value changes on an existing sheet. The character card is never modified.",
            parameters: {
                type: "object",
                properties: {
                    character: {
                        type: "string",
                        description: "Exact name of the target character."
                    },
                    stats: {
                        type: "object",
                        description: "Map of stat name to definition object {type: \"number|choice|boolean|text\", value, min, max, unit, options[], description, group}. choice REQUIRES non-empty options[] and value must be one of them. Max 60 stats.",
                        additionalProperties: true
                    },
                    custom: {
                        type: "object",
                        description: "Optional custom data to deep-merge into the target's custom section (nested JSON; existing keys without a counterpart are preserved).",
                        additionalProperties: true
                    }
                },
                required: ["character", "stats"]
            },
            /* v3.1 C8: ST evaluates this per request — the sheet-create
               protocol stays INVISIBLE until the user arms it (#42). */
            shouldRegister: () => Boolean(context.isToolCallingSupported?.()) && Boolean(getExtensionSettings().aiSheetCreate),
            formatMessage: params => `[Character State] sheet create: ${String(params?.character ?? "")}`,
            action: async params => {
                if (!getExtensionSettings().aiSheetCreate) {
                    return "ERROR SHEET_CREATE_DISABLED: sheet-create mode is NOT armed. Stat definitions are user-owned — the user must arm \"let the AI design a sheet\" in Character State settings first.";
                }

                const targetName = String(params?.character ?? "").trim();
                const character = resolveStateUpdateCharacter(targetName);

                if (!character) {
                    return `ERROR UNKNOWN_ENTITY: no character named "${targetName}" exists in this chat.`;
                }

                const result = await applySheetCreate(SillyTavern.getContext(), character, params);

                if (!result.ok) {
                    return `ERROR ${result.code}: ${result.message}`;
                }

                /* Consume-once: one armed create per arm. */
                saveExtensionSettings({ aiSheetCreate: false });

                const ignored = result.rejected.length
                    ? ` Rejected stat(s): ${result.rejected.map(k => `"${k}"`).join(", ")}.`
                    : "";

                return `OK: sheet for ${character.name || targetName} ${result.replacedCount ? "redesigned" : "created"} with ${result.statCount} stat(s), chat-scoped (card untouched).${ignored} Sheet-create mode is now disarmed — do not call this tool again unless the user arms it.`;
            }
        });

        /* ---- state_add_effect / state_remove_effect ---- */
        registerCsTool(context, {
            name: "state_add_effect",
            displayName: "Add Effect",
            description:
                "Add one timed effect (buff, debuff, timed skill, condition) to an entity. Requires a name; optional source (buff|debuff|item|skill|condition), stats deltas {StatName: delta}, unit (turns|minutes), duration and description.",
            parameters: {
                type: "object",
                properties: {
                    character: {
                        type: "string",
                        description: "Exact name of the target entity, or \"USER\" for the player."
                    },
                    effect: {
                        type: "object",
                        properties: {
                            name: { type: "string" },
                            source: { type: "string", enum: ["buff", "debuff", "item", "skill", "condition"] },
                            stats: { type: "object", additionalProperties: true },
                            unit: { type: "string", enum: ["turns", "minutes"] },
                            duration: { type: "number" },
                            description: { type: "string" }
                        },
                        required: ["name"]
                    }
                },
                required: ["character", "effect"]
            },
            shouldRegister: () => Boolean(context.isToolCallingSupported?.()),
            formatMessage: params => `[Character State] ${String(params?.character ?? "")}: effect added`,
            action: async params => {
                const targetName = String(params?.character ?? "").trim();
                const effect = params?.effect;

                if (!effect || typeof effect !== "object" || !String(effect.name ?? "").trim()) {
                    return "ERROR INVALID_EFFECT: effect must be an object with at least a name.";
                }

                const character = resolveStateUpdateCharacter(targetName);

                if (!character) {
                    return `ERROR UNKNOWN_ENTITY: no character named "${targetName}" exists in this chat. State tools CANNOT create characters — for a NEW character call the state_create_npc tool, or emit a <SIDE_NPC_CREATE>{"name":"<exact name>","stats":{...}}</SIDE_NPC_CREATE> block in your reply text (tags REQUIRED — a bare JSON object is ignored).`;
                }

                const result = await applyStateUpdate({ effects: { add: [effect] } }, character);

                const appliedLine = result?.applied?.[0];

                return appliedLine
                    ? `OK: ${appliedLine}`
                    : `OK: effect processed for ${isUserEntity(character) ? USER_STATE_PROTOCOL_NAME : character.name}.${describeToolResult(result)}`;
            }
        });

        registerCsTool(context, {
            name: "state_remove_effect",
            displayName: "Remove Effect",
            description: "Remove one or more active effects from an entity by name or id.",
            parameters: {
                type: "object",
                properties: {
                    character: {
                        type: "string",
                        description: "Exact name of the target entity, or \"USER\" for the player."
                    },
                    names: {
                        type: "array",
                        items: { type: "string" },
                        description: "Effect names or ids to remove."
                    }
                },
                required: ["character", "names"]
            },
            shouldRegister: () => Boolean(context.isToolCallingSupported?.()),
            formatMessage: params => `[Character State] ${String(params?.character ?? "")}: effect removed`,
            action: async params => {
                const targetName = String(params?.character ?? "").trim();
                const names = Array.isArray(params?.names)
                    ? params.names.map(n => String(n)).filter(Boolean)
                    : [];

                if (!names.length) {
                    return "ERROR INVALID_EFFECT: provide at least one effect name or id to remove.";
                }

                const character = resolveStateUpdateCharacter(targetName);

                if (!character) {
                    return `ERROR UNKNOWN_ENTITY: no character named "${targetName}" exists in this chat. State tools CANNOT create characters — for a NEW character call the state_create_npc tool, or emit a <SIDE_NPC_CREATE>{"name":"<exact name>","stats":{...}}</SIDE_NPC_CREATE> block in your reply text (tags REQUIRED — a bare JSON object is ignored).`;
                }

                const result = await applyStateUpdate({ effects: { remove: names } }, character);

                const appliedLine = result?.applied?.[0];

                return appliedLine
                    ? `OK: ${appliedLine}`
                    : `OK: no matching effect found on ${isUserEntity(character) ? USER_STATE_PROTOCOL_NAME : character.name}.`;
            }
        });

        /* ---- state_advance_time: relative, forward-only, semantic ops ---- */
        registerCsTool(context, {
            name: "state_advance_time",
            displayName: "Advance Game Time",
            description:
                "Advance the game clock. Provide EITHER minutes (positive integer) OR operation: \"sleep\" (advance to the next configured wake-up hour), \"travel\"/\"fast_forward\" (hours: positive number), \"skip\" (minutes alias). " +
                "The clock never moves backwards and is never invented. While the player pauses the clock, time stays frozen.",
            parameters: {
                type: "object",
                properties: {
                    minutes: { type: "number", description: "Positive integer minutes to advance." },
                    operation: { type: "string", enum: ["sleep", "travel", "fast_forward", "skip"], description: "Semantic operation (alternative to minutes)." },
                    hours: { type: "number", description: "Positive number of hours (for travel/fast_forward)." }
                },
                required: []
            },
            shouldRegister: () => Boolean(context.isToolCallingSupported?.()),
            formatMessage: params => `[Character State] game time advanced`,
            action: async params => {
                /* Fresh context per call — see state_get. A context captured
                   at registration time would write the clock into the
                   PREVIOUS chat's metadata (tool said OK, sheet stayed "—").
                   Persist + refresh the badge right away too: this action
                   runs mid-generation and the message pipeline may only run
                   later (or not at all if generation is stopped). */
                const ctx = SillyTavern.getContext();
                const operation = String(params?.operation ?? "").trim().toLowerCase();

                let targetMinutes = 0;
                let description = "";

                if (operation === "sleep") {
                    const jump = minutesUntilNextDayStart(ctx);
                    targetMinutes = (getGameTime(ctx)?.minutes ?? 0) + jump;
                    description = `sleep until the next morning (+${jump} minutes)`;
                } else if (operation === "travel" || operation === "fast_forward") {
                    const hours = Number(params?.hours);

                    if (!Number.isFinite(hours) || hours <= 0) {
                        return "ERROR INVALID_TIME: hours must be a positive number for travel/fast_forward.";
                    }

                    targetMinutes = (getGameTime(ctx)?.minutes ?? 0) + Math.round(hours * 60);
                    description = `travel/fast_forward (+${Math.round(hours)}h)`;
                } else if (operation === "skip") {
                    const minutes = Number(params?.minutes);

                    if (!Number.isInteger(minutes) || minutes <= 0) {
                        return "ERROR INVALID_TIME: minutes must be a positive integer (forward only).";
                    }

                    targetMinutes = (getGameTime(ctx)?.minutes ?? 0) + minutes;
                    description = `skip (+${minutes} minutes)`;
                } else {
                    const minutes = Number(params?.minutes);

                    if (!Number.isInteger(minutes) || minutes <= 0) {
                        return "ERROR INVALID_TIME: minutes must be a positive integer (forward only), or provide an operation (sleep|travel|fast_forward|skip).";
                    }

                    targetMinutes = (getGameTime(ctx)?.minutes ?? 0) + minutes;
                    description = `+${minutes} minutes`;
                }

                const applied = applyGameTimeUpdate(ctx, targetMinutes, "ai");

                if (!applied.changed) {
                    return `ERROR INVALID_TIME: ${applied.reason}.`;
                }

                const now = getGameTime(ctx);

                await saveChatState(ctx);
                refreshGameTimeBadgeIfOpen();

                return `OK: game time advanced (${description}) to ${formatGameTime(now.minutes)} — ${formatGameCalendar(ctx)} (${now.minutes} minutes).`;
            }
        });

        console.log("[Character State] Tool calling registered (dual-path: text protocol stays as fallback).");
        return true;
    } catch (error) {
        console.warn("[Character State] Could not register the function tool:", error);
        return false;
    }
}

/* ---- state_relationships (C2 dynamic graph) ------------------------ */

function registerRelationshipTool() {
    const context = SillyTavern.getContext();

    if (typeof context.registerFunctionTool !== "function") {
        return false;
    }

    try {
        registerCsTool(context, {
            name: "state_relationships",
            displayName: "State Relationships",
            description:
                "Query or maintain DYNAMIC relationships between entities (e.g. friend_of, located_at, owns — labels are free-form data, never interpreted). " +
                "action \"get\": list edges (optional from/to/type filters). \"set\": upsert one edge (from, type, to, optional meta object). \"remove\": delete one edge. " +
                "from/to accept the exact entity NAME (preferred — as shown in state_get / the world state directory) or its canonical key.",
            parameters: {
                type: "object",
                properties: {
                    action: { type: "string", enum: ["get", "set", "remove"] },
                    from: { type: "string", description: "Source entity: exact name (\u201cMomo\u201d) or canonical key (\u201ccustom:Momo\u201d)." },
                    type: { type: "string", description: "Free-form relationship label." },
                    to: { type: "string", description: "Target entity: exact name or canonical key." },
                    meta: { type: "object", description: "Optional arbitrary JSON attached to the edge.", additionalProperties: true }
                },
                required: ["action"]
            },
            shouldRegister: () => Boolean(context.isToolCallingSupported?.()),
            formatMessage: params => `[Character State] relationship ${String(params?.action ?? "")}`,
            action: async params => {
                /* Fresh context per call — see state_get. */
                const ctx = SillyTavern.getContext();
                const action = String(params?.action ?? "").trim().toLowerCase();

                /* Tool params may carry display names OR canonical keys —
                   normalize both before the structural core validation
                   (core keeps requiring real entity keys, invariant #31). */
                const fromKey = params?.from === undefined || params?.from === null
                    ? null
                    : resolveRelationshipEndpoint(params.from, ctx);
                const toKey = params?.to === undefined || params?.to === null
                    ? null
                    : resolveRelationshipEndpoint(params.to, ctx);

                if (action === "get") {
                    if (params?.from && !fromKey) {
                        return `ERROR MALFORMED_REQUEST: no entity matches "${params.from}" — use an exact entity name or key.`;
                    }

                    if (params?.to && !toKey) {
                        return `ERROR MALFORMED_REQUEST: no entity matches "${params.to}" — use an exact entity name or key.`;
                    }

                    const edges = listRelationships(ctx, {
                        from: fromKey,
                        to: toKey,
                        type: params?.type
                    });

                    if (!edges.length) {
                        return "OK: no matching relationships recorded.";
                    }

                    return JSON.stringify({ count: edges.length, edges }, null, 2);
                }

                if (action === "set") {
                    if (!fromKey) {
                        return `ERROR MALFORMED_REQUEST: no entity matches "${params?.from}" — use an exact entity name or key.`;
                    }

                    if (!toKey) {
                        return `ERROR MALFORMED_REQUEST: no entity matches "${params?.to}" — use an exact entity name or key.`;
                    }

                    const result = setRelationship(ctx, fromKey, params?.type, toKey, params?.meta);

                    if (!result.ok) return `ERROR MALFORMED_REQUEST: ${result.reason}.`;

                    return result.created
                        ? `OK: relationship created ${result.edge.from} -[${result.edge.type}]-> ${result.edge.to}.`
                        : `OK: relationship replaced ${result.edge.from} -[${result.edge.type}]-> ${result.edge.to}.`;
                }

                if (action === "remove") {
                    if (!fromKey) {
                        return `ERROR MALFORMED_REQUEST: no entity matches "${params?.from}" — use an exact entity name or key.`;
                    }

                    if (!toKey) {
                        return `ERROR MALFORMED_REQUEST: no entity matches "${params?.to}" — use an exact entity name or key.`;
                    }

                    const result = removeRelationship(ctx, fromKey, params?.type, toKey);

                    if (!result.ok) return `ERROR MALFORMED_REQUEST: ${result.reason}.`;

                    return `OK: relationship removed (${result.removed}).`;
                }

                return "ERROR MALFORMED_REQUEST: action must be one of get|set|remove.";
            }
        });

        return true;
    } catch (error) {
        console.warn("[Character State] Could not register the relationship tool:", error);
        return false;
    }
}

/* =========================================================
   HEURISTIC PARSER (OPT-IN, OFF BY DEFAULT)
   For weak models that forget the STATE_UPDATE protocol: detects a few
   conservative plain-text patterns on the SPEAKING character only.
   Stat names must match an existing key exactly — never guessed.
   Every applied change is audited with src="heuristic".
========================================================= */

function heuristicPatternsFor(key) {
    const escaped = key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

    return [
        { pattern: new RegExp(`\\b(?:loses?|lost)\\s+(\\d+(?:\\.\\d+)?)\\s+(?:points?\\s+of\\s+)?${escaped}\\b`, "i"), sign: -1 },
        { pattern: new RegExp(`\\b(?:gains?|gained|recovers?|recovered|regains?|regained)\\s+(\\d+(?:\\.\\d+)?)\\s+(?:points?\\s+of\\s+)?${escaped}\\b`, "i"), sign: 1 },
        { pattern: new RegExp(`\\b${escaped}\\s*([+-])\\s*(\\d+(?:\\.\\d+)?)`, "i"), sign: 0 },
        { pattern: new RegExp(`\\b${escaped}\\s+(?:drops?|dropped|decreases?|decreased|falls?|fell)\\s+(?:by\\s+)?(\\d+(?:\\.\\d+)?)\\b`, "i"), sign: -1 },
        { pattern: new RegExp(`\\b${escaped}\\s+(?:increases?|increased|rises?|rose)\\s+(?:by\\s+)?(\\d+(?:\\.\\d+)?)\\b`, "i"), sign: 1 }
    ];
}

async function applyHeuristicParsing(context, message) {
    if (!getExtensionSettings().heuristicEnabled) return false;
    if (!message || message.is_user) return false;

    const text = String(message.mes ?? "");
    if (!text.trim()) return false;

    /* Messages that already carry a machine protocol block are handled
       by the exact parser — never double-apply via heuristics. */
    if (GAME_TIME_REGEX.test(text) || STATE_REGEX.test(text) ||
        STATE_LOG_OPEN_REGEX.test(text) || USER_STATE_CREATE_REGEX.test(text)) {
        return false;
    }

    const speaker = resolveCharacterFromMessage(message);
    if (!speaker || isUserEntity(speaker)) return false;

    const state = await ensureCharacterState(speaker, false);
    if (!state || !state.stats || !Object.keys(state.stats).length) return false;

    const numberKeys = Object.keys(state.stats)
        .filter(key => state.stats[key]?.type === "number")
        .sort((a, b) => b.length - a.length);

    if (!numberKeys.length) return false;

    let changed = false;
    const entityKey = getCharacterKey(speaker);

    /* Heuristic writes MUST be journaled like every other runtime write
       path (invariant #12): without this, swiping/deleting the message
       rolled back nothing from the heuristic while the message was gone. */
    journalEntityBefore(entityKey);

    for (const key of numberKeys) {
        for (const { pattern, sign } of heuristicPatternsFor(key)) {
            const match = text.match(pattern);
            if (!match) continue;

            let delta;

            if (sign === 0) {
                const value = Number(match[2]);
                delta = match[1] === "-" ? -value : value;
            } else {
                delta = sign * Number(match[1]);
            }

            if (!Number.isFinite(delta) || delta === 0) break;

            const stat = state.stats[key];
            const oldMod = Number(stat.mod || 0);
            stat.mod = oldMod + delta;

            pushAuditEntry(context, {
                k: entityKey,
                src: "heuristic",
                sec: "stats",
                f: key,
                op: "mod",
                b: oldMod,
                a: stat.mod
            });

            queueAppliedText(`${speaker.name} ${key}: heuristic ${delta > 0 ? "+" : ""}${delta}`);
            changed = true;
            break;
        }
    }

    if (!changed) return false;

    clampNumericStats(state);
    recordStatHistory(context, entityKey, state);

    await saveChatState(context);

    csToast.info(csT("[Character State] Heuristic: applied plain-text stat changes to {name}.", { name: speaker.name }));
    console.log(`[Character State] Heuristic parser applied changes to ${speaker.name}.`);

    return true;
}

/* =========================================================
   EVENTS
========================================================= */

eventSource.on(event_types.MESSAGE_RECEIVED, handleMessageReceived);

/* Inline event-card transform: runs after every (re)render of a message,
   so cards stay styled when scrolling back in long chats. */
const messageRenderEvent = event_types?.CHARACTER_MESSAGE_RENDERED || event_types?.MESSAGE_RENDERED;

if (messageRenderEvent) {
    /* trigger messages queued by this reply: after ST finished it */
    eventSource.on(messageRenderEvent, () => {
        if (pendingTriggerSystemMessages.length) setTimeout(flushTriggerSystemMessages, 250);
    });

    eventSource.on(messageRenderEvent, messageId => {
        /* New-style inline markers (message.extra.csEvents) first, then
           legacy <CS_EVENT> system messages from older chats. */
        applyEventCardsInDom(messageId);
        transformEventCardMessage(messageId);
    });
}

/* Editing a message re-renders its .mes_text from mes.mes — the marker
   comes back as raw text until the inline card is re-applied. */
if (event_types?.MESSAGE_EDITED) {
    eventSource.on(event_types.MESSAGE_EDITED, messageId => {
        applyEventCardsInDom(messageId);
        transformEventCardMessage(messageId);
    });
}

registerCharacterStateTool();

if (event_types?.MESSAGE_SWIPED) {
    eventSource.on(event_types.MESSAGE_SWIPED, messageId => {
        handleSwipeNavigation(messageId);
    });
}

if (event_types?.MESSAGE_SWIPE_DELETED) {
    eventSource.on(event_types.MESSAGE_SWIPE_DELETED, payload => {
        handleSwipeDeleted(payload);
    });
}

if (event_types?.MORE_MESSAGES_LOADED) {
    eventSource.on(event_types.MORE_MESSAGES_LOADED, () => setTimeout(() => resweepAllEventCards(), 50));
}

if (event_types?.GENERATION_ENDED) {
    eventSource.on(event_types.GENERATION_ENDED, () => {
        endCsGenerationFlags();
        setTimeout(() => {
            flushTriggerSystemMessages();
            refreshCsHud();
        }, 0);
        /* after ST's endSwipe() reverted a failed swipe — it awaits a
           shake animation first (~650 ms), so look a few times */
        scheduleFreshSwipeSettle();
    });
}

if (event_types?.GENERATION_STARTED) {
    eventSource.on(event_types.GENERATION_STARTED, (type, _options, dryRun) => {
        /* v3.1.2 F8: background "quiet" generations (summaries, memory,
           expressions) are not turns — they ran DURING tool rounds */
        if (dryRun || type === "quiet") return;
        lastReplyThisGeneration = null;
        /* a revert that already happened is applied; any other generation
           ends the pending fresh swipe (its own start is type "swipe") */
        settlePendingFreshSwipe();
        if (type !== "swipe") pendingFreshSwipe = null;

        /* F4: a Stop leaves the round flags for the partial reply that
           still arrives; the NEXT real generation starts clean */
        if (generationStopPending) {
            generationStopPending = false;
            freshToolEffectIds.clear();
            clockTouchedThisRound = false;
        }

        /* F5: the start of a tool round's follow-up is not a new turn */
        if (toolRecursionExpected) {
            toolRecursionExpected = false;
            return;
        }
        settleToolLeftovers();
    });
}

if (event_types?.GENERATION_STOPPED) {
    eventSource.on(event_types.GENERATION_STOPPED, () => {
        /* v3.1.2 F4: ST emits STOPPED first, then (streaming) still delivers
           the partial reply — resetting here re-ticked the tool's fresh
           effect and stacked the clock fallback on the tool's advance */
        generationStopPending = true;
        toolRecursionExpected = false;
        endCsGenerationFlags();
        scheduleFreshSwipeSettle();
        /* review R5: a stopped round whose reply never comes must not keep
           its flags for an unrelated later turn (/sendas …) */
        setTimeout(() => {
            if (!generationStopPending) return;
            generationStopPending = false;
            freshToolEffectIds.clear();
            clockTouchedThisRound = false;
        }, 3000);
    });
}

/* a new user turn starts a new round: leftovers of a tool round whose reply
   never arrived must not leak into it (review R5) */
if (event_types?.MESSAGE_SENT) {
    eventSource.on(event_types.MESSAGE_SENT, () => {
        settlePendingFreshSwipe();
        pendingFreshSwipe = null;
        settleToolLeftovers();
        freshToolEffectIds.clear();
        clockTouchedThisRound = false;
        /* the next prompt must see quick edits made just before sending */
        void flushQuickEditBursts();
    });
}

if (event_types?.TOOL_CALLS_PERFORMED) {
    eventSource.on(event_types.TOOL_CALLS_PERFORMED, () => {
        markToolRoundTurn();
        bindPendingToolJournal();
        toolRecursionExpected = true;
    });
}

if (event_types?.MESSAGE_DELETED) {
    eventSource.on(event_types.MESSAGE_DELETED, messageId => {
        handleMessageDeleted(messageId);
    });
}

eventSource.on(event_types.APP_READY, () => setTimeout(async () => {
    clearCurrentCharacter();
    clearCharacterStatePromptInjection();
    clearTurnScopedMemory();
    restorePersistedTurnJournal();
    loadedCharactersCache.clear();
    registerCharacterStateTool();
    registerRelationshipTool();
    await ensureAllGroupCharacterStates();
    scheduleEventCardsResweep();
    createButton();
    refreshCsHud();
}, 1000));

eventSource.on(event_types.CHAT_CHANGED, () => setTimeout(async () => {
    clearCurrentCharacter();
    clearCharacterStatePromptInjection();
    setSelectedSheetCharacter(null);
    clearTurnScopedMemory();
    restorePersistedTurnJournal();
    void checkBranchStateOnLoad();
    loadedCharactersCache.clear();
    /* Re-register: ST swaps the chatMetadata object on every chat load —
       without this the tools keep their registration-time context (the
       previous chat) and silently write/read the wrong metadata. */
    registerCharacterStateTool();
    registerRelationshipTool();
    await ensureAllGroupCharacterStates();
    scheduleEventCardsResweep();
    createButton();
    refreshCsHud();
}, 500));

if (event_types?.GROUP_UPDATED) {
    eventSource.on(event_types.GROUP_UPDATED, () => setTimeout(async () => {
        await ensureAllGroupCharacterStates();
    }, 300));
}

setTimeout(async () => {
    clearCharacterStatePromptInjection();
    await ensureAllGroupCharacterStates();
    createButton();
}, 1000);

registerCsSlashCommand();

